} end)()
t.guides["groupe-alliance/01-depart-humain"] = (function() return {
		["\"Auntie\" Bernice Stonefield"] = "\"Tatie\" Bernice Stonefield",
		["Back south to the {object:93}, by the road to {zone:1436}. {npc:963} stands outside the barracks, {npc:955} beside him."] = "Retournez au sud vers le {object:93}, près de la route vers {zone:1436}. {npc:963} se tient devant la caserne, {npc:955} à côté de lui.",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "Retournez voir {npc:6122}. Utilisez l'{item:6928} sur le cercle d'invocation dans la cave de l'{object:2164} et vainquez le marcheur du Vide qu'elle appelle.",
		["Back to {zone:1429}"] = "Retour à {zone:1429}",
		["Billy plays in the Maclure Vineyards, east of the mine."] = "Billy joue dans les Vignobles Maclure, à l'est de la mine.",
		["Chunks of Boar Meat"] = "Morceaux de viande de sanglier",
		["Class trainer"] = "Maître de classe",
		["Crystal Kelp Fronds"] = "Feuilles de Varech cristallin",
		["Crystal Lake"] = "Lac de Cristal",
		["Crystal Lake: kill these as you meet them"] = "Lac de Cristal : tuez-les au fur et à mesure",
		["Defias Rogue Wizards camp on the shores of Stone Cairn Lake; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore."] = "Les sorciers-voleurs défias campent sur les rives du Lac du Cairn ; ils laissent aussi tomber les masques rouges en lin. Le {object:56} se trouve dans le village murloc sur la rive nord-est.",
		["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "Les Nervis défias campent dans la clairière à l'est de l'abbaye et le long du flanc est de la vallée.",
		["Druid trainer"] = "Maître des druides",
		["Echo Ridge Mine: kill these as you meet them"] = "Mine de la Crête aux échos : tuez-les au fur et à mesure",
		["Fargodeep Mine"] = "Mine de Fargodeep",
		["Follow the hills south to the tower, on the road west."] = "Suivez les collines vers le sud jusqu'à la tour, sur la route de l'ouest.",
		["Follow the hills south to the tower."] = "Suivez les collines vers le sud jusqu'à la tour.",
		["Follow the path north to the mine. Kobold Workers swarm outside it; every kobold in the valley can drop the {object:83763}."] = "Suivez le chemin vers le nord jusqu'à la mine. Les Ouvriers kobolds grouillent devant ; tous les kobolds de la vallée peuvent laisser tomber les {object:83763}.",
		["Follow the road east past the Tower of Azora to the bridge. Finish the Prowlers and Young Forest Bears around the river south of it."] = "Suivez la route vers l'est au-delà de la tour d'Azora jusqu'au pont. Terminez les rôdeurs et les jeunes ours des forêts autour de la rivière au sud de celui-ci.",
		["Follow the road north from Goldshire into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "Suivez la route vers le nord depuis Comté-de-l'Or jusqu'à {zone:1453}. {npc:5497} se trouve dans le Sanctuaire des mages, la tour du {object:2101} ; elle vous donne une fiole pour la cascade de {quest:1861}.",
		["Follow the road north from Goldshire into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "Suivez la route vers le nord depuis Comté-de-l'Or jusqu'à {zone:1453}. {npc:6122} attend dans la cave du {object:2164}, dans le {object:2101}.",
		["Follow the road south out of Goldshire to the Maclure Vineyards. {npc:251} waits by the house."] = "Suivez la route vers le sud depuis Comté-de-l'Or jusqu'aux Vignobles Maclure. {npc:251} attend près de la maison.",
		["Follow the road south out of the valley to Goldshire. {npc:295} is in the Lion's Pride Inn; {npc:240} stands outside the smithy across the road, {npc:253} at the inn's front and {npc:241} by the road south of it."] = "Suivez la route vers le sud pour sortir de la vallée et rejoindre Comté-de-l'Or. {npc:295} se trouve à l'Auberge de la Fière Lione ; {npc:240} attend devant la forge de l'autre côté de la route, {npc:253} devant l'auberge et {npc:241} sur la route au sud de celle-ci.",
		["Follow the road west back to Goldshire. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Suivez la route vers l'ouest pour retourner à Comté-de-l'Or. {npc:377} (prêtres), {npc:328} (mages) et {npc:917} (voleurs) se tiennent à l'étage de l'auberge : prenez l'escalier intérieur, la flèche ne distingue pas les étages.",
		["Follow the road west back to Goldshire; {npc:6306} and Jason stand on the lake shore before town. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Suivez la route vers l'ouest pour retourner à Comté-de-l'Or ; {npc:6306} et Jason se tiennent sur la rive du lac avant la ville. {npc:377} (prêtres), {npc:328} (mages) et {npc:917} (voleurs) se tiennent à l'étage de l'auberge : prenez l'escalier intérieur, la flèche ne distingue pas les étages.",
		["Follow the road west to the {object:93}, on the way into {zone:1436}. {npc:963} stands outside the barracks."] = "Suivez la route vers l'ouest jusqu'au {object:93}, sur le chemin menant à {zone:1436}. {npc:963} se tient devant la caserne.",
		["Forest's Edge"] = "La Lisière",
		["Fun with Elementals: {npc:248464}"] = "Les Joyeux Élémentaires : {npc:248464}",
		["Goldshire"] = "Comté-de-l'Or",
		["He stands by the river west of the farm."] = "Il se tient près de la rivière, à l'ouest de la ferme.",
		["Head back out through Goldshire and east along the road to the Brackwell Pumpkin Patch. {npc:881} (level 9) stands by its farmhouse."] = "Repartez par Comté-de-l'Or et prenez la route vers l'est jusqu'au Champ de potirons des Brackwell. {npc:881} (niveau 9) se tient près de sa ferme.",
		["If you skipped {quest:91740}, grind here to level 8.85 to stay on the route's plan."] = "Si vous avez passé {quest:91740}, tuez des monstres ici jusqu'au niveau 8.85 pour suivre le plan de l'itinéraire.",
		["If you skipped {quest:91752}, grind here to level 5.48 to stay on the route's plan."] = "Si vous avez passé {quest:91752}, tuez des monstres ici jusqu'au niveau 5.48 pour suivre le plan de l'itinéraire.",
		["If you skipped {quest:91752}, grind here to level 5.77 to stay on the route's plan."] = "Si vous avez passé {quest:91752}, tuez des monstres ici jusqu'au niveau 5.77 pour suivre le plan de l'itinéraire.",
		["If you skipped {quest:91775}, grind here to level 8.39 to stay on the route's plan."] = "Si vous avez passé {quest:91775}, tuez des monstres ici jusqu'au niveau 8.39 pour suivre le plan de l'itinéraire.",
		["Inside"] = "À l'intérieur",
		["Inside Echo Ridge Mine"] = "À l'intérieur de la Mine de la Crête aux échos",
		["It lies by the river north-west of the logging camp."] = "Il gît près de la rivière, au nord-ouest du camp de bûcherons.",
		["Jasperlode Mine"] = "Mine Veine-de-jaspe",
		["Jasperlode Mine: kill these as you meet them"] = "Mine Veine-de-jaspe : tuez-les au fur et à mesure",
		["Kobold Laborers work the tunnels inside the mine. {npc:248362} waits down the second turn on the right."] = "Les Travailleurs kobolds creusent les tunnels de la mine. {npc:248362} attend au fond du deuxième embranchement à droite.",
		["Large Candles"] = "Grandes bougies",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Quittez {zone:1453} par la porte principale. La cascade du {quest:1861} se trouve au sud-ouest des portes, sur le chemin de la {zone:1436} à l'ouest : remplissez la {item:7207} à son pied.",
		["Level 5.48"] = "Niveau 5.48",
		["Level 5.77"] = "Niveau 5.77",
		["Level 8.39"] = "Niveau 8.39",
		["Level 8.85"] = "Niveau 8.85",
		["Lost Books: Kobold Miners and Tunnelers"] = "Livres perdus : Mineurs kobolds et Tunneliers kobolds",
		["Mages: {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "Mages : {npc:198}, le maître des mages, se tient à l'étage de l'abbaye : prenez l'escalier intérieur, la flèche ne distingue pas les étages.",
		["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp."] = "Les Murlocs et les Ruisseliers murlocs occupent la rive est ; les Tas de camelote se trouvent dans leur camp.",
		["North-east of the logging camp. Defias Rogue Wizards camp on the shores of the lake."] = "Au nord-est du camp de bûcherons. Les Sorciers-voleurs défias campent sur les rives du lac.",
		["Painted Gnoll Armbands"] = "Brassards peints de gnoll",
		["Red Burlap Bandanas"] = "Masques rouges",
		["Red Linen Bandanas"] = "Masques rouges en lin",
		["Ridgepoint Tower"] = "Tour de la Crête",
		["Riverpaw Runts and Outrunners hold the hills south of the garrison, along the {zone:1436} border."] = "Des Rivepatte chétifs et des Estafettes Rivepatte tiennent les collines au sud de la garnison, le long de la frontière de {zone:1436}.",
		["Riverpaw gnolls camp in the hills west of Stone Cairn Lake; the {quest:91725} lie in their camps."] = "Les gnolls Rivepatte campent dans les collines à l'ouest du Lac du Cairn ; les {quest:91725} se trouvent dans leurs camps.",
		["Shaman trainer"] = "Maître des chamans",
		["She stands by her cart at the vineyard east of the Abbey."] = "Elle se tient près de sa charrette, dans la vigne à l'est de l'abbaye.",
		["She stands outside the mine entrance. {npc:248362}, inside, is elite: grouping up is advised."] = "Elle se tient devant l'entrée de la mine. {npc:248362}, à l'intérieur, est élite : il est conseillé de former un groupe.",
		["Shiny Red Apples, from {npc:894}, for the {quest:91736}"] = "Pommes rouges brillantes, auprès de {npc:894}, pour l'{quest:91736}",
		["Sit (/sit) by his campfire until you have Boosted Rest"] = "Asseyez-vous (/assis) près de son feu de camp jusqu'à obtenir Repos amélioré",
		["South down the road to the Maclure Vineyards."] = "Au sud sur la route vers les Vignobles Maclure.",
		["Start · Human: {zone:1429}"] = "Départ · Humain : {zone:1429}",
		["Stone Cairn Lake"] = "Lac du Cairn",
		["Subdue the voidwalker"] = "Soumettez le marcheur du Vide",
		["Summon Voidwalker"] = "Invocation d'un marcheur du Vide",
		["Tame Beast"] = "Apprivoiser une bête",
		["Tame {npc:1922}"] = "Apprivoisez : {npc:1922}",
		["Tame {npc:524}"] = "Apprivoisez : {npc:524}",
		["Tame {npc:822}"] = "Apprivoisez : {npc:822}",
		["The Defias camp"] = "Le camp défias",
		["The Fishing Traps sit along the west shore of the lake."] = "Les Pièges à poissons se trouvent le long de la rive ouest du lac.",
		["The Maclure Vineyards: kill these as you meet them"] = "Les vignes des Maclure : tuez-les au fur et à mesure",
		["The Stonefield Farm"] = "La ferme des Stonefield",
		["The Stonefield farm is west of the mine. Ma and \"Auntie\" Bernice stand by the house.\nShe sits inside the farmhouse."] = "La ferme des Stonefield se trouve à l'ouest de la mine. M'man et « Tantine » Bernice se tiennent près de la maison.\nElle est assise dans la ferme.",
		["The Tower of Azora"] = "La tour d'Azora",
		["The bridge"] = "Le pont",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it."] = "Le camp se trouve au nord-est du pont. Les Fagots de bois traînent autour du camp et dans les bois au nord de celui-ci.",
		["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "Les caisses de raisin se trouvent dans les vignes derrière les Défias. {npc:103} attend près de la cabane, au bout est de la vallée.",
		["The gnoll camps"] = "Les camps gnolls",
		["The kobold camp"] = "Le camp kobold",
		["The lake shore"] = "La rive du lac",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels."] = "La mine se trouve au sud-ouest des camps gnolls. Les {item:247816} traînent près de l'entrée ; les Géomanciens kobolds occupent les tunnels.",
		["The mine is west of the vineyards. Kobold Miners and Tunnelers fill both levels; {npc:248464}, a named kobold, holds the picture book in the lower tunnels. {npc:248464} is elite: grouping up is advised."] = "La mine se trouve à l'ouest des vignes. Les Mineurs kobolds et les Tunneliers kobolds occupent les deux niveaux ; {npc:248464}, un kobold nommé, détient le livre d'images dans les tunnels inférieurs. {npc:248464} est élite : il est conseillé de former un groupe.",
		["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the Tower of Azora; Prowlers further east give pelts too."] = "Les murlocs de la rive est laissent tomber le varech. Dépeceurs : les loups forestiers gris rôdent dans les bois entre le lac et la Tour d'Azora ; les rôdeurs plus à l'est donnent aussi des peaux.",
		["The vineyards and {npc:103}"] = "Les vignes et {npc:103}",
		["The {item:247813}, Axe and Toolbox lie in the river south of the bridge. {npc:330}, a big boar, roots in the Brackwell Pumpkin Patch west of the river with her {npc:390}: pull the piglets away first. Kill Prowlers and Young Forest Bears on the way. Careful: {npc:248278} is a level 11 elite on the murloc shore. Only go for his head with a group or once you're level 10; otherwise leave him: it's optional."] = "Le {item:247813}, la hache et la boîte à outils gisent dans la rivière au sud du pont. {npc:330}, un gros sanglier, fouit dans le Champ de potirons des Brackwell à l'ouest de la rivière avec son {npc:390} : éloignez d'abord les marcassins. Tuez les rôdeurs et les jeunes ours des forêts sur le chemin. Attention : {npc:248278} est un élite de niveau 11 sur la rive des murlocs. Ne l'affrontez qu'en groupe ou une fois niveau 10 ; sinon laissez-le : c'est optionnel.",
		["The {object:95}"] = "Le {object:95}",
		["The {quest:91736}"] = "L'{quest:91736}",
		["The {quest:91736} stands north of the {object:93}. Click it with four Shiny Red Apples in your bags: it takes them and gives you a {item:247824} on the spot (the quest never shows in your quest log). Keep the Applejack for {npc:955}: don't drink it."] = "Le {quest:91736} se trouve au nord du {object:93}. Cliquez dessus avec quatre pommes rouges brillantes dans vos sacs : il les prend et vous donne un {item:247824} sur place (la quête n'apparaît jamais dans votre journal). Gardez l'applejack pour {npc:955} : ne le buvez pas.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:248362} (level 3 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:248362} (élite de niveau 3) demande un groupe de 2. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:248464} (level 6 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:248464} (élite de niveau 6) demande un groupe de 2. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:91740} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {quest:91740} demande un groupe de 2. Passez-la si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["Walk into the mine"] = "Entrez dans la mine",
		["Walk through the mine"] = "Traversez la mine",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Pendant que vous y êtes : apprenez le maniement des bâtons auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; un bâton apporte plus de caractéristiques de sorts qu'une arme à une main pendant la progression.",
		["Wolves"] = "Loups",
		["You start in front of the Abbey. {npc:823} stands at the foot of the steps, {npc:197} inside the hall, {npc:951} and {npc:247229} in the library to the right, {npc:196} outside the north-west corner."] = "Vous commencez devant l'abbaye. {npc:823} se tient au pied des marches, {npc:197} dans la grande salle, {npc:951} et {npc:247229} dans la bibliothèque à droite, {npc:196} dehors, à l'angle nord-ouest.",
		["Young Wolves and Timber Wolves roam the fields right around the Abbey."] = "Les Jeunes loups et les Loups des bois rôdent dans les champs tout autour de l'abbaye.",
		["grind on {npc:118}"] = "tuez en boucle : {npc:118}",
		["grind on {npc:40}"] = "tuez en boucle : {npc:40}",
		["grind on {npc:80}"] = "tuez en boucle : {npc:80}",
		["his kobold tracker shows the kobolds to click on the road to Goldshire"] = "Son traqueur de kobolds indique les kobolds sur lesquels cliquer sur la route vers Comté-de-l'Or",
		["{item:247824}, from the still"] = "{item:247824}, de l'alambic",
		["{item:286214} on the way"] = "{item:286214} en chemin",
		["{item:286215}: Stonetusk Boars"] = "{item:286215} : Sangliers Brocheroc",
		["{item:6785}: the {object:83763} in the Defias camp"] = "{item:6785} : les {object:83763} dans le camp défias",
		["{item:981}; below ground"] = "{item:981} ; sous terre",
		["{npc:118} on the way"] = "{npc:118} en chemin",
		["{npc:1430} cooks in the inn's kitchen. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:1430} cuisine dans la cuisine de l'auberge. {npc:377} (prêtres), {npc:328} (mages) et {npc:917} (voleurs) se tiennent à l'étage de l'auberge : prenez l'escalier intérieur, la flèche ne distingue pas les étages.",
		["{npc:1430}: Camping 101 asks you to learn it; below ground"] = "{npc:1430} : Camping 101 vous demande de l'apprendre ; sous terre",
		["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922} : apprivoisez-le avec le {item:15908}",
		["{npc:197}, inside"] = "{npc:197}, à l'intérieur",
		["{npc:198}, the mage trainer, inside the Abbey"] = "{npc:198}, le maître des mages, dans l'abbaye",
		["{npc:240}, while William brews"] = "{npc:240}, pendant que William prépare la potion",
		["{npc:247229}, in the library; inside"] = "{npc:247229}, dans la bibliothèque ; à l'intérieur",
		["{npc:248242} and {npc:248248} stand at the foot of the tower."] = "{npc:248242} et {npc:248248} se tiennent au pied de la tour.",
		["{npc:248415} stands behind the Abbey, by the stables. {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:248415} se tient derrière l'abbaye, près des écuries. {npc:198}, le maître des mages, se tient à l'étage de l'abbaye : prenez l'escalier intérieur, la flèche ne distingue pas les étages.",
		["{npc:248415}, by the Abbey"] = "{npc:248415}, près de l'abbaye",
		["{npc:251507} stands with the Goldshire trainers. Each of her quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her. Rockhide Boars and Young Forest Bears roam the hills south of the Maclure Vineyards, Gray Forest Wolves the woods east of Crystal Lake."] = "{npc:251507} se tient avec les maîtres de Comté-de-l'Or. Chacune de ses quêtes vous donne un {item:15908} : utilisez-le sur la bête qu'elle désigne, puis rapportez-lui la baguette. Les sangliers Rochecuir et les jeunes ours des forêts rôdent dans les collines au sud des vignes des Maclure, les loups forestiers gris dans les bois à l'est du Lac de Cristal.",
		["{npc:253}, inside"] = "{npc:253}, à l'intérieur",
		["{npc:257446} in {zone:1426}; Goldshire has no shaman trainer"] = "{npc:257446} dans {zone:1426} ; Comté-de-l'Or n'a pas de maître des chamans",
		["{npc:258930}, beside her: Beast Training"] = "{npc:258930}, à côté d'elle : Dressage de bête",
		["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it."] = "{npc:261} garde le pont sur la route de l'est ; {npc:248265} se tient juste de l'autre côté.",
		["{npc:263399} camps north-east of the inn; {npc:6306}, {npc:383} and {npc:1651} stand on the shore of Crystal Lake east of town."] = "{npc:263399} campe au nord-est de l'auberge ; {npc:6306}, {npc:383} et {npc:1651} se tiennent sur la rive du Lac de Cristal à l'est de la ville.",
		["{npc:278}, inside"] = "{npc:278}, à l'intérieur",
		["{npc:279} in {zone:1453} takes it (02-westfall)"] = "{npc:279} à {zone:1453} la reçoit (02-westfall)",
		["{npc:295}, inside"] = "{npc:295}, à l'intérieur",
		["{npc:328}: {npc:5497} in {zone:1453} takes it"] = "{npc:328} : {npc:5497} à {zone:1453} la reçoit",
		["{npc:375}, the priest trainer"] = "{npc:375}, la maîtresse des prêtres",
		["{npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:377} (prêtres), {npc:328} (mages) et {npc:917} (voleurs) se tiennent à l'étage de l'auberge : prenez l'escalier intérieur, la flèche ne distingue pas les étages.",
		["{npc:377}: {npc:376} in {zone:1453} takes it"] = "{npc:377} : {npc:376} dans {zone:1453} le récupère",
		["{npc:459}, outside the Abbey"] = "{npc:459}, devant l'abbaye",
		["{npc:459}: Summon Imp"] = "{npc:459} : Invocation d'un diablotin",
		["{npc:476} walks around Jasperlode Mine: look inside the circle on the map"] = "{npc:476} rôde autour de la Mine Veine-de-jaspe : regardez à l'intérieur du cercle sur la carte",
		["{npc:524}: tame it with the {item:15908}"] = "{npc:524} : apprivoisez-le avec le {item:15908}",
		["{npc:5504} in {zone:1453}; Goldshire has no druid trainer"] = "{npc:5504} à {zone:1453} ; Comté-de-l'Or n'a pas de maître des druides",
		["{npc:6121}: {npc:6122} in {zone:1453} takes it"] = "{npc:6121} : {npc:6122} à {zone:1453} la reçoit",
		["{npc:6306}, inside"] = "{npc:6306}, à l'intérieur",
		["{npc:6306}: skinners only, the pelts are skinned; inside"] = "{npc:6306} : dépeceurs seulement, les peaux se dépècent ; à l'intérieur",
		["{npc:6774}, by the stables south of the Abbey"] = "{npc:6774}, près des écuries au sud de l'abbaye",
		["{npc:6} dig in the vineyards north-east of the Abbey. Now and then one drops a {quest:91741}: right-click it."] = "Les {npc:6} creusent dans les vignes au nord-est de l'abbaye. De temps en temps, l'une d'elles laisse tomber un {quest:91741} : faites un clic droit dessus.",
		["{npc:80} walks around Echo Ridge Mine: look inside the circle on the map"] = "{npc:80} rôde autour de la Mine de la Crête aux échos : regardez à l'intérieur du cercle sur la carte",
		["{npc:822}: tame it with the {item:15908}"] = "{npc:822} : apprivoisez-le avec le {item:15908}",
		["{npc:823}, back at the Abbey steps"] = "{npc:823}, de retour au pied des marches de l'abbaye",
		["{npc:894} sells the Shiny Red Apples for the {quest:91736}. Apples looted from kobolds and crates count too: the purchase ticks itself once you have four."] = "{npc:894} vend les Pommes rouges brillantes pour l'{quest:91736}. Les pommes ramassées sur les kobolds et dans les caisses comptent aussi : l'achat se coche tout seul dès que vous en avez quatre.",
		["{npc:911}, the warrior trainer; inside"] = "{npc:911}, le maître des guerriers ; à l'intérieur",
		["{npc:915}, the rogue trainer"] = "{npc:915}, le maître des voleurs",
		["{npc:925}, the paladin trainer"] = "{npc:925}, le maître des paladins",
		["{npc:952}, upstairs"] = "{npc:952}, à l'étage",
		["{npc:955} stands inside the barracks. He has {quest:91738} only while you carry the {item:247824}: talk to him and it goes straight to the hand-in."] = "{npc:955} se tient dans la caserne. Il ne propose {quest:91738} que si vous avez le {item:247824} sur vous : parlez-lui et vous passez directement à la remise.",
		["{npc:955}: he wants your {item:247824}; inside"] = "{npc:955} : il veut votre {item:247824} ; à l'intérieur",
		["{npc:963}: for {npc:234} at {object:81}"] = "{npc:963} : pour {npc:234} au {object:81}",
		["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood.\nStonetusk Boars graze between the vineyards and the farm."] = "L'{object:694855} pousse dans les champs autour des vignes et de la ferme des Stonefield ; les Sangliers Brocheroc des environs fournissent le sang.\nLes Sangliers Brocheroc paissent entre les vignes et la ferme.",
		["{quest:76}'s entrance"] = "Entrée de {quest:76}",
		["{quest:87} is inside the Fargodeep Mine, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it."] = "{quest:87} se trouve à l'intérieur de la mine de Fargodeep, pas sur la colline au-dessus : entrez par l'entrée et restez à gauche jusqu'au fond de la mine ; n'empruntez pas les escaliers. Les bandits défias autour des vignobles laissent parfois tomber un {item:1972} : faites un clic droit dessus.",
		["{quest:91733} and {npc:330}"] = "{quest:91733} et {npc:330}",
		["{zone:1429}: kill these as you meet them"] = "{zone:1429} : tuez-les au fur et à mesure",
} end)()
t.guides["groupe-alliance/01-depart-nain"] = (function() return {
		["Amberstill Ranch"] = "Ferme des Amberstill",
		["Anvilmar"] = "Courbenclume",
		["Back east through Kharanos: the class quests here wait for level 10."] = "De retour vers l'est par Kharanos : les quêtes de classe ici attendent le niveau 10.",
		["Back through the tunnel to {npc:257597}' cave above the farm."] = "Repassez le tunnel jusqu'à la grotte de {npc:257597}, au-dessus de la ferme.",
		["Back to Anvilmar"] = "Retour à Courbenclume",
		["Back to {npc:257446} in Anvilmar. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "Retournez voir {npc:257446} à Courbenclume. Il vous donne le {item:6635} : prenez le chemin marqué de débris qui monte vers l'ouest depuis le sud de la vallée jusqu'à la Pierre des esprits sur la crête, buvez la Sapta à côté et parlez au {npc:5891}, puis rapportez son {item:6656} à Teo.",
		["Back to {npc:257597}"] = "Retour auprès de {npc:257597}",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {zone:1436} is next, west of Goldshire."] = "Retournez voir {npc:6122}. Utilisez l'{item:6928} au cercle d'invocation dans la cave de {object:2164} et vainquez le marcheur du Vide qu'il invoque. {zone:1436} est la suite, à l'ouest de Comté-de-l'Or.",
		["Below ground"] = "Sous terre",
		["Brewnall Village"] = "Brassetout",
		["Brewnall Village sits on the lake west of Kharanos. {npc:8508}'s dock is the first stop; {npc:1374} and {npc:1375} are in the village beyond it."] = "Brassetout se trouve sur le lac à l'ouest de Kharanos. Le quai de {npc:8508} est le premier arrêt ; {npc:1374} et {npc:1375} sont dans le village au-delà.",
		["Class trainer"] = "Maître de classe",
		["Coldridge Valley: kill these as you meet them"] = "Vallée des Frigères : tuez-les au fur et à mesure",
		["Crag Boars and Young Black Bears roam the fields around Kharanos and the depot."] = "Les sangliers des rochers et les jeunes ours noirs errent dans les champs autour de Kharanos et du dépôt.",
		["Deeprun Tram"] = "Tram des profondeurs",
		["Defensive Stance"] = "Posture défensive",
		["Druid trainer"] = "Maître des druides",
		["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the Kharanos smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of Kharanos."] = "Chaque quête de Grif Cœur-Sauvage vous donne un {item:15908} : utilisez-le sur la bête qu'il nomme, puis rapportez la baguette à la forge de Kharanos. Les grands sangliers des rochers, léopards des neiges et ours griffeglace errent tous dans les champs juste au sud et à l'est de Kharanos.",
		["Farsen camps on the ridge overlooking the {object:149024} from the west. Talk to him for his farsight."] = "Farsen campe sur la crête surplombant le {object:149024} depuis l'ouest. Parlez-lui pour sa clairvoyance.",
		["Feather Charms, from the Frostmane Novices"] = "Charmes de plume, sur les Novices Frostmane",
		["Firewood"] = "Bois de chauffage",
		["Flintfire's shipments lie on the cave floor, and {npc:278166} is missing somewhere inside.\nCareful: Wendigos stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks from outside avoids this."] = "Les cargaisons de Flintfire gisent au sol de la caverne, et {npc:278166} a disparu quelque part à l'intérieur.\nAttention : les wendigos sont serrés à l'intérieur de la caverne, donc les combats attirent facilement plusieurs ennemis à la fois ; les attirer un par un avec des attaques à distance depuis l'extérieur évite cela.",
		["Follow the road all the way east to the South Gate Outpost at the {zone:1432} tunnel."] = "Suivez la route jusqu'au bout vers l'est jusqu'à l'Avant-poste de la porte Sud au tunnel de {zone:1432}.",
		["Follow the road east past the depot to Misty Pine Refuge."] = "Suivez la route vers l'est au-delà du dépôt jusqu'au Refuge de Brumepins.",
		["Follow the road north-east from Kharanos to the depot below the {zone:1455} road."] = "Suivez la route au nord-est depuis Kharanos jusqu'au dépôt sous la route de {zone:1455}.",
		["Follow the road north-east from Kharanos to the depot: the whole east of {zone:1426} is one sweep from here."] = "Suivez la route au nord-est depuis Kharanos jusqu'au dépôt : tout l'est de {zone:1426} se fait en un seul passage depuis ici.",
		["Follow the road through the tunnel and north-east to Kharanos. Start outside: {npc:1252} and Eric's campfire are in front of the Thunderbrew Distillery."] = "Suivez la route à travers le tunnel et au nord-est jusqu'à Kharanos. Commencez à l'extérieur : {npc:1252} et le feu de camp d'Eric sont devant la Distillerie Thunderbrew.",
		["Follow the road up to {zone:1455} and take the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, {npc:6179} and {npc:6178} on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {zone:1426} drop it, and the Auction House sells it."] = "Suivez la route jusqu'à {zone:1455} et prenez le {object:32362} : {npc:5149}, {npc:6179} et {npc:6178} sont dans le {object:32386}, {npc:6179} et {npc:6178} à l'étage supérieur : l'escalier commence juste au nord-est de {npc:5149}. {npc:6175}, un mendiant, erre dans la ville. Il demande dix {item:2589} : les troggs et trolls de {zone:1426} en laissent tomber, et l'Hôtel des ventes en vend.",
		["Follow the road up to {zone:1455} and train with your class trainer. The Deeprun Tram leaves from {object:171524}, in the east of the city. Ride it to {zone:1453}."] = "Suivez la route jusqu'à {zone:1455} et entraînez-vous avec votre maître de classe. Le Tram des profondeurs part de {object:171524}, à l'est de la ville. Prenez-le pour {zone:1453}.",
		["From the {quest:2997} she gives you"] = "Grâce à {quest:2997} qu'elle vous donne",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "Des Jeunes trolls Frostmane ({npc:706}) peuplent les pentes au sud et à l'est du camp de {npc:786}.",
		["Gnomeregan: kill these as you meet them"] = "Gnomeregan : tuez-les au fur et à mesure que vous les rencontrez",
		["Go through the tunnel into {zone:1432}. Just past it, a path marked by stones climbs the hills on the right of the road north to {npc:257808}'s camp."] = "Traversez le tunnel pour entrer dans {zone:1432}. Juste après, un chemin marqué de pierres gravit les collines à droite de la route vers le nord jusqu'au camp de {npc:257808}.",
		["Gretchen camps just outside the Grizzled Den, the wendigo cave south-west of Kharanos."] = "Gretchen campe juste à l'extérieur de la Tanière Grisonnante, la caverne des wendigos au sud-ouest de Kharanos.",
		["Head back out of {zone:1455} and east along the road to Helm's Bed Lake. {npc:6177} lies dead by its shore: use the {item:6866} on him. The Dark Iron Spies sneaking around the lake carry the script."] = "Sortez de {zone:1455} et allez vers l'est le long de la route jusqu'au Lac du Lit d'Helm. {npc:6177} gît mort sur sa rive : utilisez l'{item:6866} sur lui. Les Espions Sombrefer qui rôdent autour du lac portent le script.",
		["Helm's Bed Lake"] = "Lac du Lit d'Helm",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "Pendentifs d'ours griffeglace ({item:264356}), sur les Jeunes trolls Frostmane ({npc:706}) des pentes au-dessus du camp",
		["If you skipped {quest:314}, grind here to level 11.6 to stay on the route's plan."] = "Si vous avez passé {quest:314}, tuez des monstres ici jusqu'au niveau 11.6 pour suivre le plan de l'itinéraire.",
		["Inn and flight master"] = "Auberge et maître de vol",
		["Inside Anvilmar"] = "À l'intérieur de Courbenclume",
		["Instead of walking back up to {zone:1455}, go east through the South Gate tunnel into {zone:1432} and follow the road north to Thelsamar. {npc:1681} stands on the east side of town, past the Stoutlager Inn; his errand pays for a flight back to {zone:1455}."] = "Au lieu de remonter à pied vers {zone:1455}, allez vers l'est par le tunnel de la porte Sud jusqu'à {zone:1432} et suivez la route vers le nord jusqu'à Thelsamar. {npc:1681} se trouve du côté est de la ville, après l'Auberge de la Fortebière ; sa commission paye un vol de retour vers {zone:1455}.",
		["Kharanos"] = "Kharanos",
		["Kharanos and the depot"] = "Kharanos et le dépôt",
		["Kill the Crag Boars on the way: their ribs drop before you have {npc:1267}'s quest and count toward it. Back in the distillery: {npc:1699} teaches {skill:185}, then the ribs go to {npc:1267}."] = "Tuez les Sangliers des rochers en chemin : leurs côtes tombent avant que vous ayez la quête de {npc:1267} et comptent pour elle. De retour à la brasserie : {npc:1699} enseigne la {skill:185}, puis les côtes vont à {npc:1267}.",
		["Last: some classes' trainers stand outside"] = "Pour finir : les maîtres de certaines classes se tiennent dehors",
		["Leave {zone:1453} by the main gate, go south to Goldshire and east along the road to the Brackwell Pumpkin Patch. {npc:881} (level 9) stands by its farmhouse."] = "Quittez {zone:1453} par la porte principale, allez au sud jusqu'à Comté-de-l'Or et vers l'est le long de la route jusqu'au Champ de potirons des Brackwell. {npc:881} (niveau 9) se tient près de sa ferme.",
		["Leper Gnomes around Brewnall and the Gnomeregan road carry the cogs and gears. Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake."] = "Les gnomes lépreux autour de Brassetout et sur la route de Gnomeregan portent les engrenages et les rouages. Les ours griffeglace, anciens sangliers des rochers et léopards des neiges errent dans les collines autour du lac.",
		["Level 11.6"] = "Niveau 11.6",
		["Level 4 spells, before Gozwin's camp"] = "Sorts du niveau 4, avant le camp de Gozwin",
		["Misty Pine Refuge"] = "Refuge de Brumepins",
		["Misty Pine Refuge: kill these as you meet them"] = "Refuge de Brumepins : tuez-les au fur et à mesure que vous les rencontrez",
		["North Gate Outpost"] = "Avant-poste de la porte Nord",
		["On the road back west to {zone:1455}."] = "Sur la route du retour vers l'ouest, vers {zone:1455}.",
		["On the way"] = "En chemin",
		["Ragged Young Wolves roam the snow just south of Anvilmar."] = "Les jeunes loups décharnés rôdent dans la neige juste au sud de Courbenclume.",
		["Rockjaw Ambushers by Helm's Bed Lake, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Rockjaw Bonesnappers prowl the quarry and the lake; Dark Iron Spies sneak around the lake shore. One spy drops the {item:274268}."] = "Les Embusqués Mâcheroc au Lac du Lit d'Helm, au nord de la carrière, et les Brise-dos Mâcheroc plus à l'est laissent tomber le {quest:95214}. Les Briseurs d'os Mâcheroc rôdent dans la carrière et le lac ; les Espions Sombrefer rôdent sur la rive du lac. Un espion laisse tomber le {item:274268}.",
		["Rockjaw Skullthumpers fill the quarry; Rockjaw Ambushers by Helm's Bed Lake drop the {item:268548}."] = "Les Brise-crâne Mâcheroc remplissent la carrière ; les Embusqués Mâcheroc au Lac du Lit d'Helm laissent tomber le {item:268548}.",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of Anvilmar."] = "Les troggs Mâcheroc et les troggs Mâcheroc forcenés fouillent tout le fond de la vallée au sud de Courbenclume.",
		["Sit by Eric's campfire (type /sit) and wait for the buff."] = "Asseyez-vous près du feu de camp d'Eric (tapez /asseoir) et attendez l'amélioration.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "Les Petits sangliers des rochers paissent autour du camp de {npc:714} et le long du côté ouest de la vallée.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "Les Léopards des neiges et les sangliers parcourent la neige entre la ferme et la carrière. Forgerons : les Barres de cuivre s'obtiennent en fondant du {item:2770} ou auprès des marchands d'artisanat.",
		["South Gate Outpost"] = "Avant-poste de la porte Sud",
		["Start · Dwarf: {zone:1426}"] = "Départ · Nain : {zone:1426}",
		["Steelgrill's Depot"] = "Dépôt de Steelgrill",
		["Stonesplinter Seers (level 13) stand among the troggs in the south of Stonesplinter Valley, south of {npc:257808}; Tunnel Rat Geomancers (level 12) work the Silver Stream Mine at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time."] = "Les Prophètes Brisepierre (niveau 13) se tiennent parmi les troggs au sud de la Vallée des Brisepierre, au sud de {npc:257808} ; les Géomanciens Rat des tunnels (niveau 12) travaillent à la Mine du Ru d'argent à l'extrémité nord du loch. Les troggs arrivent en groupes et certains lancent à distance : tirez-les un par un.",
		["Subdue the voidwalker"] = "Soumettez le marcheur du Vide",
		["Summon Voidwalker"] = "Invocation d'un marcheur du Vide",
		["Talk to the scout at {quest:96392}"] = "Parlez à l'éclaireur pour {quest:96392}",
		["Tame Beast"] = "Apprivoiser une bête",
		["Tame {npc:1126}"] = "Apprivoisez {npc:1126}",
		["Tame {npc:1196}"] = "Apprivoisez {npc:1196}",
		["Tame {npc:1201}"] = "Apprivoisez {npc:1201}",
		["The Deeprun Tram"] = "Le Tram des profondeurs",
		["The Fire Spirit Stone"] = "La pierre de l'esprit du feu",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside Anvilmar."] = "Le Thé brûlant de Durnan dure cinq minutes : allez tout droit au nord vers {npc:836} à l'intérieur de Courbenclume.",
		["The boars"] = "Les sangliers",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "Le bois de chauffage est dans la neige autour du lac gelé, près du refuge.",
		["The quarry lies just east of Farsen's ridge."] = "La carrière se trouve juste à l'est de la crête de Farsen.",
		["The quarry troggs"] = "Les troggs de la carrière",
		["The three rifles lie in the snow around the frozen lake by the refuge. Minor Ice Elementals drift around the lake and along the way: kill them as you go for {quest:99160}.\nFinish off the Minor Ice Elementals around the small lake just west of the refuge if you are still short."] = "Les trois fusils reposent dans la neige autour du lac gelé près du refuge. Des Élémentaires de glace mineurs dérivent autour du lac et le long du chemin : tuez-les en passant pour {quest:99160}.\nAchevez les Élémentaires de glace mineurs autour du petit lac juste à l'ouest du refuge s'il vous en manque encore.",
		["The tram arrives in the {object:28027}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug."] = "Le tram arrive dans {object:28027}. {npc:5480} entraîne les guerriers dans {object:2100} ; {npc:6089} et {npc:6090} s'y tiennent ensemble près de {object:2152}. {npc:6090} vous affronte pour sa chope.",
		["The troggs"] = "Les troggs",
		["The troll cave"] = "La grotte des trolls",
		["The tunnel"] = "Le tunnel",
		["The {item:2676} grows in baskets up on Shimmer Ridge, the snowy slope north of the road between Kharanos and Brewnall: climb from the road west of Kharanos. The Frostmane Seers camped on the ridge drop it too."] = "Le {item:2676} pousse dans des paniers sur la Crête scintillante, la pente enneigée au nord de la route entre Kharanos et Brassetout : grimpez depuis la route à l'ouest de Kharanos. Les prophètes Frostmane campés sur la crête en font aussi tomber.",
		["The {object:176785} sits next to {npc:271546}, south of the Grizzled Den."] = "Le {object:176785} se trouve à côté de {npc:271546}, au sud de la Tanière Grisonnante.",
		["The {object:269} in the basement"] = "{object:269}, au sous-sol",
		["The {object:270} in the distillery; below ground"] = "Le {object:270} dans la brasserie ; sous terre",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:1388} is a level 12 elite: most classes solo it at level 14, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:1388} est un élite de niveau 12 : la plupart des classes le battent seules au niveau 14, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["Thunderbrew Distillery"] = "Distillerie Thunderbrew",
		["Tram to {zone:1453}"] = "Tram pour {zone:1453}",
		["Upstairs"] = "À l'étage",
		["Use the {item:6866} on {npc:6177}"] = "Utilisez {item:6866} sur {npc:6177}",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Pendant que vous y êtes : apprenez le maniement des bâtons auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; l'arme de mêlée d'un Chasseur vaut surtout par ses caractéristiques, et les armes à deux mains en portent le plus.",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Pendant que vous y êtes : apprenez le maniement des bâtons auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; un bâton apporte plus de caractéristiques de sorts qu'une arme à une main pendant la progression.",
		["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Pendant que vous y êtes : apprenez le maniement des épées auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; une épée en main droite fait progresser un Voleur régulièrement.",
		["While you're here: learn Two-Handed Axes from {npc:11865} ({object:32359}, 10 silver); two-handers level a Paladin fastest."] = "Pendant que vous êtes ici : apprenez Haches à deux mains auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font monter un paladin le plus vite.",
		["While you're here: learn Two-Handed Axes from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "Pendant que vous êtes ici : apprenez Haches à deux mains auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
		["While you're here: learn Two-Handed Maces from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "Pendant que vous êtes ici : apprenez Masses à deux mains auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
		["While you're here: learn Two-Handed Swords from {npc:11867} ({object:2096}, 10 silver); two-handers level a Paladin fastest."] = "Pendant que vous êtes ici : apprenez Épées à deux mains auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; les armes à deux mains font monter un paladin le plus vite.",
		["While you're here: learn Two-Handed Swords from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Pendant que vous êtes ici : apprenez Épées à deux mains auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
		["You start in front of Anvilmar, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "Vous commencez devant Courbenclume, la salle de pierre au nord de la vallée. {npc:658} attend devant la porte.",
