		["{npc:1241}, below ground"] = "{npc:1241}, sous terre",
		["{npc:1243} camps south-west of it, by the road to Coldridge."] = "{npc:1243} campe au sud-ouest, près de la route vers les Frigères.",
		["{npc:1252}: {npc:1274} in {zone:1455} takes it"] = "{npc:1252} : {npc:1274}, à {zone:1455}, la prend",
		["{npc:1266} camps in Chill Breeze Valley, south of the road back east from Brewnall to Kharanos. His meats are in the locker in {npc:1271}'s cave, east of his camp. {npc:1271} is an elite yeti: wait out of sight until he wanders off on his patrol, then take the meats and leave before he comes back. You don't need to fight him."] = "{npc:1266} campe dans la Vallée de la bise, au sud de la route du retour vers l'est de Brassetout à Kharanos. Ses viandes sont dans le coffre de la caverne de {npc:1271}, à l'est de son camp. {npc:1271} est un yéti élite : restez hors de vue jusqu'à ce qu'il s'éloigne en patrouille, puis prenez les viandes et partez avant qu'il ne revienne. Vous n'avez pas besoin de le combattre.",
		["{npc:1269}, below ground"] = "{npc:1269}, sous terre",
		["{npc:1269}, by the depot; below ground"] = "{npc:1269}, près du dépôt ; sous terre",
		["{npc:12738}, next to him"] = "{npc:12738}, à côté de lui",
		["{npc:12738}: timed, five minutes to reach {npc:836} in Anvilmar"] = "{npc:12738} : chronométré, cinq minutes pour rejoindre {npc:836} à Courbenclume",
		["{npc:1274}, in the {object:171709} with King Magni"] = "{npc:1274}, au {object:171709} avec le roi Magni",
		["{npc:1373} guards the {item:2686} barrels in the distillery basement. Buy a {item:2686} from {npc:1247}, click the guarded barrel, then hand the ale to {npc:1373} from his quest window (there is no quest to accept); after that, the unguarded barrel takes the Barleybrew Scalder."] = "{npc:1373} garde les tonneaux de {item:2686} dans le sous-sol de la distillerie. Achetez un {item:2686} auprès de {npc:1247}, cliquez sur le tonneau gardé, puis donnez la bière à {npc:1373} via sa fenêtre de quête (il n'y a pas de quête à accepter) ; ensuite, le tonneau non gardé prend le Brûleur d'orge.",
		["{npc:1373}, beside the barrel; below ground"] = "{npc:1373}, à côté du tonneau ; sous terre",
		["{npc:1377}, at the depot"] = "{npc:1377}, au dépôt",
		["{npc:1572}, the gryphon master"] = "{npc:1572}, le maître des griffons",
		["{npc:1573}, the gryphon master where you landed"] = "{npc:1573}, le maître des griffons là où vous avez atterri",
		["{npc:1694}, beside him"] = "{npc:1694}, à côté de lui",
		["{npc:1698}: blacksmiths only"] = "{npc:1698} : forgerons uniquement",
		["{npc:1699}: Camping 101 asks you to learn it; below ground"] = "{npc:1699} : Camping 101 vous demande de l'apprendre ; sous terre",
		["{npc:1872} works the forge west of the distillery.\nThen go in: {npc:6806}, the innkeeper, {npc:1226} and {npc:1267}. {npc:1699}'s {skill:185} lesson waits for the return with the ribs, when the copper is there for it."] = "{npc:1872} travaille à la forge à l'ouest de la brasserie.\nEntrez ensuite : {npc:6806}, l'aubergiste, {npc:1226} et {npc:1267}. La leçon de {skill:185} de {npc:1699} attend le retour avec les côtes, quand vous aurez le cuivre nécessaire.",
		["{npc:1960} waits at the North Gate Outpost, north of the South Gate; the dwarven corpse lies up the pass to the west of him."] = "{npc:1960} attend à l'Avant-poste de la porte Nord, au nord de la porte Sud ; le cadavre nain gît dans le col à l'ouest de lui.",
		["{npc:1965} guards the tunnel out of the valley, east of Anvilmar; {npc:6782} stands beside him at its mouth."] = "{npc:1965} garde le tunnel sortant de la vallée, à l'est de Courbenclume ; {npc:6782} se tient à côté de lui à son entrée.",
		["{npc:1977}, in the quarry"] = "{npc:1977}, dans la carrière",
		["{npc:257446}, inside Anvilmar"] = "{npc:257446}, à l'intérieur de Courbenclume",
		["{npc:257446}: {npc:5873} and your {item:5175}"] = "{npc:257446} : {npc:5873} et votre {item:5175}",
		["{npc:257597} waits in a cave above the farm north-west of the South Gate Outpost; the path up starts behind the farm."] = "{npc:257597} attend dans une caverne au-dessus de la ferme au nord-ouest de l'Avant-poste de la porte Sud ; le sentier montant commence derrière la ferme.",
		["{npc:257597}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:257597} : {npc:2523}, votre {item:5176} et {item:263412}",
		["{npc:257808} gives you the {item:6636}. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the {npc:5893}, then place its {item:6655} in the {object:61934}, atop the Shrine of Eternal Flame."] = "{npc:257808} vous donne {item:6636}. Montez au sommet au-dessus de son camp, buvez le Sapta à côté de la Pierre de l'esprit et vainquez {npc:5893}, puis placez son {item:6655} dans {object:61934}, au sommet de l'autel de la Flamme éternelle.",
		["{npc:258098}, the shaman trainer, north of the {object:32372}"] = "{npc:258098}, le maître des chamans, au nord de {object:32372}",
		["{npc:258113}: {npc:257597} by the South Gate takes it"] = "{npc:258113} : à rendre à {npc:257597}, près de la porte Sud",
		["{npc:2756} stands by {npc:8416} at the door of Anvilmar. Gozwin's camp is in the hills just north-west; the {npc:269075} prowls around it."] = "{npc:2756} se tient près de {npc:8416} à la porte de Courbenclume. Le camp de Gozwin est dans les collines juste au nord-ouest ; le {npc:269075} rôde autour.",
		["{npc:2756}, inside"] = "{npc:2756}, à l'intérieur",
		["{npc:276003} along the way to {npc:1253}"] = "{npc:276003} sur le chemin de {npc:1253}",
		["{npc:276003} on the way"] = "{npc:276003} en chemin",
		["{npc:276003}, around the small lake"] = "{npc:276003}, autour du petit lac",
		["{npc:376} is in the Cathedral of Light."] = "{npc:376} se trouve dans la cathédrale de la Lumière.",
		["{npc:4256}, in the {object:32372}"] = "{npc:4256}, à la {object:32372}",
		["{npc:460}, inside Anvilmar"] = "{npc:460}, à l'intérieur de Courbenclume",
