		["{npc:658}: a rune for {npc:895}"] = "{npc:658} : une rune pour {npc:895}",
		["{npc:658}: read the {quest:98581}"] = "{npc:658} : lisez {quest:98581}",
		["{npc:6806}, inside"] = "{npc:6806}, à l'intérieur",
		["{npc:706} along the way to {npc:786}"] = "{npc:706} sur le chemin de {npc:786}",
		["{npc:706} on the way"] = "{npc:706} en chemin",
		["{npc:713}, next to {npc:658}"] = "{npc:713}, à côté de {npc:658}",
		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "Le camp de {npc:714} est à l'extrémité ouest de la vallée. {item:10438} est dans la neige au sud du camp, le Coffre de Felix près de la grotte des trolls et le Seau de boulons de Felix à l'est de la grotte : ramassez-les en passant.",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786} et {npc:12738} campent au bord sud-ouest de la vallée, sous la grotte des trolls.",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808} est à l'intérieur de la grotte des trolls à l'est du camp de {npc:786}, pas sur la colline au-dessus : entrez par l'ouverture et suivez le tunnel jusqu'au fond.",
		["{npc:836}, inside Anvilmar; below ground"] = "{npc:836}, à l'intérieur de Courbenclume ; sous le sol",
		["{npc:837}, the priest trainer"] = "{npc:837}, le maître des prêtres",
		["{npc:8416}, at the door on the way out; inside"] = "{npc:8416}, à la porte en sortant ; à l'intérieur",
		["{npc:8416}, by the door of Anvilmar; inside"] = "{npc:8416}, près de la porte de Courbenclume ; à l'intérieur",
		["{npc:8508}, on the dock"] = "{npc:8508}, sur le quai",
		["{npc:895}, the hunter trainer"] = "{npc:895}, le maître des chasseurs",
		["{npc:912}, the warrior trainer; inside"] = "{npc:912}, le maître des guerriers ; à l'intérieur",
		["{npc:916}, the rogue trainer"] = "{npc:916}, le maître des voleurs",
		["{npc:926}, the paladin trainer"] = "{npc:926}, le maître des paladins",
		["{object:149024}: kill these as you meet them"] = "{object:149024} : tuez-les au fur et à mesure que vous les rencontrez",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}, près de la boîte aux lettres de {object:171524}",
		["{quest:287} is the troll cave in the hills south-west of Brewnall Village. Ice Claw Bears, Elder Crag Boars and Snow Leopards you kill on the way count for {npc:1374}. Kill Headhunters at its mouth and walk through to its far end."] = "{quest:287} est la caverne des trolls dans les collines au sud-ouest de Brassetout. Les ours griffeglace, anciens sangliers des rochers et léopards des neiges que vous tuez en chemin comptent pour {npc:1374}. Tuez les chasseurs de têtes à son entrée et traversez-la jusqu'au fond.",
		["{zone:1426}: kill these as you meet them"] = "{zone:1426} : tuez-les au fur et à mesure que vous les rencontrez",
		["{zone:1453} flight master"] = "Maître de vol de {zone:1453}",
		["{zone:1455} class quests"] = "Quêtes de classe de {zone:1455}",
} end)()
t.guides["groupe-alliance/02-rendez-vous-hurlevent"] = (function() return {
		["Druids: Cure Poison at 14, Aquatic Form at 16 and Cat Form at 20 come from class quests (Polestar guides, Class)."] = "Druides : Guérison du poison (14), Forme aquatique (16) et Forme de félin (20) s'obtiennent par des quêtes de classe (guides Polestar, Classe).",
		["Group 1 · Meet in {zone:1453}"] = "Groupe 1 · Rendez-vous à {zone:1453}",
		["Group up with your friends when they are online"] = "Former le groupe avec les autres s'ils sont connectés",
		["Night Elves: {zone:1457} to {zone:1453}"] = "Elfes de la nuit : de {zone:1457} à {zone:1453}",
		["Play at your own pace: quests already turned in tick themselves and the guide picks up where you are, so friends who play at other times can go ahead or fall behind. Together, group XP is best within 4 levels; ahead of the others, help them with their quests when you play together."] = "Chacun joue à son rythme : les quêtes déjà rendues se cochent toutes seules et le guide reprend où vous en êtes, donc on peut prendre de l'avance ou du retard sur les autres. Ensemble, l'XP de groupe est meilleure à 4 niveaux d'écart ou moins ; en avance, aidez les autres sur leurs quêtes quand vous jouez ensemble.",
		["Portal down to Rut'theran Village, boat to Auberdine, then the {zone:1453} boat from the same pier."] = "Portail vers Rut'theran, bateau pour Auberdine, puis bateau pour {zone:1453} sur le même ponton.",
		["{zone:1453}: meeting point"] = "{zone:1453} : point de rendez-vous",
} end)()
t.guides["groupe-alliance/03-marche-de-l-ouest"] = (function() return {
		["Back north past Molsen Farm to the mine: Kobold Diggers work inside."] = "Remontez au nord en passant la ferme des Molsen jusqu'à la mine : des terrassiers kobolds travaillent à l'intérieur.",
		["Back to {object:81}"] = "Retour à {object:81}",
		["Back to {zone:1453}"] = "Retour à {zone:1453}",
		["Defensive Stance"] = "Posture défensive",
		["Defias Pathstalkers and Knuckledusters walk Moonbrook; Highwaymen (level 17) patrol the hills south and east of it in pairs: pull them apart. The Deadmines entrance in the smithy is a group dungeon.\nCareful: The camps in the hills hold mixed groups of Defias, so it is easy to pull more than one at a time if you are low level."] = "Des éclaireurs et truands défias arpentent Ruisselune ; des malandrins (niveau 17) patrouillent par paires dans les collines au sud et à l'est : séparez-les. L'entrée des Mortemines, dans la forge, mène à un donjon de groupe.\nAttention : Les camps dans les collines contiennent des groupes mixtes de Défias, il est donc facile d'en attirer plus d'un à la fois si vous êtes bas niveau.",
		["Defias Pillagers and Looters hold the farms west of {object:81}, between the coast road and Moonbrook.\nCareful: The Gold Coast Quarry cave holds many Defias packed together, so it is easy to pull several at once there."] = "Des pilleurs et pillards défias occupent les fermes à l'ouest de {object:81}, entre la route côtière et Ruisselune.\nAttention : La grotte de la carrière de la côte de l'Or contient beaucoup de Défias serrés, il est donc facile d'en attirer plusieurs à la fois.",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Fill the vial at the farm's well"] = "Remplissez la fiole au puits de la ferme",
		["Fill the vial at the well"] = "Remplissez la fiole au puits",
		["Follow the road from Elwynn into {zone:1436}: the Furlbrows sit by their burned farm, the first one on the road. Pick up oats from any {object:2724} you pass on the loop: the rest are gathered in the fields here on the way back."] = "Suivez la route depuis Elwynn vers {zone:1436} : les Furlbrow sont assis près de leur ferme brûlée, la première sur la route. Ramassez de l'avoine sur chaque {object:2724} que vous croisez dans la boucle : le reste est récolté dans les champs ici sur le chemin du retour.",
		["For {npc:11026} in {zone:1453}'s {object:28027}"] = "Pour {npc:11026} dans {object:28027} de {zone:1453}",
		["For {npc:266} in Lakeshire, Redridge"] = "Pour {npc:266} à Comté-du-Lac, dans les Carmines",
		["Furlbrow's Pumpkin Farm: kill these as you meet them"] = "Ferme de potirons de Froncebouille : tuez-les au fur et à mesure",
		["Gnoll Paws"] = "Pattes de gnoll",
		["Group 2 · {zone:1436}"] = "Groupe 2 · {zone:1436}",
		["Harvest Watchers"] = "Gardiens des moissons",
		["Head to {zone:1453}. It has no shaman trainer: take the Deeprun Tram from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the boat."] = "Allez à {zone:1453}. Il n'y a pas de maître des chamans : prenez le Tram des profondeurs depuis {object:28027} jusqu'à {zone:1455}, entraînez-vous auprès de {npc:258098}, puis reprenez le tram pour le bateau.",
		["Inside"] = "À l'intérieur",
		["Kobold Diggers"] = "Terrassiers kobolds",
		["Level 12, 14 and 16 spells"] = "Sorts des niveaux 12, 14 et 16",
		["Longshore Murloc Gills"] = "Branchies de Murloc de Longrivage",
		["Moonbrook and the Defias hills"] = "Ruisselune et les collines des Défias",
		["Moonbrook: kill these as you meet them"] = "Ruisselune : tuez-les au fur et à mesure",
		["North of Molsen Farm. Defias Trappers and Smugglers camp outside the mine. {object:290} stands by the ruined house east of the mine.\nWest of Saldean's. Harvest Watchers and Golems work the fields; they drop the isosprings, gyrostabilizers, {item:732} and sometimes a {item:255155}. {npc:573}, a level 20 rare, walks here: leave it alone. Keep killing Goretusks and Fleshrippers on every leg of this loop."] = "Au nord de la ferme des Molsen. Des Trappeurs défias et des Contrebandiers défias campent devant la mine. {object:290} se trouve près de la maison en ruine à l'est de la mine.\nÀ l'ouest de chez Saldean. Des Gardiens des moissons et des Golems des moissons travaillent les champs ; ils lâchent les isoressorts, les gyrostabiliseurs, du {item:732} et parfois un {item:255155}. {npc:573}, un rare de niveau 20, rôde ici : laissez-le tranquille. Continuez à tuer des Broche-tripes et des Déchireurs à chaque étape de cette boucle.",
		["Only if you looted a {item:1972} in Elwynn: right-click it"] = "Seulement si vous avez ramassé un {item:1972} dans la forêt d'Elwynn : faites un clic droit dessus",
		["Right-click the {item:6775} he gives you"] = "Faites un clic droit sur le {item:6775} qu'il vous donne",
		["Riverpaw Gnolls and Scouts (level 11-13) roam the hills south of the coast, from above {object:83} east to the Jansen Stead. The gnolls further south and west are 13-19: stay in the north hills.\nMurloc Coastrunners and Raiders line the beach north of the mine. They flee at low health: pull one at a time.\nCareful: Gnolls that stand close together tend to join a fight as a group. Pulling one at a time is safer.\nCareful: Two Defias stand guard inside the house, one of them the level 15 named {npc:502}. They are linked, so attacking either one brings both."] = "Les gnolls et éclaireurs Rivepatte (niveau 11-13) rôdent dans les collines au sud de la côte, depuis les hauteurs au-dessus de {object:83} à l'est jusqu'à la ferme des Jansen. Les gnolls plus au sud et à l'ouest sont niveau 13-19 : restez dans les collines du nord.\nLes cours-la-côte et écumeurs murlocs longent la plage au nord de la mine. Ils fuient quand leur vie est basse : tirez-les un par un.\nAttention : Les gnolls qui se tiennent près les uns des autres ont tendance à se joindre au combat en groupe. Les tirer un par un est plus sûr.\nAttention : Deux Défias montent la garde dans la maison, dont {npc:502}, un nommé de niveau 15. Ils sont liés, donc en attaquer un attire l'autre.",
		["Riverpaw Miners"] = "Mineurs Rivepatte",
		["Sacks of Oats in the fields around the farm"] = "Sacs d'avoine dans les champs autour de la ferme",
		["Saldean's Farm"] = "Ferme des Saldean",
		["Shaman training"] = "Entraînement de chaman",
		["South along the road, past the fork. {npc:233} stands outside, {npc:235} in the house, {npc:253395} in the barn to the west. Young Goretusks and Fleshrippers roam the fields around the farm: start on livers and the stew's meat on the way."] = "Au sud par la route, après l'embranchement. {npc:233} se tient dehors, {npc:235} dans la maison, {npc:253395} dans la grange à l'ouest. De jeunes broche-tripes et des déchireurs rôdent dans les champs autour de la ferme : commencez à récupérer les foies et la viande du ragoût en chemin.",
		["South-west to the coast, west of Molsen Farm. Riverpaw Miners work the quarry."] = "Au sud-ouest vers la côte, à l'ouest de la ferme des Molsen. Des mineurs Rivepatte travaillent dans la carrière.",
		["Stormwind City"] = "Cité de Hurlevent",
		["The Gold Coast Quarry"] = "Carrière de la côte de l'Or",
		["The Jansen Stead"] = "La ferme des Jansen",
		["Tram to {zone:1455}"] = "Tram pour {zone:1455}",
		["Walk to {zone:1453}, or fly if you know its flight path. Trainers: {object:2100} (Warriors, Rogues), the Cathedral (Paladins, Priests), the {object:2101} (Mages, Warlocks), the Park (Druids)."] = "Marchez jusqu'à {zone:1453}, ou volez si vous connaissez son point de vol. Maîtres de classe : {object:2100} (guerriers, voleurs), la cathédrale (paladins, prêtres), {object:2101} (mages, démonistes), le parc (druides).",
		["Walk to {zone:1453}. {npc:376} is in the Cathedral of Light."] = "Marchez jusqu'à {zone:1453}. {npc:376} est dans la cathédrale de la Lumière.",
		["Walk to {zone:1453}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug."] = "Marchez jusqu'à {zone:1453}. {npc:5480} entraîne les guerriers dans {object:2100} ; {npc:6089} et {npc:6090} se tiennent ensemble près de {object:2152}. {npc:6090} vous combat pour sa chope.",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Pendant que vous y êtes : apprenez le maniement des bâtons auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; l'arme de mêlée d'un Chasseur vaut surtout par ses caractéristiques, et les armes à deux mains en portent le plus.",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Pendant que vous y êtes : apprenez le maniement des bâtons auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; un bâton apporte plus de caractéristiques de sorts qu'une arme à une main pendant la progression.",
		["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Pendant que vous y êtes : apprenez le maniement des épées auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; une épée en main droite fait progresser un Voleur régulièrement.",
		["While you're here: learn Two-Handed Swords from {npc:11867} ({object:2096}, 10 silver); two-handers level a Paladin fastest."] = "Pendant que vous êtes ici : apprenez Épées à deux mains auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; les armes à deux mains font monter un paladin le plus vite.",
		["While you're here: learn Two-Handed Swords from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Pendant que vous êtes ici : apprenez Épées à deux mains auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
		["{item:2449} for Gathering the Cure (6123) in {zone:1439}: {npc:1313}, Alchemy Supplies; herbalists pick it there instead"] = "{item:2449} pour Rassembler les ingrédients du remède (6123) à {zone:1439} : {npc:1313}, Fournitures d'alchimie ; les herboristes la cueillent plutôt là-bas",
		["{item:254676}, from the crates around Moonbrook"] = "{item:254676}, dans les caisses autour de Ruisselune",
		["{item:6529}, from {npc:5494}"] = "{item:6529}, chez {npc:5494}",
		["{item:729}: Fleshrippers"] = "{item:729} : Déchireurs",
		["{item:731} on the way"] = "{item:731} en chemin",
		["{npc:234} and {npc:821} stand at the top of the stone tower. {npc:491} is in the tower, {npc:878} on the south side of the hill, next to the inn and {npc:523} the gryphon master."] = "{npc:234} et {npc:821} se tiennent au sommet de la tour de pierre. {npc:491} est dans la tour, {npc:878} sur le flanc sud de la colline, près de l'auberge et de {npc:523}, le maître des griffons.",
		["{npc:235}, inside"] = "{npc:235}, à l'intérieur",
		["{npc:237}; Humans took it from {npc:963} in Elwynn"] = "{npc:237} ; les Humains l'ont pris à {npc:963} à Elwynn",
		["{npc:253092}, beside {npc:878}"] = "{npc:253092}, à côté de {npc:878}",
		["{npc:491}, inside"] = "{npc:491}, à l'intérieur",
		["{npc:523}; skip the free flight it offers"] = "{npc:523} ; ignorez le vol gratuit proposé",
		["{npc:5494} sells fishing supplies along the canal just west of the {object:2096}; {npc:267118} fishes at the harbor, on the way to the boat."] = "{npc:5494} vend des articles de pêche le long du canal, juste à l'ouest de {object:2096} ; {npc:267118} pêche au port, sur le chemin du bateau.",
		["{npc:5497}, Wizard's Sanctum: {quest:1861}"] = "{npc:5497}, au sanctum des mages : {quest:1861}",
		["{npc:6089}: Defensive Stance"] = "{npc:6089} : Posture défensive",
		["{npc:6171} and {npc:6173} are in the Cathedral of Light; {npc:6174} stands in the {object:2096} and asks for ten {item:2589} (humanoids drop it; the Auction House sells it)."] = "{npc:6171} et {npc:6173} sont dans la Cathédrale de la Lumière ; {npc:6174} se tient dans {object:2096} et demande dix {item:2589} (les humanoïdes en lâchent, l'hôtel des ventes en vend).",
		["{npc:6172}, by Stone Cairn Lake in Elwynn, on the road to Redridge"] = "{npc:6172}, près du lac du Cairn dans la forêt d'Elwynn, sur la route des Carmines",
		["{object:290}; inside"] = "{object:290} ; à l'intérieur",
		["{quest:153}: every Defias drops them"] = "{quest:153} : tous les Défias en lâchent",
		["{zone:1436}: kill these as you meet them"] = "{zone:1436} : tuez-les au fur et à mesure",
} end)()
t.guides["groupe-alliance/04-salle-des-thanes"] = (function() return {
		["Dark Iron Spies"] = "Espions Sombrefer",
		["Deeprun Tram to {zone:1455}"] = "Tram des profondeurs vers {zone:1455}",
		["Enter the Hall of Thanes"] = "Entrer dans la salle des Thanes",
		["Every player takes these quests before the run. Keep 6 free quest log slots."] = "Chaque joueur prend ces quêtes avant le donjon. Garder 6 places libres dans le journal.",
		["Group 3 · The Hall of Thanes (dungeon 13-17)"] = "Groupe 3 · La salle des Thanes (donjon 13-17)",
		["Group of 5, level 13 or more. The portal is past the bridge and the meeting stone."] = "Groupe de 5, niveau 13 ou plus. Le portail est après le pont et la pierre de rencontre.",
		["His camp overlooks {object:149024}, east of the depot."] = "Son camp domine {object:149024}, à l'est du dépôt.",
		["In the {object:171709}, take the cobwebbed passage on the left and follow it down to the dungeon."] = "Dans {object:171709}, prendre le passage couvert de toiles à gauche et descendre jusqu'au donjon.",
		["Inside the dungeon"] = "Dans le donjon",
		["Share each quest with your group: click it in the quest log, then Share."] = "Partagez chaque quête au groupe : clic sur la quête dans le journal, puis Partager.",
		["Spies roam around Ironband's Compound. The {item:274268} can drop from them: right-click it."] = "Des espions rôdent autour de la base d'Ironband. Ils peuvent lâcher {item:274268} : faites un clic droit dessus.",
		["Steelgrill's Depot"] = "Dépôt de Steelgrill",
		["Talk to him and choose the farsight"] = "Lui parler et choisir la vision lointaine",
		["The Hall of Thanes"] = "La salle des Thanes",
		["Treaty tablet in the last boss room"] = "Tablette du traité dans la salle du dernier boss",
		["West wing first: the {npc:265002} gives a quest before Faldrim. Each player loots their own heirlooms."] = "Aile ouest d'abord : {npc:265002} donne une quête avant Faldrim. Chacun ramasse ses propres reliques.",
		["{npc:2786}, in the {object:32383}"] = "{npc:2786}, dans {object:32383}",
		["{quest:971} belongs to Blackfathom Deeps, a dungeon the guide offers in Group 8 ({zone:1440}, levels 24 to 28). The route passes no other time in {zone:1455} before it. Planning that dungeon? Take it now: it waits in the quest log. Not sure, or playing alone? Skip it: Group 8 offers the dungeon without it."] = "{quest:971} sert aux Profondeurs de Brassenoire, un donjon que le guide propose au Groupe 8 ({zone:1440}, niveaux 24 à 28). Le parcours ne repasse pas par {zone:1455} avant. Le donjon est prévu ? La prendre maintenant : elle attend dans le journal. Pas sûr, ou seul ? La passer : le Groupe 8 propose le donjon sans elle.",
		["{zone:1455} rewards"] = "Récompenses à {zone:1455}",
		["{zone:1455}: dungeon quests"] = "{zone:1455} : quêtes du donjon",
		["{zone:1455}: {npc:2786} (Blackfathom Deeps, for later)"] = "{zone:1455} : {npc:2786} (Profondeurs de Brassenoire, pour plus tard)",
} end)()
t.guides["groupe-alliance/05-sombrivage"] = (function() return {
		["Alone, the quiet way out: same reward line, same next quest ({quest:990}). Hearth back to Auberdine afterwards."] = "Seul, la sortie discrète : même suite ({quest:990}). Revenir ensuite à Auberdine par la pierre de foyer.",
		["At the {object:177117}"] = "Au {object:177117}",
		["Auberdine"] = "Auberdine",
		["Auberdine flight master"] = "Maître de vol d'Auberdine",
		["Back north-east into the mountains to the crystal."] = "Retournez au nord-est dans les montagnes jusqu'au cristal.",
		["Back south"] = "Retour au sud",
		["Back to {npc:11802}"] = "Retour auprès de {npc:11802}",
		["Back to {npc:11802} in Nighthaven, then {npc:11800} there flies Druids straight to Rut'theran Village. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Retournez auprès de {npc:11802} à Havrenuit, puis {npc:11800} y fait voler les druides directement jusqu'à Rut'theran. {npc:11802} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
		["Bears and the Blackwood camp"] = "Les ours et le camp des Noirbois",
		["Blackwood Pathfinders and Windtalkers hold the camp south-east of Auberdine."] = "Les guides et les messagers du Vent Noirbois tiennent le camp au sud-est d'Auberdine.",
		["Blackwood furbolgs"] = "Les furbolgs Noirbois",
		["By the bonfire closest to the river: summons Xabraxxis"] = "Près du feu le plus proche de la rivière : invoque Xabraxxis",
		["Careful: If you attack one cub, the other cubs and often the mother join the fight, so expect to take on several at the same time."] = "Attention : si vous attaquez un ourson, les autres oursons et souvent la mère se joignent au combat : attendez-vous à en affronter plusieurs à la fois.",
		["Cast Teleport: {zone:1450}"] = "Lancez Téléportation : {zone:1450}",
		["Cast Teleport: {zone:1450}. {npc:11802} stands upstairs in his building in Nighthaven: go up inside, the arrow cannot tell the floors apart. Learn the flight path there if you do not have it."] = "Lancez Téléportation : {zone:1450}. {npc:11802} se tient à l'étage de son bâtiment à Havrenuit : montez par l'intérieur, la flèche ne distingue pas les étages. Apprenez le point de vol là-bas si vous ne l'avez pas.",
		["Cast Teleport: {zone:1450}. {npc:11802} stands upstairs in his building in Nighthaven: go up inside, the arrow cannot tell the floors apart. Shrine Baubles lie in the containers on the floor of Lake Elune'ara, below Nighthaven: take one to the {object:177117} in the north-west, use it there and speak to {npc:11799}. Then fly back to Auberdine from Nighthaven."] = "Lancez Téléportation : {zone:1450}. {npc:11802} se tient à l'étage de son bâtiment à Havrenuit : montez par l'intérieur, la flèche ne distingue pas les étages. Les colifichets du sanctuaire se trouvent dans les conteneurs au fond du lac Elune'ara, sous Havrenuit : apportez-en un jusqu'au {object:177117} au nord-ouest, utilisez-le là et parlez à {npc:11799}. Puis retournez à Auberdine en vol depuis Havrenuit.",
		["Cliffspring Falls"] = "Chutes de la Bondissante",
		["Cliffspring River"] = "La Bondissante",
		["Climb the eastern mountains east of {object:12894}; the {object:175524} sits on a ledge."] = "Grimpez les montagnes de l'est à l'est de {object:12894} ; le {object:175524} se trouve sur une corniche.",
		["Crawler Legs"] = "Pattes de clampant",
		["Elite level 21"] = "Élite de niveau 21",
		["Escort her out of the glaive; Therysil takes the turn-in in {zone:1440}"] = "Escortez-la hors du glaive ; Therysil prend le rendu de quête en {zone:1440}",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Fill the tube at the moonwell in the village"] = "Remplissez le tube au puits de lune du village",
		["Fine Moonstalker Pelts"] = "Belles peaux de traquelune",
		["Fly from Auberdine to Rut'theran Village and take the portal up to {npc:4217} in the Cenarion Enclave."] = "Volez d'Auberdine au village de Rut'theran et prenez le portail jusqu'à {npc:4217} dans l'Enclave cénarienne.",
		["Follow the coast north-east to the Ruins of Mathystra. {quest:951} lie among the ruins; Stormscale Myrmidons, Sorceresses and Warriors hold them, and Stormscale Beastmistresses walk the shore."] = "Suivez la côte au nord-est jusqu'aux ruines de Mathystra. {quest:951} gisent parmi les ruines ; les myrmidons, ensorceleuses et guerriers Tempécaille les occupent, et les maîtresses des bêtes Tempécaille arpentent le rivage.",
		["Follow the coast south past {object:12894}: one {quest:4728} lies on the shore west of the Grove, another further south near Remtravel's Excavation. Three more remains lie further south-west among Greymist Oracles and Tidehunters (18-20): the guide leaves them for the last loop, when you are closer to their level."] = "Suivez la côte vers le sud en passant {object:12894} : un {quest:4728} gît sur la rive à l'ouest du Bosquet, un autre plus au sud près des Excavations de Remtravel. Trois autres restes gisent plus au sud-ouest parmi les oracles et chasse-marées Grisebrume (18-20) : le guide les garde pour la dernière boucle, quand vous serez plus proche de leur niveau.",
		["Follow the hills north to the Cliffspring River and up to the falls. Two more beached remains lie on the north shore: near the Ruins of Mathystra and north of {quest:954}."] = "Suivez les collines vers le nord jusqu'à la Bondissante et remontez jusqu'aux chutes. Deux autres restes échoués gisent sur la rive nord : près des ruines de Mathystra et au nord de {quest:954}.",
		["Follow the road north."] = "Suivez la route vers le nord.",
		["Grell Earrings"] = "Boucles d'oreille de grell",
		["Grizzled Scalps"] = "Scalps vieillis",
		["Grizzled Thistle Bears roam the hills around the Grove; {quest:1003} stands west of it among them."] = "De vieux ours des chardons errent dans les collines autour du Bosquet ; {quest:1003} se trouve à l'ouest, parmi eux.",
		["Group 4 · {zone:1439}"] = "Groupe 4 · {zone:1439}",
		["Group: everyone hands their fragments to one player (they can be traded, the Auction House sells them too), who summons him once; every member loots a globe. Alone at 20 or more: hide behind a pillar as each cast ends, step out to shoot. He is immune to Frost: Mages use Fire. Stone gone? Someone just summoned him: it comes back in 5 to 10 minutes."] = "En groupe : chacun donne ses fragments à un seul joueur (ils s'échangent, l'hôtel des ventes en vend aussi), qui l'invoque une fois ; chaque membre ramasse un globe. Seul, au niveau 20 ou plus : se cacher derrière un pilier à la fin de chaque incantation, ressortir pour tirer. Il est insensible au Givre : mages en Feu. La pierre a disparu ? Quelqu'un vient de l'invoquer : elle revient en 5 à 10 minutes.",
		["He charges into the furbolg camp and more furbolgs come even if you cleared it, two shamans healing them. Two or three players; a healer helps."] = "Il fonce dans le camp des furbolgs et d'autres arrivent même camp vidé, avec deux chamans qui les soignent. À deux ou trois ; un soigneur aide.",
		["Help {npc:3692} escape the cave"] = "Aider {npc:3692} à quitter la grotte",
		["Help {npc:3692} to the road"] = "Aider {npc:3692} à rejoindre la route",
		["Highborne Relics"] = "Reliques de bien-Né",
		["Kill Rabid Thistle Bears in the hills east of Auberdine, then walk up to the furbolg camp south-east of them: nothing to kill yet."] = "Tuez des ours des chardons enragés dans les collines à l'est d'Auberdine, puis montez jusqu'au camp des furbolgs au sud-est : rien à tuer pour l'instant.",
		["Level 18.47"] = "Niveau 18.47",
		["Level 20"] = "Niveau 20",
		["Mist's Edge"] = "La lisière des brumes",
		["Mist's Edge: kill these as you meet them"] = "La lisière des brumes : tuez-les au fur et à mesure",
		["Moonstalker Fangs"] = "Crocs de traquelune",
		["Moonstalker Sires prowl the woods around the glaive. The {object:10076} and the {object:12666} sit at the bottom of the crater; {npc:3584} stands on its north side."] = "Des Géniteurs traquelunes rôdent dans les bois autour du glaive. Le {object:10076} et le {object:12666} se trouvent au fond du cratère ; {npc:3584} se tient sur son flanc nord.",
		["Moonstalkers prowl the hills between {quest:954} and the tower. {quest:1002} stands on the hill west of the tower."] = "Des Traquelunes rôdent dans les collines entre {quest:954} et la tour. {quest:1002} se trouve sur la colline à l'ouest de la tour.",
		["Night Elves fly from Auberdine to Rut'theran Village; Skyborne take the boat from the Auberdine dock and learn the Rut'theran flight path there. Take the portal up to {npc:4217} in the Cenarion Enclave."] = "Les Elfes de la nuit volent d'Auberdine au village de Rut'theran ; les Éolides prennent le bateau au quai d'Auberdine et y apprennent le point de vol de Rut'theran. Prenez le portail pour monter jusqu'à {npc:4217} dans l'Enclave cénarienne.",
		["North along the hills. {npc:3650} waits in the ruins of {quest:954}; Wild Grells and Vile Sprites fill them, Deth'ryll Satyrs the eastern edge. {quest:1001} stands by the road west of the ruins; a {quest:4723} lies on the shore on the way to him."] = "Au nord, le long des collines. {npc:3650} attend dans les ruines de {quest:954} ; des Grells sauvages et des Fées viles les peuplent, des Satyres Deth'ryll en occupent la lisière est. {quest:1001} se trouve près de la route à l'ouest des ruines ; une {quest:4723} gît sur la côte en chemin.",
		["On the way"] = "En chemin",
		["Only if a Disciple or Thug dropped {item:5352}: right-click it"] = "Seulement si un Disciple ou un Nervi a laissé tomber {item:5352} : clic droit dessus",
		["Plagued bears"] = "Les ours pestiférés",
		["Rabid Thistle Bears roam the hills just east of Auberdine. Use {quest:2139} on one and lead it back to him."] = "Des ours des chardons enragés rôdent dans les collines juste à l'est d'Auberdine. Utilisez {quest:2139} sur l'un d'eux et ramenez-le jusqu'à lui.",
		["Read the {object:17188}"] = "Lisez {object:17188}",
		["Read the {object:17189}"] = "Lisez {object:17189}",
		["Remtravel's Excavation lies on the coast south of {npc:10323}'s beach. Protect the prospector while he searches for the fossil.\nCareful: Ambushers appear as he passes certain spots: a scout comes out from under the board ramp, and more scouts come out when he checks the tent."] = "L'excavation de Remtravel se trouve sur la côte au sud de la plage de {npc:10323}. Protégez le prospecteur pendant qu'il cherche le fossile.\nAttention : Des embusqués apparaissent lorsqu'il passe certains endroits : un éclaireur sort de sous la rampe en planches, et d'autres éclaireurs surgissent quand il inspecte la tente.",
		["Scaber Stalks; below ground"] = "Pédoncules d'amanite ; sous terre",
		["She gives you the {item:15826}"] = "Elle vous donne le {item:15826}",
		["Take the portal up to {npc:4217}, then fly back to Auberdine for the boat to {zone:1453}."] = "Prenez le portail jusqu'à {npc:4217}, puis volez de retour à Auberdine pour prendre le bateau vers {zone:1453}.",
		["The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of Auberdine; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else brings it from {zone:1453} ({npc:1313}) or the Auction House."] = "Les floraisons fongiques lunaires poussent dans les grottes des séléniens dans les collines juste à l'est d'Auberdine ; les séléniens y sont irritables. {item:2449} nécessite {skill:182} : les herboristes le cueillent partout en {zone:1439}, les autres l'apportent de {zone:1453} ({npc:1313}) ou de l'Hôtel des ventes.",
		["The Ruins of Mathystra"] = "Les Ruines de Mathystra",
		["The Stormscale naga of the ruins drop Mathystral Amulet Fragments, about one naga in eleven (the {npc:271903}, for {quest:87760}, nearly one in two): 20 make the amulet at the {object:177964}, down the spiral stairs in the ruins. Using it summons {quest:98028}, a level 21 elite; his {item:279275} starts the quest."] = "Les nagas Tempécaille des ruines lâchent des fragments d'amulette de Mathystra, environ un naga sur onze ({npc:271903}, pour {quest:87760}, presque un sur deux) : 20 forment l'amulette à {object:177964}, en bas de l'escalier en colimaçon des ruines. L'utiliser invoque {quest:98028}, un élite de niveau 21 ; son {item:279275} lance la quête.",
		["The WANTED poster"] = "L'affiche AVIS DE RECHERCHE",
		["The WANTED poster outside the inn"] = "L'affiche AVIS DE RECHERCHE devant l'auberge",
		["The bay wrecks"] = "Les épaves de la baie",
		["The beach"] = "La plage",
		["The boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street. {npc:3666} stands upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Le bateau accoste à l'ouest du village. Le maître de vol se tient sur la colline au sud de l'auberge ; les donneurs de quêtes sont répartis le long de la rue principale. {npc:3666} se tient à l'étage de l'auberge : prenez l'escalier intérieur, la flèche ne distingue pas les étages.",
		["The cave and the {npc:6788}"] = "La grotte et la {npc:6788}",
		["The cave lies south of the falls: Scaber Stalks grow all through it, the {item:5270} at the very back. The {npc:6788} lairs in the hills south of the falls."] = "La grotte se trouve au sud des chutes : des Pédoncules d'amanite ({item:5271}) poussent partout à l'intérieur, {item:5270} tout au fond. {npc:6788} a son repaire dans les collines au sud des chutes.",
		["The flame burns in the south of {object:12894}."] = "La flamme brûle au sud de {object:12894}.",
		["The furbolg camp south of the Cliffspring River keeps its Nut, Fruit and Grain Stores by the bonfires. With a sample of each and the {item:12347} in your bags (the {item:12346} is filled at the {object:174795}), use the bowl by the bonfire closest to the river: it summons Xabraxxis, the satyr corruptor, and the {item:12355} lies in his Demon Bag."] = "Le camp des furbolgs au sud de la Bondissante garde ses réserves de noix, de fruits et de céréales près des feux de camp. Avec un échantillon de chacune et le {item:12347} dans vos sacs (le {item:12346} est rempli au {object:174795}), utilisez le bol près du feu de camp le plus proche de la rivière : cela invoque Xabraxxis, le satyre corrupteur, et le {item:12355} se trouve dans son sac des démons.",
		["The half pendants lie in {zone:1439} and {zone:1436}: later on the route"] = "Les demi-pendentifs se trouvent en {zone:1439} et en {zone:1436} : plus tard sur l'itinéraire",
		["The naga"] = "Les nagas",
		["The northern Blackwood camp"] = "Le camp Noirbois du nord",
		["The red crystal"] = "Le cristal rouge",
		["The relics of the Barrow Dens"] = "Les reliques du Refuge des saisons",
		["The robot, elite level 20"] = "Le robot, élite de niveau 20",
		["The skeletal turtle"] = "La tortue squelettique",
		["The southern beaches"] = "Les plages du sud",
		["The {object:10076}"] = "{object:10076}",
		["The {object:12666}"] = "{object:12666}",
		["The {object:16393}"] = "{object:16393}",
		["The {quest:952}"] = "{quest:952}",
		["Thresher Eyes; underwater"] = "Yeux de batteur ; sous l'eau",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Les Clampants des marées grouillent sur la côte en contrebas du village ; {quest:983} se trouve sur la plage juste au sud des quais. Les Batteurs de Sombrivage nagent dans les hauts-fonds. La {object:175207} gît sur la côte juste au sud du village.",
		["Top up here to level 18.47 before the hand-ins at {quest:952}: they take you to level 19."] = "Complétez ici jusqu'au niveau 18.47 avant les rendus de {quest:952} : ils vous font passer au niveau 19.",
		["Top up here to level 20 before the hand-ins at {zone:1453}: they take you to level 21."] = "Complétez ici jusqu'au niveau 20 avant les rendus de quêtes à {zone:1453} : ils vous font passer au niveau 21.",
		["Two wrecks lie on the sea floor in the bay north of Auberdine; each holds a lockbox. Reef Crawlers and Encrusted Tide Crawlers line this shore.\nCareful: The murlocs inside the wrecks are close together and fast. They often swim through the hull walls and holes, so you will usually pull extra murlocs."] = "Deux épaves gisent sur le fond marin dans la baie au nord d'Auberdine ; chacune contient une cassette. Des clampants des récifs et des clampants des marées incrustés longent ce rivage.\nAttention : Les murlocs à l'intérieur des épaves sont proches les uns des autres et rapides. Ils nagent souvent à travers les parois et les trous de la coque, vous attirerez donc généralement des murlocs supplémentaires.",
		["Underwater"] = "Sous l'eau",
		["grind on {npc:2187}"] = "tuez en boucle : {npc:2187}",
		["grind on {npc:2237}"] = "tuez en boucle : {npc:2237}",
		["grind on {npc:2339}"] = "tuez en boucle : {npc:2339}",
		["the Rabid Thistle Bears nearest {npc:3701}"] = "les Ours des chardons enragés les plus proches de {npc:3701}",
		["{item:12191}; underwater"] = "{item:12191} ; sous l'eau",
		["{item:12192}; underwater"] = "{item:12192} ; sous l'eau",
		["{item:12237} from {npc:2233} and {npc:2235}, by this stop"] = "{item:12237} sur les {npc:2233} et {npc:2235}, près de cet arrêt",
		["{item:12238}: fish from the pier"] = "{item:12238} : à pêcher depuis la jetée",
		["{item:12289}, on the beach west of the docks; underwater"] = "{item:12289}, sur la plage à l'ouest des quais ; sous l'eau",
		["{item:12347}: fill the {item:12346} at the {object:174795}"] = "{item:12347} : remplissez le {item:12346} au {object:174795}",
		["{item:12349}, at the waterfall"] = "{item:12349}, à la cascade",
		["{item:12355}, in {object:177624}"] = "{item:12355}, dans le {object:177624}",
		["{item:15845}: at the mouth of the cave by the falls"] = "{item:15845} : à l'entrée de la grotte près des chutes",
		["{item:15851} and {item:2449}"] = "{item:15851} et {item:2449}",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, dans un {object:177785} au fond du lac",
		["{item:15883}: the {object:177792} under the water off the north coast, west of the ruins"] = "{item:15883} : l'{object:177792} sous l'eau au large de la côte nord, à l'ouest des ruines",
		["{item:279275}, from the Baron: right-click it"] = "{item:279275}, sur le baron : clic droit dessus",
		["{item:279276}: any Stormscale naga, while you kill them for {npc:270269}"] = "{item:279276} : n'importe quel naga Écaille-des-tempêtes, en les tuant pour {npc:270269}",
		["{item:279277}, at the {object:177964}: summons {quest:98028}"] = "{item:279277}, à {object:177964} : invoque {quest:98028}",
		["{item:279279}: Twilight Disciples and Thugs"] = "{item:279279} : Disciples du crépuscule et Nervis du crépuscule",
		["{item:5270}; below ground"] = "{item:5270} ; sous terre",
		["{item:5338}: Deth'ryll Satyrs"] = "{item:5338} : Satyres Deth'ryll",
		["{item:5348}: Dark Strand Fanatics"] = "{item:5348} : Fanatiques de la Rive noire",
		["{npc:10216}, on the pier: only with {skill:356}"] = "{npc:10216}, sur la jetée : uniquement avec {skill:356}",
		["{npc:10323} camps on the beach west of the glaive: kill the murlocs at the camp fire; he comes in the third wave with his hound. Three beached remains lie on the beaches west and south-west of Remtravel's Excavation."] = "{npc:10323} campe sur la plage à l'ouest de la glaive : tuez les murlocs au feu de camp ; il arrive dans la troisième vague avec son chien. Trois restes échoués gisent sur les plages à l'ouest et au sud-ouest de l'excavation de Remtravel.",
		["{npc:10323}'s beach"] = "La plage de {npc:10323}",
		["{npc:11802} stands upstairs in his building in Nighthaven: go up inside, the arrow cannot tell the floors apart."] = "{npc:11802} se tient à l'étage de son bâtiment à Havrenuit : montez par l'intérieur, la flèche ne distingue pas les étages.",
		["{npc:11802}: the welcome from Sheldras"] = "{npc:11802} : le message de bienvenue de Sheldras Moontree",
		["{npc:12298}: use the {item:15826} on them; they roam all of {zone:1439}"] = "{npc:12298} : utilisez le {item:15826} sur eux ; ils errent dans tout {zone:1439}",
		["{npc:2164} on the way"] = "{npc:2164} en chemin",
		["{npc:3616}, at the Grove"] = "{npc:3616}, au Bosquet des Anciens",
		["{npc:3616}: speak to him again afterwards, he has one more thing for you"] = "{npc:3616} : lui reparler ensuite, il a encore quelque chose à donner",
		["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639} se tient à la lisière nord des ruines. Des Bien-nés maudits, des Bien-nés frémissants et des {npc:2178} les hantent ; le fantôme d'{npc:3667} erre parmi eux, la chouette {npc:270196} tournoie à l'est. Les deux tablettes se trouvent dans les ruines ; une {quest:4722} gît sur la côte à l'ouest.",
		["{npc:3644}, on the pier"] = "{npc:3644}, sur la jetée",
		["{npc:3649}, north end of the village"] = "{npc:3649}, au nord du village",
		["{npc:3649}: for {npc:1646} in {zone:1453}"] = "{npc:3649} : pour {npc:1646} à {zone:1453}",
		["{npc:3661} hides at the foot of the tower among the Dark Strand Fanatics. Keep his letter for Delgren in {zone:1440}."] = "{npc:3661} se cache au pied de la tour parmi les Fanatiques de la Rive noire. Gardez sa lettre pour Delgren le Purificateur en {zone:1440}.",
		["{npc:3666}, upstairs in the inn"] = "{npc:3666}, à l'étage de l'auberge",
		["{npc:3692} hides in Blackwood Den, in the hills east of the Master's Glaive. Equip the {item:5387} from {npc:3693} and use it near the cave: it slips you past the furbolgs. Then choose his way out."] = "{npc:3692} se cache dans la Tanière des Noirbois, dans les collines à l'est du Glaive du Maître. Équiper {item:5387} reçue de {npc:3693} et l'utiliser près de la grotte : elle permet de passer les furbolgs sans être vu. Choisir ensuite sa façon de sortir.",
		["{npc:3692}, inside Blackwood Den"] = "{npc:3692}, dans la Tanière des Noirbois",
		["{npc:3692}: {quest:994} (group)"] = "{npc:3692} : {quest:994} (groupe)",
		["{npc:3694}: for {npc:3691} in Astranaar, on the later {zone:1440} leg"] = "{npc:3694} : pour {npc:3691} à Astranaar, lors de l'étape ultérieure en {zone:1440}",
		["{npc:4217}: Cat Form"] = "{npc:4217} : Forme de félin",
		["{npc:4217}: Cure Poison"] = "{npc:4217} : Guérison du poison",
		["{npc:6301}: {quest:97894}, if you took it in {zone:1453}"] = "{npc:6301} : {quest:97894}, si vous l'avez prise à {zone:1453}",
		["{npc:6667} hides on the little island off the ruins. The key pieces drop from Giant Foreststriders (top), Greymist murlocs (middle) and Raging Reef Crawlers (bottom)."] = "{npc:6667} se cache sur le petit îlot au large des ruines. Les morceaux de clé tombent des Trotteurs des forêts géants (haut), des murlocs Grisebrume (milieu) et des Clampants des récifs enragés (bas).",
		["{npc:6667}'s key wakes the {npc:6669} on the shore south of his island; lead it back and it turns hostile near {npc:6667}: a level 20 elite robot. Alone you need a root or a fear: Druids root it and Moonfire from afar, Warlocks dot, Fear and let the Voidwalker hold it, Mages kite with Frost Nova. Melee: come with a friend. Water only resets it."] = "La clé de {npc:6667} réveille {npc:6669} sur la rive au sud de son île ; le ramener, il devient hostile près de {npc:6667} : un robot élite de niveau 20. Seul, il faut une immobilisation ou une peur : druide, Sarments puis Éclat lunaire de loin ; démoniste, sorts sur la durée, Peur et le marcheur du Vide devant ; mage, le promener avec Nova de givre. Corps à corps : venir à deux. L'eau ne fait que le réinitialiser.",
		["{npc:6788}, below ground"] = "{npc:6788}, sous terre",
		["{npc:7232}, in the {object:28027}, sends you to his brother in Auberdine: free XP on the boat trip you take anyway."] = "{npc:7232}, dans {object:28027}, vous envoie chez son frère à Auberdine : de l'XP gratuite sur le trajet en bateau que vous faites de toute façon.",
		["{quest:2078} (group, optional)"] = "{quest:2078} (groupe, facultatif)",
		["{quest:6122}: fill the sampler at Cliffspring Falls"] = "{quest:6122} : remplissez l'échantillonneur aux chutes de la Bondissante",
		["{quest:87760}: {npc:10219} offers it once all nine beached remains are handed in"] = "{quest:87760} : {npc:10219} la propose une fois les neuf restes échoués rendus",
		["{quest:948} is the ancient at the Grove; {npc:270269} and {npc:11218} sleep beside him."] = "{quest:948} est l'ancien du Bosquet ; {npc:270269} et {npc:11218} dorment à côté de lui.",
		["{quest:98028} (group, optional)"] = "{quest:98028} (groupe, facultatif)",
		["{quest:98394} (Night Elves) and the {npc:272054} (Skyborne) wait in southern {zone:1450}. The three relics lie in the {object:177116}, east of them. Reports from the first weeks say a relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394} (Elfes de la nuit) et le {npc:272054} (Célestes) attendent au sud de {zone:1450}. Les trois reliques se trouvent dans le {object:177116}, à l'est d'eux. Les rapports des premières semaines indiquent qu'une relique ne donne pas de butin tant qu'un autre joueur la pille : attendez un instant et réessayez.",
		["{zone:1439} before Auberdine"] = "{zone:1439} avant Auberdine",
		["{zone:1439}: kill these as you meet them"] = "{zone:1439} : tuez-les au passage",
} end)()
t.guides["groupe-alliance/06-ruines-de-lordaeron"] = (function() return {
		["Auberdine: boat to Southshore"] = "Auberdine : bateau pour Austrivage",
		["Blood-stained letter, by {npc:250657}: each player clicks their own"] = "Lettre tachée de sang, près de {npc:250657} : chaque joueur clique la sienne",
		["Flesh Golems hit hard and knock you into other packs; ghouls come in threes and fours. Viktor is optional: light the chimney of the ruined house in the south-west, survive 4 to 6 waves (leave the last enemy of each wave alive a moment so casters can drink), then he jumps out. Short group? Skip him."] = "Les golems de chair frappent fort et projettent dans d'autres groupes ; les goules viennent par trois ou quatre. Viktor est facultatif : allumer la cheminée de la maison en ruine au sud-ouest, tenir 4 à 6 vagues (laisser vivre un moment le dernier ennemi de chaque vague pour que les lanceurs de sorts boivent), puis il surgit. Groupe réduit ? Le laisser.",
		["Group 5 · Ruins of Lordaeron (dungeon 17-21)"] = "Groupe 5 · Ruines de Lordaeron (donjon 17-21)",
		["Horde land: travel together. North past Hillsbrad Fields, around Dalaran, then swim north up Lordamere Lake into Tirisfal and follow the road. If you die inside, the spirit healer is right outside the dungeon."] = "Terres de la Horde : voyager ensemble. Au nord par les champs de Hautebrande, contourner Dalaran, puis nager vers le nord sur le lac Lordamere jusqu'à Tirisfal et suivre la route. Mort dans le donjon ? Le gardien des âmes est juste à la sortie.",
		["Lordamere Overlook: {npc:256035} (optional)"] = "Surplomb de Lordamere : {npc:256035} (facultatif)",
		["Market Street: {npc:250631} (optional)"] = "Rue du Marché : {npc:250631} (facultatif)",
		["Next letter for Darkshire, in {zone:1431} later: {npc:228} gives the {item:279870}"] = "Lettre suivante pour Sombre-Comté, plus tard au {zone:1431} : {npc:228} donne {item:279870}",
		["On your left just after the portal. The bosses can be done in any order. Any undead may drop a {quest:95195}: right-click it, then keep looting them, there are plenty for everyone."] = "À gauche juste après le portail. Les boss se font dans n'importe quel ordre. N'importe quel mort-vivant peut lâcher {quest:95195} : clic droit dessus, puis continuer à les ramasser, il y en a pour tout le monde.",
		["One crest per run, at a random spot with no mark on the minimap: the top of the east tower (left of the top floor doors), the banshee crypt door before {npc:250660}, the top of the west tower, the foot of the north-west tower by the double stairs, or the wall of {npc:256097}'s gazebo (nearly invisible: hover the wall)."] = "Un seul écusson par passage, à une place au hasard, sans marque sur la minicarte : le haut de la tour est (à gauche des portes du dernier étage), la porte de crypte à banshee devant {npc:250660}, le haut de la tour ouest, le pied de la tour nord-ouest près du double escalier, ou le mur du kiosque de {npc:256097} (presque invisible : passer la souris sur le mur).",
		["Right from the entrance. Skeletons and banshees guard him; the banshees silence, so stun the packs. His head drops for everyone on the quest. The crypt door with a banshee in front of him is one of the Crest's spots."] = "À droite depuis l'entrée. Squelettes et banshees le gardent ; les banshees réduisent au silence, étourdir les groupes. Sa tête tombe pour chaque joueur qui a la quête. La porte de crypte gardée par une banshee devant lui est une des places possibles de l'écusson.",
		["Ruins of Lordaeron"] = "Ruines de Lordaeron",
		["Ruins of Lordaeron entrance"] = "Entrée des Ruines de Lordaeron",
		["Ruins of Lordaeron: a 5-player Forever dungeon in {zone:1420}, best at 16 to 22 (17 or more is comfortable). Alone? Skip it: the guide takes you to {zone:1453} for Redridge. The Southshore boat leaves from Auberdine's pier. Keep 4 free quest log slots."] = "Ruines de Lordaeron : un donjon de Forever pour 5 joueurs, à {zone:1420}, idéal de 16 à 22 (confortable dès 17). Seul ? La passer : le guide mène à {zone:1453} pour les Carmines. Le bateau pour Austrivage part du ponton d'Auberdine. Garder 4 places libres dans le journal.",
		["Share each quest with your group: click it in the quest log, then Share."] = "Partagez chaque quête au groupe : clic sur la quête dans le journal, puis Partager.",
		["Southshore"] = "Austrivage",
		["The graveyard at the back. His one spell, Flamestrike, lands where the tank stood when he began it: step out at once, or stun him to stop it. The rare {npc:255699} is friendly to the Alliance: leave him be."] = "Le cimetière du fond. Son seul sort, Choc de flammes, tombe là où se tenait le tank au début de l'incantation : en sortir tout de suite, ou l'étourdir pour l'arrêter. Le rare {npc:255699} est amical pour l'Alliance : le laisser.",
		["The spider wing, King's Alley. {npc:250483} patrols with two spiders: kill them first and cleanse Leech Poison off the tank. Spider packs patrol too: pull with care."] = "L'aile des araignées, allée du Roi. {npc:250483} patrouille avec deux araignées : les tuer d'abord et dissiper le poison sur le tank. Des groupes d'araignées patrouillent aussi : tirer avec prudence.",
		["The statue with green eyes starts 3 waves, and the skeleton mage in the south corridor must die too; then {npc:250631}: Frost Nova, slows melee, drains the tank. Optional. The top of the west tower next to it is one of the Crest's spots."] = "La statue aux yeux verts lance 3 vagues, et le mage squelette du couloir sud doit mourir aussi ; puis {npc:250631} : Nova de givre, ralentit le corps à corps, draine le tank. Facultatif. Le haut de la tour ouest, à côté, est une des places possibles de l'écusson.",
		["The undead troll patrolling the north-west: a simple fight, just wait out his short Anti-Magic Shield."] = "Le troll mort-vivant qui patrouille au nord-ouest : un combat simple, attendre juste la fin de son court bouclier anti-magie.",
		["The {quest:95189}"] = "{quest:95189}",
		["{npc:250631}, or skipped"] = "{npc:250631}, ou laissé",
		["{npc:256035}, or skipped"] = "{npc:256035}, ou laissé",
		["{npc:265701}, by the entrance"] = "{npc:265701}, près de l'entrée",
		["{npc:466} by the gate, the Matron at the orphanage, {npc:15991} in the keep."] = "{npc:466} près de la porte, la matrone à l'orphelinat, {npc:15991} au donjon.",
		["{quest:95189}: each player clicks it"] = "{quest:95189} : chaque joueur clique dessus",
		["{quest:95195}, from any undead: right-click it"] = "{quest:95195}, sur n'importe quel mort-vivant : clic droit dessus",
		["{quest:95195}, from the undead all run long"] = "{quest:95195}, sur les morts-vivants pendant tout le donjon",
		["{zone:1453} rewards"] = "Récompenses à {zone:1453}",
} end)()
t.guides["groupe-alliance/07-carmines"] = (function() return {
		["At the back of a cave south-east of the camps, with an imp and two helpers: kill the helpers first and keep an interrupt (Counterspell, Spell Lock) for his long fire cast. Two players are enough at 23."] = "Au fond d'une grotte au sud-est des camps, avec un diablotin et deux aides : tuer les aides d'abord et garder une interruption (Contresort, Verrou magique) pour sa longue incantation de feu. Deux joueurs suffisent au niveau 23.",
		["Back to Lakeshire"] = "Retour à Comté-du-Lac",
		["Back to {zone:1429}"] = "Retour à {zone:1429}",
		["Blackrock camps"] = "Camps Blackrock",
		["Boat to Stormwind Harbor"] = "Bateau pour le port de Hurlevent",
		["Click the weapons and racks, the grain sacks, meat and water barrels in the camps; they come back slowly and other players take them too."] = "Cliquer les armes et râteliers, sacs de grain, viandes et tonneaux d'eau des camps ; ils reviennent lentement et d'autres joueurs les prennent aussi.",
		["Cross the long bridge north into town. {npc:341} and {npc:382} stand at the north end of the bridge, {npc:900} in the town hall, {npc:381} and {npc:266} on the docks, {npc:343} at the inn, {npc:342} in her garden at the west end."] = "Traversez le long pont vers le nord jusqu'à la ville. {npc:341} et {npc:382} se tiennent au bout nord du pont, {npc:900} dans l'hôtel de ville, {npc:381} et {npc:266} sur les quais, {npc:343} à l'auberge, {npc:342} dans son jardin, à l'ouest.",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Fly to {object:81}"] = "Envolez-vous vers {object:81}",
		["Fly to {object:81} and head north-west to the coast: the {object:177790} lies on the sea floor off the shore. Then head east along the road through Elwynn to Redridge."] = "Envolez-vous vers {object:81} et dirigez-vous au nord-ouest vers la côte : {object:177790} gît sur le fond marin au large. Puis suivez la route vers l'est à travers la Forêt d'Elwynn jusqu'aux Carmines.",
		["Follow the road along the south shore of Lake Everstill to the gryphon master. {npc:1070} and {npc:903} stand by the road next to her."] = "Suivez la route le long de la rive sud du lac Placide jusqu'au maître des griffons. {npc:1070} et {npc:903} se tiennent près de la route à côté d'elle.",
		["Four elite quests around {object:116}, about 12,000 XP: best with 3 to 5 players at 23 to 25. Alone: the guide skips them. {npc:382} gives his two once {quest:98387} is handed in."] = "Quatre quêtes élites autour de {object:116}, environ 12 000 XP : idéal à 3 à 5 joueurs, niveaux 23 à 25. Seul : le guide les passe. {npc:382} donne les deux siennes une fois {quest:98387} rendue.",
		["Group 6 · {zone:1433}"] = "Groupe 6 · {zone:1433}",
		["Head north out of Lakeshire up the Redridge Canyons to Render's Valley. Blackrock Champions camp in the valley."] = "Sortez de Comté-du-Lac par le nord et remontez les canyons des Carmines jusqu'à la vallée des Etripeurs. Les champions Blackrock y campent.",
		["Inside"] = "À l'intérieur",
		["Keeshan hides at the very north end of the valley, by the {zone:1428} border. Escort him down to Lakeshire; Blackrock orcs ambush you on the way."] = "Keeshan se cache tout au nord de la vallée, près de la frontière de {zone:1428}. Escortez-le jusqu'à Comté-du-Lac ; des orcs rochenoires vous tendent une embuscade en route.",
		["Lake Everstill: kill these as you meet them"] = "lac Placide : tuez-les au fur et à mesure",
		["Lakeridge Highway"] = "Grand-route de la Crête du lac",
		["Lakeridge Highway: kill these as you meet them"] = "Grand-route de la Crête du lac : tuez-les au fur et à mesure",
		["Lakeshire"] = "Comté-du-Lac",
		["Lakeshire rewards"] = "Récompenses à Comté-du-Lac",
		["Level 18 and 20 spells"] = "Sorts des niveaux 18 et 20",
		["Murloc Flesheaters and Tidecallers line the south shore east of the bridge. Any of them can carry a {item:1467} or a fin.\nGreater Tarantulas crawl on the slopes around the mill north-east of the lake."] = "Des Dévoreurs murlocs et des Mande-flots murlocs bordent la rive sud à l'est du pont. N'importe lequel peut porter un {item:1467} ou une nageoire.\nDes Grandes tarentules rampent sur les pentes autour du moulin au nord-est du lac.",
		["Not inside the keep: behind the broken gate on the right of its entrance, by a camp fire, with two guards. Crowd-control a guard and burst him. Two or three players at 23-25; alone, nearer 29."] = "Pas dans le donjon : derrière le portail cassé à droite de son entrée, près d'un feu de camp, avec deux gardes. Neutraliser un garde et le tuer vite. À deux ou trois vers 23-25 ; seul, plutôt vers 29.",
		["On the road east, past the Tower of Azora, head north from the bridge to Stone Cairn Lake. {npc:6172} lies south of the lake: use the {item:6866} on him. The Defias Rogue Wizards around him carry the {item:6846}."] = "Sur la route vers l'est, après la tour d'Azora, allez au nord depuis le pont jusqu'au lac du Cairn. {npc:6172} se trouve au sud du lac : utilisez {item:6866} sur lui. Les sorciers-voleurs défias autour de lui portent {item:6846}.",
		["Only if you are still in {zone:1439} (Ruins of Lordaeron skipped)."] = "Seulement si le groupe est encore à {zone:1439} (Ruines de Lordaeron sautées).",
		["Only once {quest:97914} is handed in: for {npc:3649}, back in Auberdine (06-ashenvale)"] = "Une fois seulement {quest:97914} remis : pour {npc:3649}, de retour à Auberdine (06-ashenvale)",
		["Only the Blackrock Shadowcasters drop the orbs, all through the keep. {npc:334} holds the top floor with two guards and a fire-breathing whelp: a full group only, and keep moving, the keep respawns fast."] = "Seuls les exhalombres Blackrock donnent les orbes, dans tout le donjon. {npc:334} tient le dernier étage avec deux gardes et un dragonnet qui crache du feu : groupe complet seulement, et sans traîner, le donjon réapparaît vite.",
		["Redridge Canyons"] = "Canyons des Carmines",
		["Redridge Mongrels and other gnolls hold the hills east of Three Corners, north of the road; Redridge Thrashers prowl among them, Poachers camp south of the road. Redridge Brutes, for the Iron Pikes and Rivets, hold the hills further north; Dire Condors and Great Goretusks roam the hills east of them."] = "Les bâtards des Carmines et d'autres gnolls occupent les collines à l'est de Trois chemins, au nord de la route ; les vandales des Carmines rôdent parmi eux, les braconniers campent au sud de la route. Les brutes des Carmines, pour les clous et les vis en fer, tiennent les collines plus au nord ; les condors redoutables et les grands broche-tripes errent dans les collines à l'est.",
		["Render's Valley"] = "Vallée des Etripeurs",
		["Shaman training"] = "Entraînement de chaman",
		["South-east from the mill, west of Galardell Valley's gnolls, to the Blackrock camps east of {object:116}. Renegades, Grunts and Outrunners fill them; keep east of the keep, whose orcs are elite."] = "Au sud-est du moulin, à l'ouest des gnolls de la vallée de Galardell, jusqu'aux camps Rochenoire à l'est de {object:116}. Renégats, grunts et coureurs les occupent ; restez à l'est du donjon, dont les orcs sont élites.",
		["Stonewatch elites (group, optional)"] = "Les élites de Guet-de-pierre (groupe, facultatif)",
		["Swim east from the bridge into Lake Everstill; the chest lies on the lake bed."] = "Nagez vers l'est depuis le pont dans le lac Placide ; le coffre gît au fond du lac.",
		["The Auberdine boat docks at Stormwind Harbor. Walk up into the city for training and {npc:1646}, then leave by the main gate and follow the road east through {zone:1429}."] = "Le bateau d'Auberdine accoste au port de Hurlevent. Montez en ville pour l'entraînement et {npc:1646}, puis sortez par la porte principale et suivez la route vers l'est à travers {zone:1429}.",
		["The Stockade, later (dungeon, optional): {npc:859}"] = "La Prison, plus tard (donjon, facultatif) : {npc:859}",
		["The WANTED poster by the town hall door"] = "L'affiche AVIS DE RECHERCHE près de la porte de l'hôtel de ville",
		["The camps below Stonewatch"] = "Les camps sous Guet-de-pierre",
		["The other WANTED poster beside it"] = "L'autre affiche AVIS DE RECHERCHE juste à côté",
		["The road from Elwynn enters Redridge at Three Corners. {npc:464} stands where the roads to Redridge and {zone:1431} meet."] = "La route venant de la forêt d'Elwynn entre dans les Carmines à Trois chemins. {npc:464} se tient là où se rejoignent les routes vers les Carmines et {zone:1431}.",
		["Three Corners"] = "Trois chemins",
		["Tram to {zone:1455}"] = "Tram pour {zone:1455}",
		["Use the {item:6866} on {npc:6172}"] = "Utilisez le {item:6866} sur {npc:6172}",
		["What Comes Around is for the Stockade, the prison dungeon in {zone:1453} after {zone:1431} (group of 5, 24 to 28). Alone? Skip it."] = "Cette quête est pour la Prison, le donjon de {zone:1453} après le {zone:1431} (groupe de 5, 24 à 28). Seul ? La passer.",
		["While you're here: learn Polearms from {npc:11867} ({object:2096}, 1 gold); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Pendant que vous y êtes : apprenez le maniement des armes d'hast auprès de {npc:11867} ({object:2096}, 1 pièce d'or) ; l'arme de mêlée d'un Chasseur vaut surtout par ses caractéristiques, et les armes à deux mains en portent le plus.",
		["While you're here: learn Polearms from {npc:11867} ({object:2096}, 1 gold); two-handers level a Warrior fastest."] = "Pendant que vous y êtes : apprenez le maniement des armes d'hast auprès de {npc:11867} ({object:2096}, 1 pièce d'or) ; les armes à deux mains font progresser un Guerrier le plus vite.",
		["{item:1260}: {quest:19}, elite 24"] = "{item:1260} : {quest:19}, élite 24",
		["{item:1261}: {npc:436}, elite"] = "{item:1261} : {npc:436}, élite",
		["{item:1309}; underwater"] = "{item:1309} ; sous l'eau",
		["{item:1467} on the way"] = "{item:1467} en chemin",
		["{item:15882}: the {object:177790}"] = "{item:15882} : l'{object:177790}",
		["{item:271872}: {npc:214519}, elite 23"] = "{item:271872} : {npc:214519}, élite 23",
		["{item:280911}: Redridge Thrashers"] = "{item:280911} : Vandales des Carmines",
		["{item:3633}: {npc:334}, elite 26, top floor"] = "{item:3633} : {npc:334}, élite 26, dernier étage",
		["{item:6846}: Defias Rogue Wizards"] = "{item:6846} : Sorciers-voleurs défias",
		["{npc:1646}: Thundris' letter from Auberdine"] = "{npc:1646} : Lettre de Thundris depuis Auberdine",
		["{npc:266}, by the docks; upstairs"] = "{npc:266}, près des quais ; à l'étage",
		["{npc:332} is at SI:7 in {object:2100}, {npc:6122} in the {object:2164}'s cellar in the {object:2101}, {npc:376} in the Cathedral of Light."] = "{npc:332} est au SI:7, dans {object:2100}, {npc:6122} dans la cave de {object:2164}, dans {object:2101}, {npc:376} dans la Cathedral of Light.",
		["{npc:332}: {npc:7024} in {zone:1436} takes it, at the end of {zone:1431}"] = "{npc:332} : à rendre à {npc:7024} en {zone:1436}, à la fin de {zone:1431}",
		["{npc:341}: after {quest:89}"] = "{npc:341} : après {quest:89}",
		["{npc:343}, inside"] = "{npc:343}, à l'intérieur",
		["{npc:344}, in the town hall"] = "{npc:344}, dans l'hôtel de ville",
		["{npc:344}: hand it in even if the log does not show it complete"] = "{npc:344} : la rendre même si le journal ne la dit pas finie",
		["{npc:349}, below ground"] = "{npc:349}, sous terre",
		["{npc:376}: {npc:11401} in {zone:1457} takes it, later"] = "{npc:376} : à rendre plus tard à {npc:11401}, à {zone:1457}",
		["{npc:376}: {npc:11406} in {zone:1455} takes it, later"] = "{npc:376} : à rendre plus tard à {npc:11406}, à {zone:1455}",
		["{npc:376}: {npc:258785} in {zone:1455} takes it, later"] = "{npc:376} : à rendre plus tard à {npc:258785}, à {zone:1455}",
		["{npc:382} has one more quest, done alone: the stolen weapons and the Blackrock supplies lie on the ground in the orc camps south-east of {object:116}, where you found the axes."] = "{npc:382} a une quête de plus, faisable seul : les armes volées et les provisions Rochenoire sont au sol dans les camps orcs au sud-est de {object:116}, là où étaient les haches.",
		["{npc:382}: elite quests"] = "{npc:382} : quêtes élites",
		["{npc:435}, below ground"] = "{npc:435}, sous terre",
		["{npc:464} walks around Three Corners: look inside the circle on the map"] = "{npc:464} se promène à Trois chemins : regardez à l'intérieur du cercle sur la carte",
		["{npc:6122}: {npc:6244} in the {zone:1413} takes it, later"] = "{npc:6122} : à rendre plus tard à {npc:6244}, dans {zone:1413}",
		["{npc:859}, by the town hall"] = "{npc:859}, près de l'hôtel de ville",
		["{npc:903}, by the gryphons south of the bridge"] = "{npc:903}, près des griffons au sud du pont",
		["{quest:115} alone: the cave far north of Lakeshire (by the {zone:1428} road) holds Shadowcasters too; pull them one at a time and leave its level 24 boss alone."] = "{quest:115} seul : la grotte loin au nord de Comté-du-Lac (près de la route de {zone:1428}) a aussi des lanceurs d'ombre ; les tirer un par un et laisser son chef de niveau 24.",
		["{zone:1431} is next: follow the road west to Three Corners, then south to Darkshire."] = "{zone:1431} est la suite : suivez la route vers l'ouest jusqu'à Trois chemins, puis au sud jusqu'à Sombre-Comté.",
		["{zone:1453} class quests"] = "Quêtes de classe à {zone:1453}",
		["{zone:1453} flight master"] = "Maître de vol de {zone:1453}",
		["{zone:1453} has no shaman trainer: take the Deeprun Tram from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back."] = "{zone:1453} n'a pas de maître des chamans : prenez le Tram des profondeurs depuis {object:28027} jusqu'à {zone:1455}, entraînez-vous auprès de {npc:258098}, puis reprenez le tram.",
} end)()
t.guides["groupe-alliance/07b-mortemines"] = (function() return {
		["Alone: around 20-21 for the cards, 23 for the Foreman. Two players: fine at 19-20. The cards drop rarely and each player loots their own: skip them if time runs short."] = "Seul : vers 20-21 pour les cartes, 23 pour le contremaître. À deux : faisable vers 19-20. Les cartes tombent rarement et chacun ramasse les siennes : les laisser si le temps manque.",
		["Captain's cabin, top of the ship. Two Blackguards join at the pull, two more at half health: a stun at 51 to 55% skips the second pair. Everyone on the quest loots their own head and their own letter."] = "Cabine du capitaine, en haut du bateau. Deux canailles le rejoignent au début, deux autres à mi-vie : un étourdissement vers 51 à 55 % évite la seconde paire. Chaque joueur qui a la quête ramasse sa tête et sa lettre.",
		["Clear every {npc:641} of the lumber room first, pulling them back to the previous room: the Shredder's Terrify sends you running into them. {npc:643} jumps out when it breaks; he disarms."] = "Vider d'abord chaque {npc:641} de la scierie, en les tirant dans la salle précédente : la peur du broyeur vous jette sur eux. {npc:643} saute dehors quand la machine casse ; il désarme.",
		["Cookie, on the lower deck, is optional: interrupt his healing cast. Do not hearth: leave by the back, along the coast."] = "Macaron, sur le pont inférieur, est facultatif : interrompre son soin. Pas de pierre de foyer : sortir par l'arrière, le long de la côte.",
		["Escort him to Moonbrook"] = "L'escorter jusqu'à Ruisselune",
		["Escort the {npc:467}"] = "Escorter {npc:467}",
		["Fly to {zone:1453}. Mathias Shaw is upstairs at SI:7 in {object:2100}, {npc:1325} in the same building; {npc:656} (tavern), {npc:6579} and {npc:11026} are in the {object:28027}. Train while you are here."] = "Voler vers {zone:1453}. Mathias Shaw est à l'étage du SI:7 dans {object:2100}, {npc:1325} dans le même bâtiment ; {npc:656} (taverne), {npc:6579} et {npc:11026} sont dans {object:28027}. S'entraîner au passage.",
		["For {npc:1719}: the Stockade, after {zone:1431}"] = "Pour {npc:1719} : la Prison, après le {zone:1431}",
		["For {npc:253092} in {zone:1436}"] = "Pour {npc:253092} en {zone:1436}",
		["Goblin Engineers and Craftsmen summon golems: kill or stun the goblin, the golem goes with it. {npc:1763} has an Engineer at his side. Plant the explosives near the middle of the room before pulling him."] = "Les ingénieurs et artisans gobelins invoquent des golems : tuer ou étourdir le gobelin, le golem disparaît avec lui. {npc:1763} a un ingénieur à ses côtés. Poser les explosifs vers le milieu de la salle avant de l'engager.",
		["Group 6b · The Deadmines (dungeon 18-23, optional)"] = "Groupe 6b · Les Mortemines (donjon 18-23, facultatif)",
		["Group of 5, level 18 or more. Pull the two Watchmen away from {npc:644} first, and turn around after every boss: patrols come from behind. {npc:3586}, a rare, may stand in the small tunnel on the left after him: kill his miners first."] = "Groupe de 5, niveau 18 ou plus. Éloigner d'abord les deux guetteurs de {npc:644}, et se retourner après chaque boss : des patrouilles arrivent par derrière. {npc:3586}, un rare, peut se tenir dans le petit tunnel à gauche après lui : tuer ses mineurs d'abord.",
		["He walks the road from the Moonbrook smithy to the Gold Coast Quarry and the {object:83}, and back: wait for him by the smithy. He runs at low health and can drag Moonbrook's Defias along: root or slow him and finish him fast."] = "Il suit la route de la forge de Ruisselune à la carrière de la côte de l'Or et à {object:83}, puis revient : l'attendre devant la forge. Il fuit à faible vie et peut attirer les Défias de Ruisselune : l'immobiliser ou le ralentir et l'achever vite.",
		["He walks to Moonbrook. The hard spot is the fountain: a Defias by the cart and the caster at the fountain join in, so deal with the caster first (Polymorph, Fear). Clearing Moonbrook beforehand makes it easy alone at 18."] = "Il marche jusqu'à Ruisselune. Le passage dur est la fontaine : un Défias près de la charrette et le lanceur de sorts de la fontaine s'en mêlent, neutraliser d'abord le lanceur (Métamorphose, Peur). Nettoyer Ruisselune avant la rend facile seul au niveau 18.",
		["In the cove: two stealthed Defias Blackguards join him by the walkway, kill them before he reaches 66%. At 66% and 33% he stuns the whole group for a few seconds and changes weapons: keep the tank's health up before each."] = "Dans la crique : deux canailles défias camouflées le rejoignent près de la passerelle, les tuer avant qu'il arrive à 66 %. À 66 % et 33 %, il étourdit tout le groupe quelques secondes et change d'arme : garder le tank plein de vie avant chaque fois.",
		["Keep 8 free quest log slots. Everyone takes the quests at their own pace; meet at the Moonbrook entrance for the run."] = "Garder 8 places libres dans le journal. Chacun prend les quêtes à son rythme ; rendez-vous à l'entrée de Ruisselune pour le donjon.",
		["Lakeshire: {npc:266}"] = "Comté-du-Lac : {npc:266}",
		["Moonbrook's smithy hides the mine. Before the portal, the purple area of the minimap holds elite undead miners in pairs: the Miners' Union Cards drop there, not inside, and {npc:626} stands at the far end with a linked add."] = "La forge de Ruisselune cache la mine. Avant le portail, la zone violette de la minicarte abrite des mineurs morts-vivants élites, par paires : les cartes du syndicat des mineurs tombent là, pas dans l'instance, et {npc:626} se tient au bout avec un mob lié.",
		["Not there? Someone is escorting him: wait for him to come back, or group up with them. Since 05/11 he can vanish when crossing a zone border (a known bug, fix on the way): abandon and take the quest again."] = "Absent ? Quelqu'un l'escorte : attendre son retour, ou grouper avec ce joueur. Depuis le 05/11, il peut disparaître en franchissant une limite de zone (bug connu, correction en cours) : abandonner et reprendre la quête.",
		["On the ship. Crowd-control the Squallshaper, kill the Companion, then the Pirate, then Greenskin facing away from the group (Cleave)."] = "Sur le bateau. Neutraliser le façonneur de grains, tuer le compagnon, puis le pirate, puis Peau-Verte tourné dos au groupe (Enchaînement).",
		["Out by the back of the cove; {npc:253279} waits right outside with the {object:581792}. No item reward on this chain: XP and reputation."] = "Sortie par l'arrière de la crique ; {npc:253279} attend juste dehors avec {object:581792}. Pas d'objet en récompense sur cette suite : XP et réputation.",
		["Place the explosives, near the middle of the foundry"] = "Poser les explosifs, vers le milieu de la fonderie",
		["Share each quest with your group: click it in the quest log, then Share. {quest:214} drop from Defias all through the dungeon."] = "Partager chaque quête avec le groupe : la cliquer dans le journal, puis Partager. Les bandanas de {quest:214} tombent sur les Défias de tout le donjon.",
		["The Deadmines"] = "Les Mortemines",
		["The Deadmines: a 5-player dungeon under Moonbrook, in {zone:1436}, best at 18 to 23. This chapter takes its quests on the way, then the dungeon boss by boss. Alone? Skip it: the guide goes on to {zone:1431}."] = "Les Mortemines : un donjon pour 5 joueurs sous Ruisselune, en {zone:1436}, idéal de 18 à 23. Ce chapitre prend ses quêtes en chemin, puis fait le donjon boss par boss. Seul ? Le passer : le guide continue au {zone:1431}.",
		["The cannon door"] = "La porte du canon",
		["The cannon door is open"] = "La porte du canon est ouverte",
		["The cove exit: {npc:253279}"] = "La sortie de la crique : {npc:253279}",
		["The mine outside the portal"] = "La mine avant le portail",
		["The {item:5397} barrel sits in the alcove on the right just before the cannon. Fire the cannon, then step back: a patrol of elites comes out through the broken door. A Rogue can pick the lock instead."] = "Le tonneau de {item:5397} est dans l'alcôve à droite juste avant le canon. Tirer, puis reculer : une patrouille d'élites sort par la porte brisée. Un voleur peut crocheter la serrure à la place.",
		["The {npc:550}"] = "{npc:550}",
		["The {object:581792}, beside her"] = "{object:581792}, à côté d'elle",
		["{item:1875}: {npc:626}, elite"] = "{item:1875} : {npc:626}, élite",
		["{item:1894}: Undead Excavators and Dynamiters, elite"] = "{item:1894} : excavateurs et dynamiteurs morts-vivants, élites",
		["{item:2874}, on VanCleef: right-click it, it opens the Stockade chain"] = "{item:2874}, sur VanCleef : clic droit dessus, elle ouvre la suite vers la Prison",
		["{item:4358} (not Coarse, whatever the text says): Auction House or an engineer friend"] = "{item:4358} (pas la grossière, quoi qu'en dise le texte) : hôtel des ventes ou un ami ingénieur",
		["{item:915}: any Defias"] = "{item:915} : n'importe quel Défias",
		["{npc:11026}: only after {quest:92748}, from Alba in {zone:1436}"] = "{npc:11026} : seulement après {quest:92748}, d'Alba en {zone:1436}",
		["{npc:1325}, SI:7"] = "{npc:1325}, SI:7",
		["{npc:1763}'s foundry"] = "La fonderie de {npc:1763}",
		["{npc:266}, upstairs in the inn"] = "{npc:266}, à l'étage de l'auberge",
		["{npc:467}, at the foot of the tower ramp"] = "{npc:467}, au pied de la rampe de la tour",
		["{npc:642} and {npc:643}"] = "{npc:642} et {npc:643}",
		["{npc:820}, at the top of the tower"] = "{npc:820}, en haut de la tour",
		["{npc:820}, top of the tower"] = "{npc:820}, en haut de la tour",
		["{object:81} rewards"] = "Récompenses à {object:81}",
		["{zone:1431} next: fly to Darkshire if you know its flight path, else ride south through Elwynn."] = "Ensuite le {zone:1431} : voler vers Sombre-Comté si son point de vol est connu, sinon descendre au sud par Elwynn.",
		["{zone:1453} rewards"] = "Récompenses à {zone:1453}",
} end)()
t.guides["groupe-alliance/08-bois-de-la-penombre"] = (function() return {
		["/lay down beside {npc:7207}"] = "/lay down à côté de {npc:7207}",
		["Any spider can drop them, the Black Widow Hatchlings east of {quest:163} most often."] = "N'importe quelle araignée peut les lâcher, le plus souvent les jeunes veuves noires à l'est de {quest:163}.",
		["Back to Darkshire"] = "Retour à Sombre-Comté",
		["Brightwood Grove"] = "Bosquet de Clairbois",
		["Class trainer"] = "Maître de classe",
		["Continue west to {quest:163}. The {object:673515} glows by the ruined house south of the road."] = "Continuer à l'ouest jusqu'à {quest:163}. {object:673515} brille près de la maison en ruine au sud de la route.",
		["Darkshire"] = "Sombre-Comté",
		["Every ghoul of the Raven Hill Cemetery's northern half can drop a rib: Flesh Eaters, Bone Chewers, Plague Spreaders and Brain Eaters.\nCareful: A {npc:948} casts Summon Flesh Eating Worms as it dies, which brings extra adds."] = "Chaque goule de la moitié nord du cimetière de Colline-aux-Corbeaux peut laisser tomber une côte : dévoreurs, mâcheurs d'os, répandeurs de peste et mangeurs de cervelle.\nAttention : Un {npc:948} lance Invocation de vers mangeurs de chair en mourant, ce qui fait apparaître des renforts.",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Fly to {zone:1453}"] = "Prendre un vol pour {zone:1453}",
		["Follow the road north-west past the cemetery to {npc:311}'s camp on the far west edge of the forest. {npc:893} stands beside {npc:311}."] = "Suivez la route vers le nord-ouest après le cimetière jusqu'au camp de {npc:311}, à l'extrême ouest de la forêt. {npc:893} se tient à côté de {npc:311}.",
		["Follow the road south from Three Corners into {zone:1431}; Darkshire lies on the east side of the forest."] = "Suivez la route au sud depuis Trois chemins jusqu'à {zone:1431} ; Sombre-Comté se trouve sur le flanc est de la forêt.",
		["Ghoul Ribs"] = "Côtes de goule",
		["Gooey Spider Legs on the way"] = "Pattes d'araignée fondantes en chemin",
		["Group 7 · {zone:1431}"] = "Groupe 7 · {zone:1431}",
		["Head back east along the road to the Yorgen Farmstead."] = "Revenez vers l'est par la route jusqu'à la ferme des Yorgen.",
		["Head back east to Darkshire."] = "Revenez vers l'est à Sombre-Comté.",
		["Head north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "Remontez vers le nord à travers la forêt d'Elwynn jusqu'à {zone:1453} ; Mathias Shaw se trouve au SI:7, dans {object:2100}.",
		["Head west along the road once more."] = "Repartez une fois de plus vers l'ouest par la route.",
		["Head west along the road out of {quest:163} into {zone:1436}. {npc:7024} watches {npc:7053}'s tower from the hills just inside the border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "Prendre la route vers l'ouest depuis {quest:163} jusqu'en {zone:1436}. {npc:7024} surveille la tour de {npc:7053} depuis les collines juste après la frontière. {npc:7051} (niveau 23) qui garde la tour porte sa clé ; le journal de Klaven est dans le coffre en haut.",
		["Head west to the hermit once more."] = "Retournez une fois de plus vers l'ouest jusqu'à l'ermite.",
		["Her house stands on the hill south-east of Darkshire, above the Tranquil Gardens Cemetery."] = "Sa maison se dresse sur la colline au sud-est de Sombre-Comté, au-dessus du cimetière des jardins paisibles.",
		["Inside"] = "À l'intérieur",
		["Level 22 and 24 spells"] = "Sorts des niveaux 22 et 24",
		["Next: {zone:1453} for training, then the boat from Stormwind Harbor to Auberdine for {zone:1440}."] = "Suivant : {zone:1453} pour l'entraînement, puis le bateau du port de Hurlevent à Auberdine pour {zone:1440}.",
		["No {item:4371} for Look to the Stars? {npc:3133} sells it in the house beside {npc:276}, in limited stock; {npc:1448} in {object:1162} sells it too.\n{npc:276}'s house stands at the east end of town. {npc:3133} sells engineering goods in the house beside it."] = "Pas de {item:4371} pour Regarder les étoiles ? {npc:3133} le vend dans la maison à côté de {npc:276}, en stock limité ; {npc:1448} dans {object:1162} le vend aussi.\nLa maison de {npc:276} se trouve à l'extrémité est de la ville. {npc:3133} vend des articles d'ingénierie dans la maison à côté.",
		["Only if you took the letter after the Ruins of Lordaeron"] = "Seulement si vous avez pris la lettre après les Ruines de Lordaeron",
		["Rabid Dire Wolves roam the woods around the cemetery and {npc:289}, Starving Dire Wolves the hills north-east of him. Pygmy Venom Web Spiders crawl east of the cemetery and drop the venom. Every ghoul of the cemetery's northern half can drop a fang.\nCareful: Wolves and other spider types share the area along the {zone:1436} border, so you can easily pull several mobs at once."] = "Des loups redoutables enragés rôdent dans les bois autour du cimetière et de {npc:289}, des loups redoutables affamés dans les collines au nord-est de lui. Des araignées Tisse-venin pygmées rampent à l'est du cimetière et laissent tomber le venin. Chaque goule de la moitié nord du cimetière peut laisser tomber un croc.\nAttention : Loups et autres types d'araignées partagent la zone le long de la frontière de {zone:1436}, vous pouvez donc facilement attirer plusieurs monstres à la fois.",
		["Raven Hill Cemetery: kill these as you meet them"] = "Cimetière de Colline-aux-Corbeaux : tuez-les au fur et à mesure",
		["Rogue training"] = "Entraînement de voleur",
		["Rot Blossoms"] = "Racines pourries ({item:1598})",
		["Shaman training"] = "Entraînement de chaman",
		["Skeletal Horrors walk the hillside between Darkshire and the Tranquil Gardens Cemetery, south-east of town; they drop the Rot Blossoms."] = "Des squelettes infernaux hantent le flanc de colline entre Sombre-Comté et le cimetière des jardins paisibles, au sud-est de la ville ; ils laissent tomber les racines pourries.",
		["Skeletal Warriors and Skeletal Mages walk among the graves south-east of Darkshire, below {npc:302}'s house on the hill. Every skeleton in {zone:1431} can drop a {item:2378}.\nCareful: Because the skeletons stand near each other, running straight in tends to pull several at once."] = "Les guerriers squelettes et mages squelettes errent parmi les tombes au sud-est de Sombre-Comté, sous la maison de {npc:302} sur la colline. Chaque squelette de {zone:1431} peut laisser tomber {item:2378}.\nAttention : Comme les squelettes sont proches les uns des autres, foncer droit dedans a tendance à en attirer plusieurs à la fois.",
		["The Hushed Bank: kill these as you meet them"] = "La Rive silencieuse : tuez-les au fur et à mesure",
		["The Stockade, later (dungeon, optional): {npc:270}"] = "La Prison, plus tard (donjon, facultatif) : {npc:270}",
		["The cemetery lies north of the village. Skeletal Horrors and Skeletal Fiends walk its southern half. {npc:522}, an elite, wanders the graves: keep away from him."] = "Le cimetière se trouve au nord du village. Des squelettes infernaux et des démons squelettes errent dans sa moitié sud. {npc:522}, un élite, rôde parmi les tombes : tenez-vous à l'écart.",
		["The hermit's shack stands in the woods north-east of the Raven Hill Cemetery."] = "La cabane de l'ermite se trouve dans les bois au nord-est du cimetière de Colline-aux-Corbeaux.",
		["The mound of loose dirt lies south of the farmhouse, by the old stump."] = "Le monticule de poussière se trouve au sud de la ferme, près de la vieille souche.",
		["Train here, in {zone:1453}, before you go on."] = "Entraînez-vous ici, à {zone:1453}, avant de continuer.",
		["Tram to {zone:1455}"] = "Tram pour {zone:1455}",
		["Tranquil Gardens Cemetery"] = "Cimetière des jardins paisibles",
		["Tranquil Gardens Cemetery: kill these as you meet them"] = "Cimetière des jardins paisibles : tuez-les au fur et à mesure",
		["Yorgen Farmstead"] = "Ferme des Yorgen",
		["{item:281046}, from the {object:673515}"] = "{item:281046}, sur le {object:673515}",
		["{item:3372}: {npc:1313}, Alchemy Supplies"] = "{item:3372} : {npc:1313}, Fournitures d'alchimie",
		["{item:4371}, from {npc:3133}, if you have none"] = "{item:4371}, chez {npc:3133}, si vous n'en avez pas",
		["{item:4371}, from {npc:3133}: limited stock. Sold out? {npc:1448} in {object:1162} sells it too."] = "{item:4371}, de {npc:3133} : stock limité. Épuisé ? {npc:1448} dans {object:1162} le vend aussi.",
		["{item:7908}, in the chest"] = "{item:7908}, dans le coffre",
		["{npc:202} on the way"] = "{npc:202} en chemin",
		["{npc:2409}, at the north end of town"] = "{npc:2409}, à l'extrémité nord de la ville",
		["{npc:264}, in the town hall"] = "{npc:264}, à l'hôtel de ville",
		["{npc:265}, in her house by the tavern; inside"] = "{npc:265}, dans sa maison près de la taverne ; à l'intérieur",
		["{npc:265}, inside"] = "{npc:265}, à l'intérieur",
		["{npc:267}, in the town hall"] = "{npc:267}, à l'hôtel de ville",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}, dans la maison derrière l'hôtel de ville",
		["{npc:268}, inside"] = "{npc:268}, à l'intérieur",
		["{npc:270}, in the town hall"] = "{npc:270}, dans l'hôtel de ville",
		["{npc:272}, in the tavern"] = "{npc:272}, dans la taverne",
		["{npc:273}, in the tavern"] = "{npc:273}, dans la taverne",
		["{npc:276}, inside"] = "{npc:276}, à l'intérieur",
		["{npc:288} again: {quest:240}"] = "{npc:288} à nouveau : {quest:240}",
		["{npc:288} hides in the house at the west end of {quest:163}."] = "{npc:288} se cache dans la maison au bout ouest de {quest:163}.",
		["{npc:288}, round the well south of the cemetery"] = "{npc:288}, autour du puits au sud du cimetière",
		["{npc:332}: Poisons, and {item:18160}"] = "{npc:332} : Poisons, et {item:18160}",
		["{npc:531} on the way"] = "{npc:531} en chemin",
		["{npc:533} on the way"] = "{npc:533} en chemin",
		["{npc:6171}: Redemption"] = "{npc:6171} : Rédemption",
		["{npc:6173} and {npc:6171} are in the Cathedral of Light."] = "{npc:6173} et {npc:6171} sont dans la Cathédrale de la Lumière.",
		["{npc:633}, at the south end of town; inside"] = "{npc:633}, au sud de la ville ; à l'intérieur",
		["{npc:633}: {npc:288}' chain, small XP on the trips west you make anyway"] = "{npc:633} : la suite de {npc:288}, un peu d'XP sur les trajets vers l'ouest faits de toute façon",
		["{npc:663}, by the town hall"] = "{npc:663}, près de l'hôtel de ville",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}, taverne du Corbeau écarlate",
		["{npc:888} stands south of the road, at the Yorgen Farmstead."] = "{npc:888} se tient au sud de la route, à la ferme des Yorgen.",
		["{object:81} flight master"] = "{object:81} maître de vol",
		["{quest:2607}: {npc:7207}, in the cellar of the Barracks"] = "{quest:2607} : {npc:7207}, dans la cave de la caserne",
		["{quest:337}: a rare drop from {zone:1431}'s mobs"] = "{quest:337} : un butin rare des monstres de {zone:1431}",
		["{quest:377} is for the Stockade, the prison dungeon in {zone:1453} after {zone:1431} (group of 5, 24 to 28). Alone? Skip it."] = "{quest:377} est pour la Prison, le donjon de {zone:1453} après le {zone:1431} (groupe de 5, 24 à 28). Seul ? La passer.",
		["{zone:1453} has no shaman trainer: take the Deeprun Tram from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the Auberdine boat."] = "{zone:1453} n'a pas de maître des chamans : prenez le Tram des profondeurs depuis {object:28027} jusqu'à {zone:1455}, entraînez-vous auprès de {npc:258098}, puis reprenez le tram pour le bateau d'Auberdine.",
} end)()
t.guides["groupe-alliance/08b-prison"] = (function() return {
		["At the junction, type /target {npc:1720}: if a frame shows, the rare elite (26) is in a cell nearby, with the best loot of the dungeon."] = "Au croisement, taper /target {npc:1720} : si un cadre s'affiche, l'élite rare (26) est dans une cellule proche, avec le meilleur butin du donjon.",
		["Back to {zone:1453}"] = "Retour à {zone:1453}",
		["Cells line both sides, 3 or 4 elites each, and runners flee into the next cell for help: stop them or clear each cell as you pass. {npc:1696} hides in a side cell of this corridor (often first on the right or second on the left); a patrol walks between the two wings."] = "Des cellules des deux côtés, 3 ou 4 élites chacune, et les fuyards courent chercher de l'aide dans la cellule voisine : les arrêter ou vider chaque cellule au passage. {npc:1696} se cache dans une cellule de ce couloir (souvent la 1re à droite ou la 2e à gauche) ; une patrouille circule entre les deux ailes.",
		["Darkshire: {npc:270}"] = "Sombre-Comté : {npc:270}",
		["Defias Prisoners, Convicts and Insurgents"] = "Prisonniers, détenus et insurgés défias",
		["Enter the Stockade"] = "Entrer dans la Prison",
		["Finish the clear"] = "Finir le nettoyage",
		["Fly back to {zone:1453} if you went to Lakeshire or Darkshire."] = "Revenir en vol à {zone:1453} après Comté-du-Lac ou Sombre-Comté.",
		["Fly to Lakeshire and back: a few minutes for the biggest reward of the prison."] = "Aller-retour en vol à Comté-du-Lac : quelques minutes pour la plus grosse récompense de la Prison.",
		["Group 7b · The Stockade (dungeon 24-28, optional)"] = "Groupe 7b · La Prison (donjon 24-28, facultatif)",
		["Keep 6 free quest log slots. Every player takes the quests on their own; meet at the prison gate for the run."] = "Garder 6 places libres dans le journal. Chacun prend les quêtes de son côté ; rendez-vous à la porte de la prison pour le donjon.",
		["Lakeshire: {npc:859}"] = "Comté-du-Lac : {npc:859}",
		["Left at the junction, to the small hall at the end. Clear every room around it first: his Intimidating Shout fears the group into fresh packs. He runs at low health: stop him."] = "À gauche au croisement, jusqu'à la petite salle du bout. Vider d'abord chaque pièce autour : son cri d'intimidation fait fuir le groupe vers des groupes frais. Il fuit à faible vie : l'arrêter.",
		["One Convict short after a full clear? Wait a few minutes at the entrance for the respawn rather than resetting. Two chests, one in each wing. Leaving through the portal drops whatever chases you."] = "Un forçat manquant après un tour complet ? Attendre quelques minutes la réapparition à l'entrée plutôt que réinitialiser. Deux coffres, un par aile. Ressortir par le portail fait lâcher prise à ce qui vous poursuit.",
		["Right at the junction. {npc:1666} sits in a cell (second on the left); {npc:1717} comes with two linked Insurgents and casts Chain Lightning: crowd-control an add and spread out. {npc:1716} waits at the very end: he hits one target hard and his Smoke Bomb stuns, so keep the tank topped up."] = "À droite au croisement. {npc:1666} est dans une cellule (la 2e à gauche) ; {npc:1717} vient avec deux insurgés liés et lance Chaîne d'éclairs : neutraliser un des deux et s'écarter. {npc:1716} attend tout au bout : il frappe fort une seule cible et sa bombe fumigène étourdit, garder le tank plein de vie.",
		["Share each quest with your group: click it in the quest log, then Share. Red Wool Bandanas and the prisoners for Quell the Uprising come from every Defias."] = "Partager chaque quête avec le groupe : la cliquer dans le journal, puis Partager. Les foulards en laine rouge et les prisonniers d'Écraser la rébellion viennent de tous les Défias.",
		["The Stockade"] = "La Prison",
		["The Stockade, {zone:1453}'s prison taken over by rioting Defias, is a group dungeon in the canals between the {object:2101} and {object:2100}, best at 24 to 28. Alone? Skip it: the guide goes on to {zone:1440}."] = "La Prison, la geôle de {zone:1453} prise par des Défias en révolte, est un donjon de groupe dans les canaux entre {object:2101} et {object:2100}, idéal de 24 à 28. Seul ? La passer : le guide continue en {zone:1440}.",
		["The east wing: Kam, {npc:1717} and {npc:1716}"] = "L'aile est : Kam, {npc:1717} et {npc:1716}",
		["The entry corridor and {npc:1696}"] = "Le couloir d'entrée et {npc:1696}",
		["The gate is by {npc:1719}, at the top of the stairs on the canal. Group of 5 at 24 to 28, or 3 at 26 to 29. Every prisoner is elite (23 to 26); the Defias Prisoners disarm, so the tank builds threat before anyone hits."] = "La porte est près de {npc:1719}, en haut des marches sur le canal. Groupe de 5 de 24 à 28, ou de 3 de 26 à 29. Tous les prisonniers sont élites (23 à 26) ; les prisonniers défias désarment, le tank prend la menace avant que les autres frappent.",
		["The west wing: {npc:1663}"] = "L'aile ouest : {npc:1663}",
		["{item:2909}: any Defias inside"] = "{item:2909} : n'importe quel Défias à l'intérieur",
		["{item:2926}, elite 29"] = "{item:2926}, élite 29",
		["{item:3628}, elite 26"] = "{item:3628}, élite 26",
		["{item:3630}: {npc:1696}, elite 24"] = "{item:3630} : {npc:1696}, élite 24",
		["{npc:1666}: his head is for The Fury Runs Deep, a {zone:1437} quest left for later"] = "{npc:1666} : sa tête sert à Fureur dans les Profondeurs, une quête des {zone:1437} laissée pour plus tard",
		["{npc:1719}, at the prison gate"] = "{npc:1719}, à la porte de la prison",
		["{npc:1719}: {quest:389}, after the Deadmines"] = "{npc:1719} : {quest:389}, après les Mortemines",
		["{npc:270}, town hall"] = "{npc:270}, hôtel de ville",
		["{npc:956}, in the stables past the bridge: for the Excavation Site, later"] = "{npc:956}, dans les écuries après le pont : pour le Site de fouilles, plus tard",
		["{quest:392}: for {npc:1646}, {object:2098}"] = "{quest:392} : pour {npc:1646}, {object:2098}",
		["{zone:1440} next: the boat for Auberdine leaves from Stormwind Harbor."] = "Ensuite {zone:1440} : le bateau pour Auberdine part du port de Hurlevent.",
		["{zone:1453} rewards"] = "Récompenses à {zone:1453}",
		["{zone:1453}: Stockade quests"] = "{zone:1453} : quêtes de la Prison",
} end)()
t.guides["groupe-alliance/09-orneval-paluns"] = (function() return {
		["A spot taken by the Horde? Skip the step (Skip button) and come back later. On the Normal ruleset, only players flagged for PvP can be attacked (PvP icon on the portrait). The {zone:1437}, later in this guide, have no Horde quests."] = "Un endroit occupé par la Horde ? Passer l'étape (bouton Passer) et y revenir plus tard. Avec les règles Normal, seuls les joueurs marqués JcJ peuvent être attaqués (icône JcJ sur le portrait). Plus loin dans ce guide, {zone:1437} : aucune quête de la Horde.",
		["Astranaar"] = "Astranaar",
		["Astranaar flight master"] = "Maître de vol d'Astranaar",
		["Auberdine flight master"] = "Maître de vol d'Auberdine",
		["Auberdine: {npc:8997}"] = "Auberdine : {npc:8997}",
		["Auberdine: {npc:8997} (Blackfathom Deeps, optional)"] = "Auberdine : {npc:8997} (Profondeurs de Brassenoire, facultatif)",
		["Back down the portal to Rut'theran Village, then the flight to Auberdine."] = "Redescendre par le portail au village de Rut'theran, puis le vol pour Auberdine.",
		["Back to Auberdine"] = "Retour à Auberdine",
		["Bathran's Haunt: kill these as you meet them"] = "Repaire de Bathran : tuez-les au fur et à mesure",
		["Below ground"] = "Sous terre",
		["Black, Crimson and Monstrous Oozes fill Ironbeard's Tomb, just west of the road to {object:376} and north of Einar's camp. Any ooze there may hold {npc:2111}'s bag.\nMosshide Fenrunners and Mistweavers roam the riverbanks just west and south of {npc:1244}; almost every one drops flint."] = "Des limons noirs, cramoisis et monstrueux remplissent la tombe d'Ironbeard, juste à l'ouest de la route vers {object:376} et au nord du camp d'Einar. N'importe quel limon peut contenir le sac de {npc:2111}.\nDes paludiers et tisseurs de brumes Poil-moussu rôdent sur les berges juste à l'ouest et au sud de {npc:1244} ; presque tous laissent du silex.",
		["Blackfathom Deeps"] = "Profondeurs de Brassenoire",
		["Blackfathom Deeps: a 5-player dungeon on the north-west coast of {zone:1440}, best at 24 to 28. Its quests are taken here and on the way, the dungeon is run from the Zoram Strand, and they are handed in back at Auberdine. Alone? Skip it: the guide goes on in {zone:1440}."] = "Profondeurs de Brassenoire : un donjon pour 5 joueurs sur la côte nord-ouest d'{zone:1440}, idéal de 24 à 28. Ses quêtes se prennent ici et en chemin, le donjon se fait depuis la grève de Zoram, et elles se rendent au retour à Auberdine. Seul ? Le passer : le guide continue en {zone:1440}.",
		["Blackfathom Deeps: a 5-player dungeon on the north-west coast of {zone:1440}, best at 24 to 28. This guide takes its quests on the way, runs it from the Zoram Strand, then hands them in at Auberdine. Alone? Skip it: the guide goes on in {zone:1440}."] = "Profondeurs de Brassenoire : un donjon pour 5 joueurs sur la côte nord-ouest d'{zone:1440}, idéal de 24 à 28. Le guide prend ses quêtes en chemin, fait le donjon depuis la grève de Zoram, puis les rend à Auberdine. Seul ? Le passer : le guide continue en {zone:1440}.",
		["Blackfathom Deeps: along the way"] = "Profondeurs de Brassenoire : en chemin",
		["Blackfathom Deeps: before going in"] = "Profondeurs de Brassenoire : avant d'entrer",
		["Blackfathom Deeps: leave"] = "Profondeurs de Brassenoire : sortir",
		["Blackfathom Deeps: {npc:4787}"] = "Profondeurs de Brassenoire : {npc:4787}",
		["Blackfathom Deeps: {npc:4787} (without the {zone:1457} quest)"] = "Profondeurs de Brassenoire : {npc:4787} (sans la quête de {zone:1457})",
		["Blackfathom Deeps: {npc:4831} and {npc:6243}"] = "Profondeurs de Brassenoire : {npc:4831} et {npc:6243}",
		["Blackfathom Deeps: {npc:4832}"] = "Profondeurs de Brassenoire : {npc:4832}",
		["Blackfathom Deeps: {npc:4887}'s pool"] = "Profondeurs de Brassenoire : le bassin de {npc:4887}",
		["Bluegill Marsh"] = "Marais des Branchies-bleues",
		["Boat to {object:1162}"] = "Bateau pour {object:1162}",
		["Cast Teleport: {zone:1450}"] = "Lancez Téléportation : {zone:1450}",
		["Cathedral of Light"] = "Cathédrale de la Lumière",
		["Cave Stalkers and Leech Stalkers fill Thelgen Rock, the cave south-east of the excavation site."] = "Des traqueuses des grottes et des traqueuses sanguines infestent le rocher de Thelgen, la grotte au sud-est du site de fouilles.",
		["Collected all through the dungeon: the brain stems from the nagas and the Fallenroot satyrs (those outside the portal drop them too), the Twilight Pendants from the Twilight's Hammer cultists, about 4 kills in 5 for each. Every player with the quest loots their own; with a full group on them, a second run may be needed."] = "À ramasser dans tout le donjon : les troncs cérébraux sur les nagas et les satyres (ceux d'avant le portail en lâchent aussi), les pendentifs du Crépuscule sur les cultistes du Marteau du crépuscule, environ 4 fois sur 5 pour chacun. Chaque joueur qui a la quête ramasse les siens ; avec tout le groupe dessus, un second passage peut être nécessaire.",
		["Contested zone too: {object:19559} (Horde) lies west of {object:19555}, and more Horde quest givers stand in the far south-east. Stay grouped."] = "Zone contestée elle aussi : {object:19559} (Horde) est à l'ouest de {object:19555}, et d'autres donneurs de quêtes de la Horde se tiennent tout au sud-est. Rester groupés.",
		["Contested zone: Horde players quest here too, from Zoram'gar Outpost (west coast) and Splintertree Post (east). Their quests use the same spots as this guide: the Zoram Strand nagas, the Thistlefur camp north of Astranaar, the Foulweald, Mystral Lake. Stay grouped there."] = "Zone contestée : des joueurs de la Horde y font aussi leurs quêtes, depuis l'avant-poste de Zoram'gar (côte ouest) et le poste de Bois-brisé (à l'est). Leurs quêtes passent par les mêmes endroits que ce guide : les nagas de la grève de Zoram, le camp Crin-de-Chardon au nord d'Astranaar, les Vile-sylve, le lac Mystral. Y rester groupés.",
		["Escort {npc:11218} to his bag at the southern edge of {zone:1439}, then hand the quest in at {object:19863}."] = "Escorter {npc:11218} jusqu'à son sac au sud de {zone:1439}, puis rendre la quête au {object:19863}.",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Fen Creepers hide in the marsh pools north-west of the Green Belt.\nCareful: When out of combat, Fen Creepers cast Sneak from time to time, so they are stealthed and hard to see."] = "Des rampants des tourbières se cachent dans les mares au nord-ouest de la Ceinture verte.\nAttention : Hors combat, les rampants des tourbières lancent Camouflage par moments, ils sont donc camouflés et difficiles à voir.",
		["Fly to Auberdine"] = "Envolez-vous pour Auberdine",
		["Fly to Rut'theran Village"] = "Envolez-vous vers le village de Rut'theran",
		["Follow the coast north out of Menethil. Bluegill Murlocs fill the marsh; {npc:1259} walks with a pack in the middle of it."] = "Sortez de Menethil en longeant la côte vers le nord. Les Murlocs Branchie-bleue grouillent dans le marais ; {npc:1259} se promène avec un groupe en son milieu.",
		["Follow the coast north to the Zoram Strand. {npc:3846} camps on the beach; Wrathtail nagas fill the shore."] = "Suivez la côte vers le nord jusqu'au Rivage de Zoram. {npc:3846} campe sur la plage ; les nagas Queue-de-rage couvrent le rivage.",
		["Follow the road east to the Howling Vale; {npc:3916} stands by the moonwell.\nThe moonwell lies in the hills north-east of Astranaar."] = "Suivez la route vers l'est jusqu'à la Vallée des Hurlements ; {npc:3916} se tient près du puits de lune.\nLe puits de lune se trouve dans les collines au nord-est d'Astranaar.",
		["Follow the road east. Young Wetlands Crocolisks lurk in the pools north of the excavation site."] = "Suivez la route vers l'est. Des Jeunes crocilisques des Paluns ({npc:1417}) rôdent dans les mares au nord du site de fouilles.",
		["For Bolvar Fordragon in {object:2117}: keep it"] = "Pour Bolvar Fordragon, dans le {object:2117} : gardez-la",
		["For the giant crocolisks of the north coast, on your next visit"] = "Pour les crocilisques géants de la côte nord, lors de votre prochaine visite",
		["For {npc:2228} in Southshore: keep it"] = "Pour {npc:2228} à Austrivage : gardez-le",
		["From Auberdine to Rut'theran Village: the flight, or the boat from the Auberdine dock for whoever never learned that flight path; then the portal up to {zone:1457}. {npc:4783} and {npc:4784} stand with the {object:92525}."] = "D'Auberdine au village de Rut'theran : le vol, ou le bateau du quai d'Auberdine pour qui n'a jamais appris ce trajet ; puis le portail qui monte à {zone:1457}. {npc:4783} et {npc:4784} se tiennent avec {object:92525}.",
		["From Auberdine to Rut'theran Village: the flight, or the boat from the Auberdine dock for whoever never learned that flight path; then the portal up to {zone:1457}. {npc:4784} stands with the {object:92525}."] = "D'Auberdine au village de Rut'theran : le vol, ou le bateau du quai d'Auberdine pour qui n'a jamais appris ce trajet ; puis le portail qui monte à {zone:1457}. {npc:4784} se tient avec {object:92525}.",
		["From Stormwind Harbor take the boat to Auberdine; {npc:3649} stands at the north end of the village. Then head south along the road through {zone:1439}."] = "Depuis le port de Hurlevent, prenez le bateau pour Auberdine ; {npc:3649} se tient au bout nord du village. Puis dirigez-vous vers le sud le long de la route à travers {zone:1439}.",
		["Group 8 · {zone:1440}, {zone:1437} & Stonetalon"] = "Groupe 8 · {zone:1440}, {zone:1437} et les Serres-Rocheuses",
		["Head east along the {zone:1437} road, south through {object:1668} into {zone:1432} and west through the tunnel into {zone:1426} to {zone:1455}."] = "Prenez la route de {zone:1437} vers l'est, au sud par {object:1668} vers {zone:1432} et à l'ouest par le tunnel vers {zone:1426} jusqu'à {zone:1455}.",
		["Head south past Mystral Lake into the Talondeep Path tunnel; it comes out in Stonetalon's {object:19555}. {npc:4080} and {npc:4077} camp on the Webwinder Path south-west of the crag."] = "Dirigez-vous au sud en passant le lac Mystral pour entrer dans le tunnel de la Perce des Serres ; il débouche dans les Serres-Rocheuses, au {object:19555}. {npc:4080} et {npc:4077} campent sur le sentier des Tisseuses, au sud-ouest de la combe.",
		["Head west to the shore of Lake Falathim. Teronis lies among the Saltspittle murlocs; any murloc can drop the {item:5463}."] = "Allez vers l'ouest jusqu'au rivage du lac Falathim. Teronis se trouve parmi les murlocs Crache-sel ; n'importe quel murloc peut laisser tomber le {item:5463}.",
		["In the quest log before going in: {quest:1275} ({npc:8997}, Auberdine). If you took them: {quest:1198} and {quest:1199} ({zone:1457}, a detour), {quest:971} ({npc:2786}, {zone:1455}, offered in Group 3: too far to fetch now). Nothing to bring."] = "Dans le journal avant d'entrer : {quest:1275} ({npc:8997}, Auberdine). Si elles ont été prises : {quest:1198} et {quest:1199} ({zone:1457}, un détour), {quest:971} ({npc:2786}, {zone:1455}, proposée au Groupe 3 : trop loin pour aller la chercher maintenant). Rien à apporter.",
		["Inside"] = "À l'intérieur",
		["Into {zone:1426}"] = "Vers {zone:1426}",
		["Into {zone:1432}"] = "Dans les {zone:1432}",
		["Into {zone:1455}"] = "Vers {zone:1455}",
		["Into {zone:1457}"] = "Vers {zone:1457}",
		["Keep 5 free quest log slots. Every player takes the quests from the givers; sharing works too (click the quest in the log, then Share)."] = "Garder 5 places libres dans le journal. Chaque joueur prend les quêtes auprès des donneurs ; le partage marche aussi (clic sur la quête dans le journal, puis Partager).",
		["Kelris waits in the ceremonial chamber before the last room. Interrupt his Sleep and kill his adds first. Every player on {quest:1200} loots their own head. {npc:4829}, behind him, is optional: no quest, good loot."] = "Kelris attend dans la salle de cérémonie avant la dernière salle. Interrompre son Sommeil et tuer ses aides d'abord. Chaque joueur qui a {quest:1200} ramasse sa propre tête. {npc:4829}, derrière lui, est facultatif : pas de quête, du bon butin.",
		["Leave by the portal and go on along the coast: {npc:8997}'s and the {zone:1457} hand-ins wait for the end of {zone:1440}, at Auberdine."] = "Sortir par le portail et continuer le long de la côte : les rendus de {npc:8997} et de {zone:1457} attendent la fin d'{zone:1440}, à Auberdine.",
		["Made by the {item:5456} from the 5 bracers"] = "Obtenu avec {item:5456} à partir des 5 bracelets",
		["Melyria and {npc:3901}"] = "Melyria et {npc:3901}",
		["Menethil"] = "Menethil",
		["Mosshide Gnolls and Mongrels hold the hills south-east of the Green Belt."] = "Les gnolls et bâtards Poil-moussu tiennent les collines au sud-est de la Ceinture verte.",
		["Mottled Raptors and Screechers roam the hills west of the excavation site.\nCareful: Once a {npc:1021} drops to 30% health, it calls for help from creatures within 20 yd. Mottled Screechers frequently come in packs of three, and raptors summoned by their calls for help may also join the fight."] = "Des Raptors tachetés et des Hurleurs tachetés parcourent les collines à l'ouest du site de fouilles.\nAttention : quand un {npc:1021} tombe à 30 % de vie, il appelle à l'aide les créatures dans un rayon de 20 m. Les Hurleurs tachetés vont souvent par trois, et les raptors attirés par leurs appels peuvent aussi se joindre au combat.",
		["Mystral Lake"] = "Lac Mystral",
		["Next: fly to Darkshire."] = "Ensuite : volez vers Sombre-Comté.",
		["North of Maestra's Post, plant bundles lie around the ruins of Bathran's Haunt. Dark Strand cultists hold the ruins just south of them: any of them can drop the {item:5366}."] = "Au nord du poste de Maestra, des fagots de plantes gisent autour des ruines du Repaire de Bathran. Des sectateurs de la Rive noire occupent les ruines juste au sud : n'importe lequel peut laisser tomber le {item:5366}.",
		["Not every elemental drops one (about 1 in 5 in the data): this line counts them"] = "Tous les élémentaires n'en donnent pas (environ 1 sur 5 d'après les données) : cette ligne les compte",
		["Only after Crocs of the Sky, a later quest of his: not offered? Carry on"] = "Seulement après Crocs of the Sky, une de ses quêtes suivantes : pas proposée ? Continuer",
		["Only if you looted {quest:337} in {zone:1431}"] = "Seulement si vous avez ramassé {quest:337} à {zone:1431}",
		["Only with {item:5352} from {zone:1439}: {npc:2786}, the {object:32383}"] = "Seulement avec {item:5352} de {zone:1439} : {npc:2786}, {object:32383}",
		["Raptor valley"] = "La vallée des raptors",
		["Share the quests with your group: click each in the quest log, then Share."] = "Partager les quêtes avec le groupe : clic sur chacune dans le journal, puis Partager.",
		["Take the Deeprun Tram from {object:171524} to {zone:1453}'s {object:28027}, then walk to the {object:2098}."] = "Prenez le Tram des profondeurs de {object:171524} vers {object:28027} de {zone:1453}, puis marchez jusqu'au {object:2098}.",
		["Take the boat from Stormwind Harbor to Auberdine. Join the two half pendants into the {item:15885} and cast Teleport: {zone:1450}: {npc:11802} is in Nighthaven. Then {npc:11800} in Nighthaven flies Druids straight to Rut'theran Village. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Prenez le bateau du port de Hurlevent pour Auberdine. Assemblez les deux demi-pendentifs pour former le {item:15885} et lancez Téléportation : {zone:1450} : {npc:11802} se trouve à Havrenuit. Ensuite, {npc:11800} à Havrenuit emmène les druides directement à Rut'theran. {npc:11802} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
		["Take the portal up to the Cenarion Enclave, then fly back to Auberdine."] = "Prenez le portail menant à l'Enclave cénarienne, puis revenez en vol à Auberdine.",
		["Thaelrid of the {object:92525} waits in an underwater cave whose entrance is south-east of {npc:4887}'s pool. He offers {quest:1200} without {quest:1198} too. Talk to him BEFORE killing Kelris; not offered? Carry on."] = "Thaelrid, de {object:92525}, attend dans une grotte sous l'eau dont l'entrée est au sud-est du bassin de {npc:4887}. Il propose {quest:1200} même sans {quest:1198}. Lui parler AVANT de tuer Kelris ; pas proposée ? Continuer.",
		["Thaelrid of the {object:92525} waits in an underwater cave whose entrance is south-east of {npc:4887}'s pool. Talk to him BEFORE killing Kelris: Kelris's head drops only for players who already hold {quest:1200}."] = "Thaelrid, de {object:92525}, attend dans une grotte sous l'eau dont l'entrée est au sud-est du bassin de {npc:4887}. Lui parler AVANT de tuer Kelris : la tête de Kelris ne tombe que pour les joueurs qui ont déjà {quest:1200}.",
		["The Bluegill hovels"] = "Les huttes des Branchie-bleue",
		["The Foulweald"] = "Les Vile-sylve",
		["The Foulweald furbolgs live in the woods south of the road, south-east of Astranaar. The Den Watcher and the Ursas guard the den."] = "Les furbolgs Vile-sylve vivent dans les bois au sud de la route, au sud-est d'Astranaar. Le protecteur et les ursas gardent la tanière.",
		["The Green Belt"] = "La Ceinture Verte",
		["The Green Belt: kill these as you meet them"] = "La Ceinture verte : tuez-les au fur et à mesure",
		["The Mosshide gnolls"] = "Les gnolls Poil-moussu",
		["The Venture Co. clear the forest of {object:19555}. Loggers and Deforesters work all over it; the Operators run the shredders and one carries the blueprints."] = "La KapitalRisk déboise la forêt de {object:19555}. Bûcherons et Déforestiers y travaillent partout ; les Opérateurs pilotent les déchiqueteuses et l'un d'eux porte les plans.",
		["The Zoram Strand"] = "La grève de Zoram",
		["The bigger raptors hunt in the valley just west of the dig."] = "Les plus gros raptors chassent dans la vallée juste à l'ouest des fouilles.",
		["The excavation site sits on the hill south of the road."] = "Le site de fouilles se trouve sur la colline au sud de la route.",
		["The great turtle {npc:4887} lives in the first big pool. The {item:5359} lies in a chest underwater, in an alcove north of that pool: swim down for it, every player with the quest opens the chest. {npc:4787} waits in another underwater cave, its entrance south-east of the same pool (next step)."] = "La grande tortue {npc:4887} vit dans le premier grand bassin. {item:5359} est dans un coffre sous l'eau, dans une alcôve au nord de ce bassin : plonger le chercher, chaque joueur qui a la quête ouvre le coffre. {npc:4787} attend dans une autre grotte sous l'eau, dont l'entrée est au sud-est du même bassin (étape suivante).",
		["The portal is in the half-sunken temple at the north end of the Zoram Strand: swim down to it. Group of 5 at 24 to 28; every enemy inside is elite."] = "Le portail est dans le temple à moitié englouti au nord de la grève de Zoram : y descendre à la nage. Groupe de 5 de 24 à 28 ; tous les ennemis à l'intérieur sont élites.",
		["The raptor hills"] = "Les collines des raptors",
		["The tears glow on the small isle east of Astranaar."] = "Les larmes brillent sur la petite île à l'est d'Astranaar.",
		["The timber planks and iron pallets lie in the water all around {object:1162}, west, north and east of the town, on the bottom or floating: swim for them. Giant crocolisks guard some of the iron. Lowering ground clutter makes them easier to see."] = "Les planches de bois et les palettes de fer sont dans l'eau tout autour de {object:1162}, à l'ouest, au nord et à l'est de la ville, au fond ou flottantes : y aller à la nage. Des crocilisques géants gardent une partie du fer. Baisser la densité de l'herbe (détails du sol) les rend plus visibles.",
		["The two stand together at the western end of the road.\nSouth of the murlocs, {npc:3585} waits at the {object:13352}."] = "Tous deux se tiennent ensemble à l'extrémité ouest de la route.\nAu sud des murlocs, {npc:3585} attend au {object:13352}.",
		["Thelgen Rock"] = "Rocher de Thelgen",
		["Three containers in the murloc hovels, south to north: the {object:261}, then the {object:142151}, then the {object:259} at the north end."] = "Trois conteneurs dans les huttes des murlocs, du sud au nord : {object:261}, puis {object:142151}, puis {object:259} à l'extrémité nord.",
		["To {object:1162}"] = "Vers {object:1162}",
		["Tram to {zone:1453}"] = "Tram pour {zone:1453}",
		["Two more Blackfathom quests wait in {zone:1457}, with the {object:92525}: {quest:1198}, then {quest:1200} from Thaelrid inside the dungeon, and {quest:1199}. About 19,600 XP with the hand-ins, and a blue reward. The detour: the boat from the Auberdine dock to Rut'theran Village (Night Elves fly), the portal up to {zone:1457}, then back; the hand-ins need the same trip after {zone:1440}. Short on time? Skip it."] = "Deux autres quêtes de Brassenoire attendent à {zone:1457}, chez {object:92525} : {quest:1198}, puis {quest:1200} donnée par Thaelrid dans le donjon, et {quest:1199}. Environ 19 600 XP avec les rendus, et une récompense bleue. Le détour : le bateau du quai d'Auberdine jusqu'au village de Rut'theran (les Elfes de la nuit volent), le portail qui monte à {zone:1457}, puis le retour ; les rendus demandent le même trajet après {zone:1440}. Pressé ? Le passer.",
		["Warlocks: The {item:6898} ({npc:6247}, in the {zone:1413}) takes three fragments from the Twilight Acolytes here and one from {object:1680}; it is not on this route."] = "Démonistes : {item:6898} ({npc:6247}, dans {zone:1413}) demande trois fragments sur les acolytes du Crépuscule d'ici et un dans {object:1680} ; elle n'est pas sur ce parcours.",
		["Webwinder Path"] = "Sentier des Tisseuses",
		["West of Mystral Lake, the stardust bushes grow among the ruins."] = "À l'ouest du Lac Mystral, les buissons couverts de poussière d'étoile poussent parmi les ruines.",
		["Whelgar's Excavation Site"] = "Excavations de Whelgar",
		["While you're here: learn Two-Handed Axes from {npc:11865} ({object:32359}, 10 silver); two-handers level a Paladin fastest."] = "Pendant que vous êtes ici : apprenez Haches à deux mains auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font monter un paladin le plus vite.",
		["While you're here: learn Two-Handed Axes from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "Pendant que vous êtes ici : apprenez Haches à deux mains auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
		["While you're here: learn Two-Handed Maces from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "Pendant que vous êtes ici : apprenez Masses à deux mains auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
		["With 5 bracers in the bags: right-click it in the bags"] = "Avec 5 bracelets dans les sacs : clic droit dessus, dans les sacs",
		["Young crocolisks"] = "Jeunes crocilisques",
		["{item:15885}: join the two halves"] = "{item:15885} : assemblez les deux moitiés",
		["{item:5359}, in the {object:13949}"] = "{item:5359}, dans {object:13949}",
		["{item:5424}, in the ruins on the shore"] = "{item:5424}, dans les ruines du rivage",
		["{item:5879}: Twilight's Hammer cultists"] = "{item:5879} : cultistes du Marteau du crépuscule",
		["{item:5952}: Blackfathom nagas, Fallenroot satyrs"] = "{item:5952} : nagas et satyres du donjon",
		["{npc:1076}, below ground"] = "{npc:1076}, sous terre",
		["{npc:11218} sleeps at the {object:12893} in southern {zone:1439}. Use the {item:13536} to wake him and lead him south along the road to his bag, by the three-way fork at the southern edge of {zone:1439}; blow the horn again whenever he falls asleep. Do not cross into {zone:1440} with him: on Forever the escort fails there.\nCareful: Two scripted ambushes of three mobs each attack along the road.\nTimed quest: 25 minutes, hand-in to {npc:11219} at {object:19863} included. Wake him only when ready to go straight on."] = "{npc:11218} dort près du {object:12893} au sud de {zone:1439}. Utiliser le {item:13536} pour le réveiller et le conduire vers le sud le long de la route jusqu'à son sac, près de la fourche à trois branches au sud de {zone:1439} ; sonner du cor à nouveau chaque fois qu'il s'endort. Ne pas passer en {zone:1440} avec lui : sur Forever, l'escorte y échoue.\nAttention : deux embuscades scriptées de trois monstres chacune attaquent le long de la route.\nQuête chronométrée : 25 minutes, rendu à {npc:11219} au {object:19863} compris. Ne le réveiller qu'une fois prêt à enchaîner.",
		["{npc:11406} and {npc:258785} are in the {object:32386}, in the {object:32362}."] = "{npc:11406} et {npc:258785} sont dans le {object:32386}, dans {object:32362}.",
		["{npc:11406}: Chastise"] = "{npc:11406} : Châtier",
		["{npc:1239}, in the inn"] = "{npc:1239}, à l'auberge",
		["{npc:1242}, on the pier north of the inn"] = "{npc:1242}, sur la jetée au nord de l'auberge",
		["{npc:1242}: for {npc:2104} in the keep. He offers it only after this hand-in"] = "{npc:1242} : pour {npc:2104}, dans le donjon. Il ne la propose qu'après ce rendu",
		["{npc:1244}: {quest:98283}, an elite raptor, done in Group 12"] = "{npc:1244} : {quest:98283}, un raptor élite, à faire au Groupe 12",
		["{npc:1440}, in the Royal Library"] = "{npc:1440}, dans la Bibliothèque royale",
		["{npc:1444}, in the {object:2098}"] = "{npc:1444}, sur la {object:2098}",
		["{npc:1480}, inside"] = "{npc:1480}, à l'intérieur",
		["{npc:1573}, in the {object:32372}"] = "{npc:1573}, à {object:32372}",
		["{npc:2086}, by the keep; inside"] = "{npc:2086}, près du donjon ; à l'intérieur",
		["{npc:2092}'s quest in {zone:1455} needs level 28. If you are short of it after these hand-ins, grind the Dragonmaw orcs at the camps along the road east to {object:1668} before you go on."] = "La quête de {npc:2092} en {zone:1455} requiert le niveau 28. S'il vous manque après ces remises, farmez les orcs Gueule-de-dragon aux camps le long de la route à l'est vers {object:1668} avant de continuer.",
		["{npc:2093} camps by the road; {npc:1244} stands farther east, by the river."] = "{npc:2093} campe au bord de la route ; {npc:1244} se tient plus à l'est, près de la rivière.",
		["{npc:2094} stands by the north gate."] = "{npc:2094} se tient près de la porte nord.",
		["{npc:2094}, by the north gate"] = "{npc:2094}, près de la porte nord",
		["{npc:2096}, by the north gate"] = "{npc:2096}, près de la porte nord",
		["{npc:2096}: he won't offer 305 while you carry it"] = "{npc:2096} : il ne propose pas la 305 tant que vous l'avez sur vous",
		["{npc:2097}, by the north gate"] = "{npc:2097}, près de la porte nord",
		["{npc:2104} stands in Menethil Keep, a short walk from {npc:1242}."] = "{npc:2104} se trouve au Donjon de Menethil, à quelques pas de {npc:1242}.",
		["{npc:2104}, by the keep"] = "{npc:2104}, près du donjon",
		["{npc:2104}, on the top floor"] = "{npc:2104}, au dernier étage",
		["{npc:210995} may not offer these to every class; if he doesn't, carry on.; walks around The Talondeep Path: the map marks where to look"] = "{npc:210995} ne propose pas forcément ces quêtes à toutes les classes ; s'il ne le fait pas, continuez. ; se promène autour de la Perce des Serres : la carte indique où chercher",
		["{npc:3649}: Alexston's reply, if you took it in {zone:1453}"] = "{npc:3649} : la réponse d'Alexston, si vous l'avez prise à {zone:1453}",
		["{npc:3664} and his voidwalkers hold the Ruins of Ordil'Aran south of the shrine. Pull his guards first."] = "{npc:3664} et ses marcheurs du Vide occupent les ruines d'Ordil'Aran au sud du sanctuaire. Tirez d'abord ses gardes.",
		["{npc:3691}, in the inn"] = "{npc:3691}, à l'auberge",
		["{npc:3885} stands at the Silverwind Refuge on the east shore of Mystral Lake; {npc:210995} camps on its west shore. Befouled Water Elementals wade in the lake between them.\nThe game counts only the {item:5455}, not the bracers: the elementals' tooltip shows no count, so follow the bracer line of this step. Only Intact Elemental Bracers count, other bracers are junk. With 5 in the bags, right-click the {item:5456}: it turns them into the {item:5455}, then hand it in."] = "{npc:3885} se trouve au refuge de Vent-argent sur la rive est du lac Mystral ; {npc:210995} campe sur la rive ouest. Des élémentaires d'eau souillés pataugent dans le lac entre eux.\nLe jeu ne compte que {item:5455}, pas les bracelets : l'infobulle des élémentaires n'affiche aucun compteur, suivre la ligne des bracelets de cette étape. Seuls les Bracelets élémentaires intacts comptent, les autres bracelets sont de la camelote. Avec 5 bracelets dans les sacs, clic droit sur {item:5456} : il les change en {item:5455}, puis rendre la quête.",
		["{npc:3894}, inside"] = "{npc:3894}, à l'intérieur",
		["{npc:3970}: for {npc:1480} in Menethil, at the end of this guide; inside"] = "{npc:3970} : pour {npc:1480} à Menethil, à la fin de ce guide ; à l'intérieur",
		["{npc:3987} (25) leads the Thistlefur furbolgs at the camp north of Astranaar. Clear his guards first, one at a time.\nCareful: The furbolgs near him usually join in when he is pulled. Killing the ones along his path first lets you fight him alone."] = "{npc:3987} (25) dirige les furbolgs Chardon-vert au camp au nord d'Astranaar. Éliminez d'abord ses gardes, un par un.\nAttention : Les furbolgs près de lui se joignent généralement au combat quand il est tiré. Tuer ceux le long de son chemin d'abord vous permet de l'affronter seul.",
		["{npc:4201}, in the hut north of them; inside"] = "{npc:4201}, dans la hutte au nord ; à l'intérieur",
		["{npc:4201}, inside"] = "{npc:4201}, à l'intérieur",
		["{npc:4276} mines in the Windshear Mine at the east end of the crag. Talk to him and fend off the Venture Co. raiders while he mines.\nCareful: The kobolds arrive in waves. The first wave is melee fighters, and the second adds casters to the mix. Regular mobs in the mine respawn quickly and can join the fight while the waves are coming. A group is recommended."] = "{npc:4276} mine dans la mine des Cisailles, à l'extrémité est de la combe. Parlez-lui et repoussez les assaillants de la KapitalRisk pendant qu'il mine.\nAttention : Les kobolds arrivent par vagues. La première vague est composée de combattants au corps à corps, et la seconde ajoute des lanceurs de sorts. Les mobs normaux de la mine réapparaissent rapidement et peuvent se joindre au combat pendant l'arrivée des vagues. Un groupe est recommandé.",
		["{npc:4784}, with the 10 pendants"] = "{npc:4784}, avec les 10 pendentifs",
		["{npc:4831}, the second boss, comes with two guards: interrupt her Forked Lightning, it chains between players standing close (spread out). {npc:6243}, the murloc of the side cave, is optional: pull his murlocs one at a time; the stone behind him gives the Blessing of Blackfathom. The Twilight's Hammer cultists come after them."] = "{npc:4831}, le deuxième boss, vient avec deux gardes : interrompre son Éclair fourchu, qui rebondit entre les joueurs proches (s'écarter). {npc:6243}, le murloc de la grotte latérale, est facultatif : tirer ses murlocs un par un ; la pierre derrière lui donne la Bénédiction de Brassenoire. Les cultistes du Marteau du crépuscule viennent ensuite.",
		["{npc:4984} only sends you to {npc:8997} in Auberdine, who gives the dungeon quest: a few hundred XP for a trip you make anyway."] = "{npc:4984} envoie seulement chez {npc:8997} à Auberdine, qui donne la quête du donjon : quelques centaines d'XP pour un trajet fait de toute façon.",
		["{npc:4984}'s errand, if you took it in {zone:1453}"] = "La course de {npc:4984}, si elle a été prise à {zone:1453}",
		["{npc:5082}, Mikhail and Tapoke Jahn are all at Menethil's inn; Tapoke fights you when you talk to Mikhail, but gives up once beaten. {npc:1480} stands a short walk north-east of the inn.\n{npc:2104} stands in Menethil Keep."] = "{npc:5082}, Mikhail et Tapoke Jahn sont tous à l'auberge de Menethil ; Tapoke vous attaque quand vous parlez à Mikhail, mais se rend une fois vaincu. {npc:1480} se tient à quelques pas au nord-est de l'auberge.\n{npc:2104} se trouve au Donjon de Menethil.",
		["{object:176634}, beside him"] = "{object:176634}, à côté de lui",
		["{object:19555}: kill these as you meet them"] = "{object:19555} : tuez-les au fur et à mesure.",
		["{object:2164} is in the {object:2101}."] = "{object:2164} se trouve dans le {object:2101}.",
		["{quest:1009} walks the northern tip of the Zoram Strand with Wrathtail guards."] = "{quest:1009} arpente l'extrémité nord du Rivage de Zoram avec des gardes Queue-de-rage.",
		["{quest:1010}, from the plant bundles"] = "{quest:1010}, sur les bottes de plantes",
		["{quest:971}, from Blackfathom Deeps: {npc:2786} is in the {object:32383}."] = "{quest:971}, des Profondeurs de Brassenoire : {npc:2786} est dans {object:32383}.",
		["{zone:1437}: kill these as you meet them"] = "{zone:1437} : tuez-les au passage",
		["{zone:1453}: {npc:4984} (Blackfathom Deeps, optional)"] = "{zone:1453} : {npc:4984} (Profondeurs de Brassenoire, facultatif)",
		["{zone:1455} priests"] = "Prêtres d'{zone:1455}",
		["{zone:1457}: Blackfathom hand-ins (detour)"] = "{zone:1457} : rendus de Brassenoire (détour)",
		["{zone:1457}: the {object:92525} (Blackfathom Deeps, optional detour)"] = "{zone:1457} : {object:92525} (Profondeurs de Brassenoire, détour facultatif)",
		["{zone:1457}: {quest:1199} (detour)"] = "{zone:1457} : {quest:1199} (détour)",
} end)()
t.guides["groupe-alliance/10-site-de-fouilles"] = (function() return {
		["Back to {object:1162}"] = "Retour à {object:1162}",
		["Clear around him first. Tendon Rip slows the tank hard and his Dust Storm makes everyone within 10 yards miss: casters stay out of it."] = "Nettoyer autour de lui d'abord. Il ralentit fortement le tank et sa tempête de poussière fait rater tout le monde à 10 mètres : les lanceurs de sorts restent en dehors.",
		["Daewyn and the {npc:260808}"] = "Daewyn et {npc:260808}",
		["Daewyn: {quest:95772}, from {npc:956} in Lakeshire"] = "Daewyn : {quest:95772}, de {npc:956} à Comté-du-Lac",
		["Deepwater Tavern"] = "Taverne de l'Eau-profonde",
		["Excavation Site"] = "Site de fouilles",
		["Excavation Site entrance"] = "Entrée du site de fouilles",
		["Excavation Site: a 5-player Forever dungeon up the hill in the middle of the {zone:1437}, best at 28 to 31, with 5 players (4 with a real tank or healer). Everything inside is elite and the last boss is 31: about 39,000 XP of quests and blue rewards. Alone? Skip it: the guide goes on to Dalaran."] = "Site de fouilles : un donjon de Forever pour 5 joueurs en haut de la colline, au milieu des {zone:1437}, idéal de 28 à 31, à 5 (à 4 avec un vrai tank ou soigneur). Tout est élite à l'intérieur et le dernier boss est niveau 31 : environ 39 000 XP de quêtes et des récompenses bleues. Seul ? Le passer : le guide continue vers Dalaran.",
		["Fly to Lakeshire on your way to {zone:1453}: {npc:956} is in the stables past the bridge."] = "Passer par Comté-du-Lac en vol sur la route de {zone:1453} : {npc:956} est dans les écuries après le pont.",
		["From the meeting stone near Thelgen Rock, follow the mountain path up to the portal. A single graveyard serves the area: a wipe means a long walk back."] = "Depuis la pierre de rencontre près du rocher de Thelgen, suivre le sentier de montagne jusqu'au portail. Un seul cimetière dans le secteur : après un échec collectif, le retour à pied est long.",
		["From {zone:1441}: use your hearthstone, bound in Menethil's Deepwater Tavern. On cooldown? Fly to Theramore and take the boat to {object:1162}."] = "Depuis {zone:1441} : utilisez votre pierre de foyer, liée à la taverne de l'Eau-profonde de Menethil. En recharge ? Prenez le griffon jusqu'à Theramore, puis le bateau pour {object:1162}.",
		["Group 10 · Excavation Site: {zone:1437} (dungeon 28-32)"] = "Groupe 10 · Site de fouilles : {zone:1437} (donjon 28-32)",
		["In the small cave of the outdoor dig, west of the road."] = "Dans la petite grotte du chantier extérieur, à l'ouest de la route.",
		["Keep 6 free quest log slots. {npc:1480} is in her house, {npc:2094} by the north gate. {quest:95737}, from Llana in Astranaar, can no longer be taken once you hold {npc:1480}'s quest."] = "Garder 6 places libres dans le journal. {npc:1480} est dans sa maison, {npc:2094} près de la porte nord. {quest:95737}, de Llana à Astranaar, ne se prend plus une fois la quête de {npc:1480} dans le journal.",
		["Lakeshire: {npc:956}"] = "Comté-du-Lac : {npc:956}",
		["Menethil rewards"] = "Récompenses à Menethil",
		["Needs {quest:484} done"] = "Demande {quest:484} finie",
		["On the Green Belt, east of the road. He gives it once his three earlier quests are done (The Greenwarden, Tramping Paws, Fire Taboo, then Blisters on the Land)."] = "Sur la Ceinture verte, à l'est de la route. Il la donne une fois ses trois quêtes précédentes terminées (Le Gouverneur vert, Piétinements de pattes, Feu interdit, puis Fièvre sur le pays).",
		["Saltspine"] = "Seléchine",
		["Share each quest with your group: click it in the quest log, then Share. Talk to {npc:262681} and Daewyn as soon as you find them inside: their follow-ups start with them."] = "Partager chaque quête avec le groupe : la cliquer dans le journal, puis Partager. Parler à {npc:262681} et à Daewyn dès qu'on les trouve à l'intérieur : leurs suites commencent avec eux.",
		["The last boss, level 31, woken by the Archival Panel on its right. Thunderclap slows everyone within 10 yards, and it knocks back and stuns the tank for 5 seconds: rotate stuns and slows, keep healing the tank, kite round the structures if need be. {npc:262681} waits on the wooden scaffold by its arena."] = "Le dernier boss, niveau 31, réveillé par le panneau d'archives à sa droite. Coup de tonnerre ralentit tout le monde à 10 mètres, et il projette et étourdit le tank 5 secondes : enchaîner étourdissements et ralentissements, soigner le tank, tourner autour des structures si besoin. {npc:262681} attend sur l'échafaudage en bois près de son arène.",
		["The most dangerous stretch: Thicket Lurkers leap out of the tall grass, and Matriarchs call more of them at low health. Keep to the narrow path, fight in the open, kill the others before a Matriarch. Shadetooth comes with two Thicket Hunters (dispel Infected Wound): crowd-control one, kill the other, and fight him in the crocodile cove on the left so his fear cannot throw anyone into the grass."] = "Le passage le plus dangereux : des raptors surgissent des hautes herbes, et les matriarches en appellent d'autres à faible vie. Rester sur le chemin étroit, combattre à découvert, tuer les autres avant une matriarche. Dent-Sombre vient avec deux chasseurs des fourrés (dissiper la blessure infectée) : en neutraliser un, tuer l'autre, et le combattre dans l'anse aux crocodiles à gauche pour que sa peur n'envoie personne dans les herbes.",
		["The tall grass and Shadetooth"] = "Les hautes herbes et Dent-Sombre",
		["The {npc:260808} (elite 28) stands right of the Dragonmaw and the burned dig camp; only this one inside drops the rootcore, not the one outside the dungeon."] = "{npc:260808} (élite 28) se tient à droite des Gueules-de-dragon et du camp de fouilles brûlé ; seul celui de l'intérieur donne le cœur de racine, pas celui du dehors.",
		["{item:270180}: {npc:260808}, elite 28"] = "{item:270180} : {npc:260808}, élite 28",
		["{item:270865}, from the {npc:260326}: right-click it"] = "{item:270865}, sur {npc:260326} : clic droit dessus",
		["{item:284845}: Shadetooth and the Thicket raptors"] = "{item:284845} : Dent-Sombre et les raptors des fourrés",
		["{npc:1244}'s reward"] = "Récompense de {npc:1244}",
		["{npc:1480}: pick mana potions for casters"] = "{npc:1480} : potions de mana pour les lanceurs de sorts",
		["{npc:1480}: {quest:95737}, if you took it in Astranaar"] = "{npc:1480} : {quest:95737}, si elle a été prise à Astranaar",
		["{npc:2094}: the reward may be missing (bug reported on 07/11)"] = "{npc:2094} : la récompense peut manquer (bug signalé le 07/11)",
		["{npc:262681}, each player talks to him"] = "{npc:262681}, chaque joueur lui parle",
		["{object:1162}: dungeon quests"] = "{object:1162} : quêtes du donjon",
		["{object:32356}. He says you lack the {item:270865}? Abandon the quest and take it again from Whelgar for a new relic."] = "{object:32356}. Il dit qu'il manque {item:270865} ? Abandonner la quête et la reprendre chez Whelgar pour une nouvelle relique.",
} end)()
t.guides["groupe-alliance/10b-gnomeregan"] = (function() return {
		["Collected all through the dungeon. {item:9309} (24 for {npc:6579}): the troggs, slimes, leper gnomes and machines. {quest:2924}: the Artificial Extrapolators, rectangular boxes on the floor all around the dungeon; each one vanishes once used, so a full group on the quest may have to search the whole dungeon. Every player with the quest loots their own."] = "À ramasser dans tout le donjon. {item:9309} (24 pour {npc:6579}) : les troggs, limons, gnomes lépreux et machines. {quest:2924} : les extrapolateurs (Artificial Extrapolator), des boîtes rectangulaires posées au sol partout dans le donjon ; chacune disparaît une fois utilisée, un groupe entier sur la quête doit donc parfois fouiller tout le donjon. Chaque joueur qui a la quête ramasse les siens.",
		["Escort {npc:7850} back to the entrance"] = "Escorter {npc:7850} jusqu'à l'entrée",
		["Gnomeregan"] = "Gnomeregan",
		["Gnomeregan: a 5-player dungeon under {zone:1426}, best at 29 to 33; {npc:7800}, the last boss, is 34. Every quest giver stands in {object:171524}. From the {zone:1437}: fly from {object:1162} to {zone:1455}. Alone? Skip it: the guide goes on to Dalaran."] = "Gnomeregan : un donjon pour 5 joueurs sous {zone:1426}, idéal de 29 à 33 ; {npc:7800}, le dernier boss, est niveau 34. Tous les donneurs sont à {object:171524}. Depuis {zone:1437} : vol de {object:1162} à {zone:1455}. Seul ? Le passer : le guide continue vers Dalaran.",
		["Gnomeregan: along the way"] = "Gnomeregan : en chemin",
		["Gnomeregan: before going in"] = "Gnomeregan : avant d'entrer",
		["Gnomeregan: the Engineering Labs"] = "Gnomeregan : les laboratoires d'ingénierie",
		["Gnomeregan: the Launch Bay"] = "Gnomeregan : la baie de lancement",
		["Gnomeregan: the Sparklematic, the Dormitory and the Clean Room"] = "Gnomeregan : le Sparklematic, le dortoir et la salle propre",
		["Gnomeregan: {npc:7800}"] = "Gnomeregan : {npc:7800}",
		["Group 10b · Gnomeregan (dungeon 29-33, optional)"] = "Groupe 10b · Gnomeregan (donjon 29-33, facultatif)",
		["Group of 5 at 29 to 33. Everything inside is elite and the mechanical foes hit hard."] = "Groupe de 5 de 29 à 33. Tout est élite à l'intérieur et les ennemis mécaniques frappent fort.",
		["In the quest log before going in: {quest:2929}, {quest:2930} and {quest:2922} ({object:171524}). If you took them: {quest:2928} ({npc:6579}, {zone:1453}, Group 9), {quest:2924} ({npc:6169}, {object:171524}), {quest:2962} (Ozzie, Kharanos). Bring the {item:9280} (or the White one), and 3 silver per {item:9308} you want to put in the {object:142487}."] = "Dans le journal avant d'entrer : {quest:2929}, {quest:2930} et {quest:2922} ({object:171524}). Si elles ont été prises : {quest:2928} ({npc:6579}, {zone:1453}, Groupe 9), {quest:2924} ({npc:6169}, {object:171524}), {quest:2962} (Ozzie, Kharanos). Apporter {item:9280} (ou la blanche), et 3 pièces d'argent par {item:9308} à mettre dans {object:142487}.",
		["Keep 9 free quest log slots. Every quest can be shared except {quest:2926} and its follow-up: each player takes those from Ozzie."] = "Garder 9 places libres dans le journal. Toutes les quêtes se partagent sauf {quest:2926} et sa suite : chaque joueur les prend chez Ozzie.",
		["Kharanos: Ozzie's next quest"] = "Kharanos : la quête suivante d'Ozzie",
		["Kharanos: {npc:1268}"] = "Kharanos : {npc:1268}",
		["Kharanos: {npc:1268} (Green Glow)"] = "Kharanos : {npc:1268} (lueur verte)",
		["Kharanos: {quest:2962} (optional detour)"] = "Kharanos : {quest:2962} (détour facultatif)",
		["Out of Gnomeregan and east to Kharanos, on the way back to {zone:1455}."] = "Sortir de Gnomeregan et aller à l'est jusqu'à Kharanos, sur le chemin de {zone:1455}.",
		["Out of Gnomeregan and east to Kharanos, within the two hours of the fallout."] = "Sortir de Gnomeregan et aller à l'est jusqu'à Kharanos, dans les deux heures des retombées.",
		["Ride out of {zone:1455} down to Kharanos. Ozzie hands you an {item:9283}."] = "Sortir de {zone:1455} et descendre à Kharanos. Ozzie remet {item:9283}.",
		["Share the quests with your group: click each in the quest log, then Share."] = "Partager les quêtes avec le groupe : clic sur chacune dans le journal, puis Partager.",
		["Take the Deeprun Tram to {zone:1453}: {npc:6579} is in the {object:28027}, by the tram. Group 11 (Dalaran) starts in {zone:1453}."] = "Prendre le tram pour {zone:1453} : {npc:6579} est dans {object:28027}, près du tram. Le Groupe 11 (Dalaran) commence à {zone:1453}.",
		["The Gnomeregan outskirts"] = "Les abords de Gnomeregan",
		["The last boss. Tank Thermaplugg (elite 34) in the middle of the room: his Walking Bombs then take longer to reach the group; ranged players kill them. They come faster at half health and faster still at 20 %. Overwhelmed? A button on the pillars around the room stops them for a while: give that job to one ranged player. After each knock-back his threat resets: let the tank take him back."] = "Le dernier boss. Tanker Thermaplugg (élite 34) au milieu de la salle : ses bombes ambulantes mettent alors plus de temps à atteindre le groupe ; les joueurs à distance les tuent. Elles arrivent plus vite à mi-vie, plus vite encore à 20 %. Débordés ? Un bouton sur les piliers autour de la salle les arrête un moment : confier ce rôle à un joueur à distance. Après chaque projection, sa menace repart de zéro : laisser le tank le reprendre.",
		["The {npc:6229} fights in the Engineering Labs; {object:142696}, on the lower level of that room, turns the Red card into the {item:9316}."] = "{npc:6229} combat dans les laboratoires d'ingénierie ; {object:142696}, au niveau inférieur de cette salle, change la carte rouge en {item:9316}.",
		["West of Kharanos, the paths down to the dungeon's portal, outside the instance. Kill an {npc:6213} (green glow, elite 24) and use the {item:9283} on its corpse. {npc:6231} (elite 26) has his own room off the northern part of these paths: his Memory Core drops for every player on the quest.\n{quest:2930} starts out here too: the {item:9279} drops from the troggs and lepers of the outskirts (about 1 kill in 10), and {object:142345}, a machine also outside the portal, turns it into a {item:9280}."] = "À l'ouest de Kharanos, les chemins qui descendent au portail du donjon, hors de l'instance. Tuer un {npc:6213} (lueur verte, élite 24) et utiliser {item:9283} sur son cadavre. {npc:6231} (élite 26) a sa propre salle sur la partie nord de ces chemins : son noyau de mémoire tombe pour chaque joueur qui a la quête.\n{quest:2930} commence ici aussi : {item:9279} tombe sur les troggs et les lépreux des abords (environ 1 fois sur 10), et {object:142345}, une machine elle aussi devant le portail, la change en {item:9280}.",
		["{item:9277}: {npc:6231}, elite 26"] = "{item:9277} : {npc:6231}, élite 26",
		["{item:9278}: Artificial Extrapolators"] = "{item:9278} : extrapolateurs (Artificial Extrapolator)",
		["{item:9279}: troggs and lepers"] = "{item:9279} : troggs et lépreux",
		["{item:9280}: the White one, at {object:142345}"] = "{item:9280} : la blanche, dans {object:142345}",
		["{item:9281}: the Blue one, at {object:142476}"] = "{item:9281} : la bleue, dans {object:142476}",
		["{item:9282}: the Yellow one, at {object:142475}"] = "{item:9282} : la jaune, dans {object:142475}",
		["{item:9284}: the empty phial, on an {npc:6213}'s corpse"] = "{item:9284} : la fiole vide, sur le cadavre d'un {npc:6213}",
		["{item:9316}: the Red one, at {object:142696}"] = "{item:9316} : la rouge, dans {object:142696}",
		["{item:9365}: the heavy phial, on a living irradiated slime or horror"] = "{item:9365} : la fiole lourde, sur un limon ou une horreur irradiés vivants",
		["{npc:1268}: then back to the portal"] = "{npc:1268} : puis retour au portail",
		["{npc:6169}: not offered without Mathiel's errand from {zone:1457}? Carry on without it"] = "{npc:6169} : pas proposée sans la course de Mathiel à {zone:1457} ? Continuer sans elle",
		["{npc:6235} stands on the Launch Bay platform; {object:142476}, on the same platform, turns the Blue card into a Red one."] = "{npc:6235} se tient sur la plateforme de la baie de lancement ; {object:142476}, sur la même plateforme, change la carte bleue en rouge.",
		["{npc:6569}: for {npc:1268} in Kharanos"] = "{npc:6569} : pour {npc:1268} à Kharanos",
		["{npc:7079}, in the Clean Room"] = "{npc:7079}, dans la salle propre",
		["{object:142487} machines stand in the room before the Dormitory: put the {quest:2945} in one to clean it. In the Dormitory, {npc:7850} waits before the {npc:7079} room: his escort runs all the way back to the dungeon's entrance; near the end a countdown starts, get him out before it reaches zero. His reward waits at {object:3204}, on the route of Group 15. {object:142475}, in the Dormitory south of the Clean Room, turns the Yellow card into a Blue one."] = "Les machines {object:142487} sont dans la salle avant le dortoir : y mettre {quest:2945} pour le nettoyer. Dans le dortoir, {npc:7850} attend avant la salle de {npc:7079} : son escorte va jusqu'à l'entrée du donjon ; vers la fin, un compte à rebours démarre, le sortir avant zéro. Sa récompense attend à {object:3204}, sur le parcours du Groupe 15. {object:142475}, dans le dortoir au sud de la salle propre, change la carte jaune en bleue.",
		["{quest:2926} is done outside the dungeon, so it can be handed in now: back to Kharanos, then back to the portal, about two rides of a couple of minutes. Ozzie's next quest is done inside: use his {item:9364} on a LIVING irradiated slime or horror, and the fallout lasts two hours, enough for the run and the ride back. Not each player's cup of tea? Skip it: {quest:2926} is handed in after the run."] = "{quest:2926} se fait hors du donjon, elle peut donc se rendre maintenant : retour à Kharanos, puis retour au portail, deux trajets de quelques minutes. La quête suivante d'Ozzie se fait à l'intérieur : utiliser sa {item:9364} sur un limon ou une horreur irradiés VIVANTS ; les retombées durent deux heures, assez pour le donjon et le retour. Pas envie ? La passer : {quest:2926} se rend après le donjon.",
		["{quest:2945}, a drop from the Dark Iron Agents: right-click it"] = "{quest:2945}, sur les agents Sombrefer : clic droit dessus",
		["{quest:2947}: for {npc:6826} in {zone:1455}"] = "{quest:2947} : pour {npc:6826} à {zone:1455}",
		["{quest:2947}: {npc:6826} is in the {object:32362}. His next quest, Gnome Improvement, asks for a {item:2842} and a {item:1206}: not in the guide."] = "{quest:2947} : {npc:6826} est dans {object:32362}. Sa quête suivante, Gnome Improvement, demande {item:2842} et {item:1206} : hors du guide.",
		["{zone:1455}: Gnomeregan quests"] = "{zone:1455} : quêtes de Gnomeregan",
} end)()
t.guides["groupe-alliance/11-mille-pointes"] = (function() return {
		["A new {item:279996}, for the four titan watchers around the {zone:1437}, in Group 12; below ground"] = "Une nouvelle {item:279996}, pour les quatre gardiens titans des {zone:1437}, au Groupe 12 ; sous terre",
		["Angerfang Encampment"] = "Campement de Hargnecroc",
		["Back to Darkshire"] = "Retour à Sombre-Comté",
		["Below ground"] = "Sous terre",
		["Darkshire"] = "Sombre-Comté",
		["Darkshire flight master"] = "Maître de vol de Sombre-Comté",
		["Escort him out of the Kraul"] = "L'escorter hors du kraal",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Fly to {object:1162}"] = "Envolez-vous vers {object:1162}",
		["Fly to {zone:1453}"] = "Prendre un vol pour {zone:1453}",
		["Follow the canyons east to the salt flats. The goblins and gnomes of the Mirage Raceway are neutral and give quests to both factions."] = "Suivez les canyons vers l'est jusqu'aux plaines de sel. Les gobelins et gnomes de la Piste des mirages sont neutres et donnent des quêtes aux deux factions.",
		["Follow the coast north to the wrecked ship. Cursed Sailors walk the beach, Cursed Marines the deck; {npc:1159} stands on the beach by the bow. Giant Wetlands Crocolisks lurk on the coast just north of it.\nCareful: Fen Creepers hide in stealth where the river splits close to the ghost ship, and they can join a fight."] = "Suivez la côte vers le nord jusqu'à l'épave. Des Marins maudits arpentent la plage, des Soldats de marine maudits le pont ; {npc:1159} se tient sur la plage près de la proue. Des Crocilisques géants des Paluns rôdent sur la côte juste au nord.\nAttention : des Rampants des tourbières se cachent, camouflés, là où la rivière se divise près du navire fantôme, et peuvent se joindre au combat.",
		["For the Dragonmaw catapult, on the {zone:1437} loop of the next guide"] = "Pour la catapulte Dragonmaw, lors de la boucle des {zone:1437} du guide suivant",
		["For {npc:1212} in {zone:1453}, in the next guide"] = "Pour {npc:1212} à {zone:1453}, dans le guide suivant",
		["For {npc:1284} in {zone:1453}, in the next guide"] = "Pour {npc:1284} à {zone:1453}, dans le guide suivant",
		["For {npc:482} in {zone:1453}, in the next guide"] = "Pour {npc:482} à {zone:1453}, dans le guide suivant",
		["For {quest:5762} in Stranglethorn, later"] = "Pour {quest:5762} à Strangleronce, plus tard",
		["Gnomeregan: the gnomes' fallen city under {zone:1426}, a 5-player dungeon best at 29 to 33. The guide runs it after Group 10 (Group 10b), from {zone:1455}, where the other quests are given. {npc:6579}'s quest is the only one given elsewhere: take it now. Alone? Skip it: Group 10b is then skipped too."] = "Gnomeregan : la cité perdue des gnomes sous {zone:1426}, un donjon pour 5 joueurs idéal de 29 à 33. Le guide le fait après le Groupe 10 (Groupe 10b), depuis {zone:1455}, où sont données les autres quêtes. La quête de {npc:6579} est la seule donnée ailleurs : la prendre maintenant. Seul ? La passer : le Groupe 10b est alors passé aussi.",
		["Group 9 · {zone:1441}, {zone:1431} & {zone:1437}"] = "Groupe 9 · {zone:1441}, {zone:1431} et {zone:1437}",
		["Head east again to the Dragonmaw camp. The four sets of Attack Plans lie in the Angerfang Encampment; {npc:2091}, an elite, stands in the camp too."] = "Reprenez la direction de l'est vers le camp Dragonmaw. Les quatre plans d'attaque se trouvent au campement de Hargnecroc ; {npc:2091}, un élite, s'y tient également.",
		["Head east to the ogre mound. {object:119} sits in the camp at its entrance; Splinter Fist ogres guard it."] = "Allez vers l'est jusqu'au tertre des ogres. {object:119} se trouve dans le camp à son entrée ; des ogres Brisepoing la gardent.",
		["Her house stands on the hill south-east of Darkshire."] = "Sa maison se trouve sur la colline au sud-est de Sombre-Comté.",
		["Horde land: keep clear of Camp Taurajo and its guards. Keep 2 free quest log slots."] = "Terre de la Horde : se tenir loin du Camp Taurajo et de ses gardes. Garder 2 places libres dans le journal.",
		["Inside"] = "À l'intérieur",
		["Into {zone:1413}"] = "Dans les {zone:1413}",
		["Jump down from {npc:4421}'s area and kill a few quilboars: {npc:4510}, a night elf who died in the Kraul, lies by a tent in the north of that area. {quest:1142} asks for {item:5825}, about 1 quilboar in 10, for each player on the quest: by now most of the Kraul is cleared, so it often takes the walk back or a second run."] = "Sauter en contrebas de la zone de {npc:4421} et tuer quelques huttes-épines : {npc:4510}, un elfe de la nuit mort dans le kraal, gît près d'une tente au nord de cette zone. {quest:1142} demande {item:5825}, environ 1 hutte-épine sur 10, pour chaque joueur qui a la quête : à ce stade le kraal est presque vidé, il faut souvent le chemin du retour ou un second passage.",
		["Level 28 required: below 28, skip it and its follow-ups in {zone:1431}. Take the Deeprun Tram from {zone:1455}, then the Cathedral and the Keep."] = "Niveau 28 requis : en dessous, laisser de côté cette quête et sa suite à {zone:1431}. Tram des profondeurs depuis {zone:1455}, puis la Cathédrale et le Donjon.",
		["Mirage Raceway"] = "Piste des mirages",
		["Mirage Raceway: kill these as you meet them"] = "Piste des mirages : tuez-les au fur et à mesure",
		["Nightbane Dark Runners"] = "Messagers Plaie-de-nuit",
		["Nightbane Shadow Weavers"] = "Tisseurs d'ombre Plaie-de-nuit",
		["Nightbane Vile Fangs and the {npc:511}"] = "Crocs noirs Plaie-de-nuit et {npc:511}",
		["Not there? Another group is escorting him: wait for him to come back, or join them."] = "Pas là ? Un autre groupe l'escorte : attendre son retour, ou se joindre à eux.",
		["On the road south through the {zone:1413}, {npc:6244} camps east of the road, north-east of Camp Taurajo; come in from the east and keep clear of the Horde guards."] = "Sur la route vers le sud à travers {zone:1413}, {npc:6244} campe à l'est de la route, au nord-est du Camp Taurajo ; arrivez par l'est et évitez les gardes de la Horde.",
		["On the top floor"] = "Au dernier étage",
		["On the way"] = "En chemin",
		["Only if a {npc:272273} dropped {quest:96138}: right-click it"] = "Seulement si un {npc:272273} a laissé tomber {quest:96138} : clic droit dessus",
		["Raven Hill Cemetery: kill these as you meet them"] = "Cimetière de Colline-aux-Corbeaux : tuez-les au fur et à mesure",
		["Razorfen Kraul"] = "Kraal de Tranchebauge",
		["Razorfen Kraul (dungeon, optional)"] = "Kraal de Tranchebauge (donjon, facultatif)",
		["Razorfen Kraul: a 5-player quilboar dungeon in the bramble at the southern edge of the {zone:1413}, west of the road down to {zone:1441}, best at 27 to 32. Its two Alliance quests are given inside: nothing to take beforehand. Alone? Skip it: the guide goes on to {zone:1441}."] = "Kraal de Tranchebauge : un donjon de huttes-épines pour 5 joueurs, dans les ronces au sud de {zone:1413}, à l'ouest de la route qui descend vers {zone:1441}, idéal de 27 à 32. Ses deux quêtes de l'Alliance sont données à l'intérieur : rien à prendre avant. Seul ? Le passer : le guide continue vers {zone:1441}.",
		["Razorfen Kraul: {npc:4421}"] = "Kraal de Tranchebauge : {npc:4421}",
		["Razorfen Kraul: {npc:4510}"] = "Kraal de Tranchebauge : {npc:4510}",
		["Razorfen Kraul: {quest:1144}"] = "Kraal de Tranchebauge : {quest:1144}",
		["Roogug, {npc:4424}, {npc:4428}, {npc:4420} and {npc:4422} come before her (the codex's order). {npc:4421}, the last boss, fights on the ramp outside her hut and teleports back into it now and then: the tank grabs her again. Her Purity dispels every debuff and makes her immune for a while: no damage-over-time on her."] = "Roogug, {npc:4424}, {npc:4428}, {npc:4420} et {npc:4422} viennent avant elle (ordre du codex). {npc:4421}, le dernier boss, se combat sur la rampe devant sa hutte et s'y téléporte de temps en temps : le tank la reprend. Sa Pureté dissipe tous les affaiblissements et la rend insensible un moment : pas de dégâts sur la durée sur elle.",
		["Take the boat from Menethil's pier to {object:21056} in {zone:1445}."] = "Prenez le bateau depuis le quai de Menethil jusqu'à {object:21056} en {zone:1445}.",
		["The Dark Runners prowl the woods south of the road, west of Darkshire."] = "Les Coureurs noirs rodent dans les bois au sud de la route, à l'ouest de Sombre-Comté.",
		["The Defias camp lies in the south-west of {zone:1431}, south of {object:102} near the {zone:1436} border. The strongbox stands among the tents."] = "Le camp des Défias se trouve au sud-ouest de {zone:1431}, au sud de {object:102} près de la frontière de {zone:1436}. Le coffre-fort se dresse parmi les tentes.",
		["The Goaz Warders stand just west of Whelgar's camp: use the {item:279996} he gave you beside one."] = "Les Goaz Warders se tiennent juste à l'ouest du camp de Whelgar : utiliser à côté de l'un d'eux {item:279996} qu'il a remise.",
		["The Lost Fleet: kill these as you meet them"] = "La Flotte perdue : tuez-les au fur et à mesure",
		["The Plague Spreaders walk the northern half of the Raven Hill Cemetery. {npc:522}, an elite, wanders the graves: keep away from him.\nSkeletal Raiders, Healers and Warders hold the west part of the cemetery, just east of {npc:311}'s camp.\nCareful: The skeletons in the catacombs are packed close together, so you can easily pull extra mobs."] = "Les répandeurs de peste arpentent la moitié nord du cimetière de Colline-aux-Corbeaux. {npc:522}, un élite, erre parmi les tombes : tenez-vous à l'écart.\nDes écumeurs, soigneurs et gardiens squelettes occupent la partie ouest du cimetière, juste à l'est du camp de {npc:311}.\nAttention : Les squelettes dans les catacombes sont serrés, vous pouvez donc facilement attirer des mobs supplémentaires.",
		["The captain walks the deck of the wrecked ship; his strongbox sits in the hold."] = "Le capitaine arpente le pont du navire échoué ; son coffre est dans la cale.",
		["The relics lie in the dig itself. {npc:1353}, a big Razormaw, prowls the raptor valley just west of it.\nThe Dragonmaw orcs camp east of the excavation site. Raiders and Swamprunners carry the war banners."] = "Les reliques se trouvent dans les fouilles elles-mêmes. {npc:1353}, un gros tranchegueule, rôde dans la vallée des raptors juste à l'ouest.\nLes orcs Dragonmaw campent à l'est du site de fouilles. Les écumeurs et les arpenteurs portent les bannières de guerre.",
		["The strongest worgen roam the woods south of Darkshire, west and south of the Tranquil Gardens Cemetery. The {npc:511} hides in the small crypt by the cemetery.\nCareful: Curse of Blood lasts 10 minutes and adds 13 to each hit of physical damage you take.\nCareful: Some worgen outside the cave stand in groups, including one camp of four. To avoid adds, pull them one at a time from the raised ground next to the cave entrance."] = "Les worgens les plus forts rôdent dans les bois au sud de Sombre-Comté, à l'ouest et au sud du cimetière des jardins paisibles. {npc:511} se cache dans la petite crypte près du cimetière.\nAttention : Malédiction de sang dure 10 minutes et ajoute 13 à chaque coup de dégâts physiques que vous subissez.\nAttention : Certains worgens à l'extérieur de la grotte sont en groupes, dont un camp de quatre. Pour éviter les renforts, tirez-les un par un depuis le terrain surélevé à côté de l'entrée de la grotte.",
		["The worgen hold the woods of Brightwood, west of Darkshire and north of the road. Pull them one at a time."] = "Les worgens occupent le Bois-Clair, à l'ouest de Sombre-Comté et au nord de la route. Tirez-les un par un.",
		["To Theramore"] = "Vers Theramore",
		["Vul'Gol Ogre Mound: kill these as you meet them"] = "Tertre des ogres Vul'Gol : tuez-les au fur et à mesure",
		["Wait a moment, then speak with her again"] = "Patientez un instant, puis parlez-lui de nouveau",
		["Whelgar's Excavation Site: kill these as you meet them"] = "Excavations de Whelgar : tuez-les au fur et à mesure",
		["{item:1946}; inside"] = "{item:1946} ; à l'intérieur",
		["{item:2594}, from {npc:1464}"] = "{item:2594}, chez {npc:1464}",
		["{item:2658} along the way to {npc:1078} and Whelgar"] = "{item:2658} en chemin vers {npc:1078} et Whelgar",
		["{item:2659} along the way to {npc:1078} and Whelgar"] = "{item:2659} en chemin vers {npc:1078} et Whelgar",
		["{item:2660} along the way to {npc:1078} and Whelgar"] = "{item:2660} en chemin vers {npc:1078} et Whelgar",
		["{item:2661} along the way to {npc:1078} and Whelgar"] = "{item:2661} en chemin vers {npc:1078} et Whelgar",
		["{item:4371}, from {npc:3133}, if you have none"] = "{item:4371}, chez {npc:3133}, si vous n'en avez pas",
		["{item:5825}: quilboars of the Kraul, about 1 in 10"] = "{item:5825} : huttes-épines du kraal, environ 1 fois sur 10",
		["{item:5947}; inside"] = "{item:5947} ; à l'intérieur",
		["{npc:1077}, below ground"] = "{npc:1077}, sous terre",
		["{npc:1078} and Whelgar"] = "{npc:1078} et Whelgar",
		["{npc:1239}, in the inn"] = "{npc:1239}, à l'auberge",
		["{npc:2104}, in Menethil Keep; on the top floor"] = "{npc:2104}, au Donjon de Menethil ; au dernier étage",
		["{npc:263}, in the town hall"] = "{npc:263}, à l'hôtel de ville",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}, dans la maison derrière l'hôtel de ville",
		["{npc:276}, at the east end of town; inside"] = "{npc:276}, à l'extrémité est de la ville ; à l'intérieur",
		["{npc:276}, inside"] = "{npc:276}, à l'intérieur",
		["{npc:311}'s Camp"] = "Le camp de {npc:311}",
		["{npc:4454}: for Martek in the {zone:1418}, at 39; not offered? Go on"] = "{npc:4454} : pour Martek dans {zone:1418}, à 39 ; non proposé ? Continuer",
		["{npc:482}, the cheese shop in the {object:2096}"] = "{npc:482}, la fromagerie du {object:2096}",
		["{npc:4959} and {npc:482}"] = "{npc:4959} et {npc:482}",
		["{npc:4982}, in the Cathedral of Light"] = "{npc:4982}, dans la Cathédrale de la Lumière",
		["{npc:6579} stands in the {object:28027}, by the tram. The quest waits in the log until Gnomeregan."] = "{npc:6579} se tient dans {object:28027}, près du tram. La quête attend dans le journal jusqu'à Gnomeregan.",
		["{npc:661}, by {npc:633}'s house; inside"] = "{npc:661}, près de la maison de {npc:633} ; à l'intérieur",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}, taverne du Corbeau écarlate",
		["{npc:840} again"] = "De nouveau {npc:840}",
		["{npc:840} walks around Darkshire: look inside the circle on the map"] = "{npc:840} se promène dans Sombre-Comté : regardez à l'intérieur du cercle sur la carte",
		["{npc:840}, at the north entrance of town; walks around Darkshire: look inside the circle on the map"] = "{npc:840}, à l'entrée nord de la ville ; se promène dans Sombre-Comté : regardez à l'intérieur du cercle sur la carte",
		["{object:19868} lies all over the flats. Scorpid Reavers roam the north half; keep to it, away from the Saltstone Basilisks, Crystalhides and Gazers (32-35) of the middle and the far south."] = "{object:19868} jonchent les Salines. Les Scorpides ravageurs parcourent la moitié nord : restez-y, loin des Basilics du sel gemme, Peaux de cristal et Contemplateurs (32-35) du centre et de l'extrême sud.",
		["{quest:1144}, a goblin, is held in the same tent as {npc:4510}. Everyone takes his quest before he starts walking; he walks back to the entrance by the south side, past many armored boars. He gives the reward himself at the end."] = "{quest:1144}, un gobelin, est retenu dans la même tente que {npc:4510}. Chacun prend sa quête avant qu'il se mette en marche ; il retourne à l'entrée par le côté sud, devant de nombreux sangliers cuirassés. Il donne lui-même la récompense à la fin.",
		["{quest:1144}, at the entrance"] = "{quest:1144}, à l'entrée",
		["{quest:1738}: in {zone:1440}, on the way to {zone:1443}"] = "{quest:1738} : en {zone:1440}, en route vers {zone:1443}",
		["{quest:65602}: the incubus, beside the succubus; the {item:190309} is near the {quest:1738}"] = "{quest:65602} : l'incube, à côté de la succube ; la {item:190309} est près de {quest:1738}",
		["{quest:98221}: {quest:465} comes after it on Forever"] = "{quest:98221} : sur Forever, {quest:465} vient après",
		["{zone:1453} flight master"] = "Maître de vol de {zone:1453}",
		["{zone:1453}: {npc:6579} (Gnomeregan, optional)"] = "{zone:1453} : {npc:6579} (Gnomeregan, facultatif)",
} end)()
t.guides["groupe-alliance/12-dalaran"] = (function() return {
		["Blossom in the central garden, remnants everywhere, the {item:251961} at the Violet Citadel end."] = "Fleur dans le jardin central, rémanents partout, {item:251961} au bout, côté Citadelle pourpre.",
		["City of Dalaran"] = "Cité de Dalaran",
		["City of Dalaran entrance"] = "Entrée de la Cité de Dalaran",
		["City of Dalaran: a 5-player Forever dungeon in the {zone:1416}, best at 30 to 33. This chapter takes its four quests, runs the dungeon, then hands them in. Alone? Skip it: the guide goes on to the {zone:1437}.\n{npc:5502} is in the {object:2096}, {npc:5694} in the {object:2101} tower."] = "Cité de Dalaran : un donjon Forever pour 5 joueurs dans les {zone:1416}, idéal de 30 à 33. Ce chapitre prend ses quatre quêtes, fait le donjon, puis les rend. Seul ? La passer : le guide continue vers les {zone:1437}.\n{npc:5502} est dans {object:2096}, {npc:5694} dans la tour de {object:2101}.",
		["Clara's apples"] = "Les pommes de Clara",
		["Dalaran skipped: back to {object:1162}"] = "Dalaran passé : retour à {object:1162}",
		["Deepwater Tavern"] = "Taverne de l'Eau-profonde",
		["From {zone:1453}: use your hearthstone (Deepwater Tavern, {object:1162}) or fly to {object:1162}, then take the boat to Southshore. His quest needs level 30: below that, the guide waits here. Ahead of the others? Take it, they can take it from him later on their own."] = "Depuis {zone:1453} : utilisez votre pierre de foyer (taverne de l'Eau-profonde, {object:1162}) ou prenez le griffon pour {object:1162}, puis le bateau pour Austrivage. Sa quête demande le niveau 30 : en dessous, le guide attend ici. En avance sur les autres ? Prenez-la, ils la prendront plus tard auprès de lui de leur côté.",
		["Group 11 · City of Dalaran (dungeon 30-33, optional)"] = "Groupe 11 · Cité de Dalaran (donjon 30-33, facultatif)",
		["Group of 5. Open the sewer gate with the key from Modera and follow the large pipe."] = "Groupe de 5. Ouvrir la grille de l'égout avec la clé de Modera et suivre la grosse canalisation.",
		["Group: level 30 required for {quest:92432}, the quest that opens the way to Dalaran. Below 30? Level up first."] = "Groupe : niveau 30 requis pour {quest:92432}, la quête qui ouvre la route de Dalaran. En dessous de 30 ? Monter de niveau d'abord.",
		["Inside the dungeon"] = "Dans le donjon",
		["Modera's rewards"] = "Récompenses de Modera",
		["Next: {object:1162}, where your hearthstone is still bound (Deepwater Tavern). {npc:5502} and {npc:5694} take their quests at the next guide's {zone:1453} stop."] = "Ensuite : {object:1162}, où votre pierre de foyer est toujours liée (taverne de l'Eau-profonde). {npc:5502} et {npc:5694} attendent leurs quêtes à l'étape de {zone:1453} du guide suivant.",
		["North-west past Hillsbrad Fields, by Dalaran's outer sewer. Avoid {object:1772}."] = "Au nord-ouest après les champs de Hautebrande, près de l'égout extérieur de Dalaran. Éviter {object:1772}.",
		["Only if you did The Stockade Riots. {npc:1646} is in the {object:2159} on {object:2098}, Mathias Shaw upstairs at SI:7 in {object:2100}, {npc:482} upstairs in the cheese shop of the {object:2096}, {npc:7766} in the garden beside {object:2117}."] = "Uniquement si vous avez fait Les émeutes de la Prison. {npc:1646} se trouve dans l'{object:2159} sur la {object:2098}, Mathias Shaw à l'étage au SI:7 dans l'{object:2100}, {npc:482} à l'étage dans la fromagerie de l'{object:2096}, {npc:7766} dans le jardin près de l'{object:2117}.",
		["Overhear Lescovar and {npc:1755} in the garden, then kill both"] = "Écouter Lescovar et {npc:1755} dans le jardin, puis les tuer tous les deux",
		["Share each quest with your group: click it in the quest log, then Share."] = "Partagez chaque quête au groupe : clic sur la quête dans le journal, puis Partager.",
		["Southshore: {npc:247264}"] = "Austrivage : {npc:247264}",
		["The bowl of apples sits on the table of the farmhouse just outside the {zone:1453} gate, south-west of the road. {item:4306}: from your bags, humanoids or the Auction House."] = "Le bol de pommes repose sur la table de la ferme juste à l'extérieur de la porte de {zone:1453}, au sud-ouest de la route. {item:4306} : dans vos sacs, sur des humanoïdes ou à l'hôtel des ventes.",
		["Use your hearthstone (Deepwater Tavern, {object:1162}), or fly from {zone:1453} to {object:1162} if it is on cooldown."] = "Utilisez votre pierre de foyer (taverne de l'Eau-profonde, {object:1162}), ou prenez le griffon de {zone:1453} vers {object:1162} si elle est en recharge.",
		["{npc:1749}, in the throne room of {object:2117}: {item:2933}"] = "{npc:1749}, dans la salle du trône de l'{object:2117} : {item:2933}",
		["{zone:1453}: the end of the Defias story"] = "{zone:1453} : la fin de l'histoire des Défias",
		["{zone:1453}: two dungeon quests"] = "{zone:1453} : deux quêtes du donjon",
} end)()
t.guides["groupe-alliance/13-solo-loch-modan"] = (function() return {
		["12 minutes this time: Elder Mountain Boars (16-17) roam the hills north-west of the lodge. Under 15, or short on time, skip it."] = "Cette fois 12 minutes : les anciens sangliers des montagnes (16-17) parcourent les collines au nord-ouest du pavillon. Sous le niveau 15, ou pressé par le temps, passez.",
		["Back south along the road, almost to the tunnel: use the Ceramic Jar Grenhild gave you while standing on the patch of snow."] = "Redescendez la route vers le sud, presque jusqu'au tunnel : utilisez le bocal en céramique que Grenhild vous a remis en vous tenant sur la plaque de neige.",
		["Back south along the road."] = "Redescendez la route vers le sud.",
		["Back with the group: /polestar guides, Group Alliance, the group's guide."] = "Retour au groupe : /polestar guides, Groupe Alliance, le guide du groupe.",
		["Boars, black bears and Forest Lurkers (spiders) roam the hills west of the road, between the tunnel and the Silver Stream Mine."] = "Des sangliers, des ours noirs et des rôdeuses des forêts (araignées) parcourent les collines à l'ouest de la route, entre le tunnel et la mine du Ru d'argent.",
		["Crocolisk Skins"] = "Peaux de crocilisque",
		["Deeper in the valley"] = "Au fond de la vallée",
		["East along the road on the south shore. {npc:1345} and {npc:1344} stand at the dig site; the troggs digging just east of them are 17-20: keep away."] = "Vers l'est par la route de la rive sud. {npc:1345} et {npc:1344} se tiennent sur le site de fouilles ; les troggs qui creusent juste à l'est sont de niveau 17-20 : restez à l'écart.",
		["Elder Mountain Boars"] = "Anciens sangliers des montagnes",
		["Farstrider Lodge"] = "Le pavillon des chasseurs",
		["Fly to {zone:1455}"] = "Envolez-vous vers {zone:1455}",
		["From {zone:1455}, follow the road east across {zone:1426} to the South Gate Pass tunnel; the guard tower stands where it opens onto {zone:1432}."] = "Depuis {zone:1455}, suivez la route vers l'est à travers {zone:1426} jusqu'au tunnel du passage de la porte Sud ; la tour de garde se dresse là où il débouche sur {zone:1432}.",
		["Further south, past the first camp, Skullthumpers and Seers (13-14) hold the valley's end."] = "Plus au sud, après le premier camp, les brise-crânes et les prophètes (13-14) tiennent le fond de la vallée.",
		["Handed in at the end, in {zone:1455}"] = "À rendre à la fin, à {zone:1455}",
		["His house stands on the north-west shore of the loch, east of the mine."] = "Sa maison se trouve sur la rive nord-ouest du loch, à l'est de la mine.",
		["Level 15 or more: {npc:1090} wants the Shamans and Bonesnappers (15-16) at the very back of the valley. Under 15, skip it."] = "Niveau 15 ou plus : {npc:1090} veut les chamans et les briseurs d'os (15-16) tout au fond de la vallée. Sous le niveau 15, passez.",
		["Loch Crocolisks line the east and north shores. {npc:270693}, the named one, swims along the east shore north-west of the lodge. Leave the {npc:2476} (level 22) alone."] = "Les crocilisques du loch bordent les rives est et nord. {npc:270693}, le crocilisque nommé, nage le long de la rive est, au nord-ouest du pavillon. Laissez tranquille le {npc:2476} (niveau 22).",
		["Mountain Buzzards"] = "Busards des montagnes",
		["North along the road to the town. {npc:1340} walks up and down the road through town; {npc:1963} and {npc:49808} stand in the middle of town, {npc:1681} on the east side, the gryphon master at the south end."] = "Vers le nord par la route jusqu'au village. {npc:1340} fait les cent pas sur la route qui traverse le village ; {npc:1963} et {npc:49808} se tiennent au centre, {npc:1681} du côté est, le maître des griffons à l'extrémité sud.",
		["North on the road past Thelsamar to the mine at the north-west end of the loch. {npc:1343} stands at its entrance."] = "Vers le nord par la route, après Thelsamar, jusqu'à la mine au bout nord-ouest du loch. {npc:1343} se tient à l'entrée.",
		["Optional, for swimmers: a {object:665289} lies on the lake floor east of town, at one of several spots: swim until its \"!\" shows on the minimap. Young Threshadons (19-20) swim in the loch: keep clear."] = "Facultatif, pour les nageurs : l'objet {object:665289} repose au fond du lac à l'est du village, à l'un de plusieurs endroits possibles : nagez jusqu'à voir son « ! » sur la minicarte. De jeunes battrodons (19-20) nagent dans le loch : tenez-vous à distance.",
		["Rats and crates"] = "Rats et caisses",
		["Sausages on the way"] = "Boudins en chemin",
		["Silver Stream Mine"] = "Mine du Ru d'argent",
		["Solo catch-up for a player behind the group. Back within 4 levels of the lowest player? Stop and rejoin: /polestar guides, Group Alliance, the group's guide."] = "Rattrapage en solo pour un joueur en retard sur le groupe. Revenu à 4 niveaux ou moins du plus bas du groupe ? Arrêtez et rejoignez-le : /polestar guides, Groupe Alliance, le guide du groupe.",
		["Solo · {zone:1432}"] = "Solo · {zone:1432}",
		["Stonesplinter Bonesnappers"] = "Briseurs d'os Brisepierre",
		["Stonesplinter Scouts"] = "Éclaireurs Brisepierre",
		["Stonesplinter Seers"] = "Prophètes Brisepierre",
		["Stonesplinter Shamans"] = "Chamans Brisepierre",
		["Stonesplinter Skullthumpers"] = "Brise-crânes Brisepierre",
		["Stonesplinter Troggs"] = "Troggs Brisepierre",
		["Stonesplinter Valley"] = "Vallée des Brisepierre",
		["The fishing toolbox"] = "La boîte de pêche",
		["The loch shore"] = "La rive du loch",
		["The lodge stands at the east end of the loch. Daryl's quest has a 15-minute timer: the Mountain Buzzards fly over the hills west and south-west of the lodge."] = "Le pavillon se trouve au bout est du loch. La quête de Daryl est limitée à 15 minutes : les busards des montagnes survolent les collines à l'ouest et au sud-ouest du pavillon.",
		["The snowy patch"] = "La plaque de neige",
		["The southern guard tower"] = "La tour de garde du sud",
		["The troggs camp in the valley east of the tower. Every trogg can drop a Stone Tooth: no need to hunt one kind."] = "Les troggs campent dans la vallée à l'est de la tour. Tous peuvent laisser une dent de pierre : inutile de viser une seule espèce.",
		["The valley's end"] = "Le bout de la vallée",
		["The {object:271} sit inside the mine; Tunnel Rat kobolds fill it and the hills around it."] = "Les {object:271} se trouvent dans la mine ; des kobolds Rat des tunnels la remplissent, ainsi que les collines alentour.",
		["Thelsamar"] = "Thelsamar",
		["Trogg Stone Teeth"] = "Dents de pierre de trogg",
		["Tunnel Rat Ears"] = "Oreilles de Rat des tunnels",
		["West along the road. {npc:1684} sells fishing supplies by the water north-east of town."] = "Vers l'ouest par la route. {npc:1684} vend des fournitures de pêche au bord de l'eau, au nord-est du village.",
		["{item:2640}, from the crates"] = "{item:2640}, dans les caisses",
		["{npc:1356} is in the {object:32356}; {npc:4256} in the {object:32372}; {npc:1573} is the gryphon master where you landed."] = "{npc:1356} : {object:32356} ; {npc:4256} : {object:32372} ; {npc:1573} : le maître des griffons, à l'arrivée.",
		["{npc:1572}, the gryphon master"] = "{npc:1572}, le maître des griffons",
} end)()
t.guides["groupe-alliance/14-paluns-hautebrande"] = (function() return {
		["A report for {object:2117}; inside"] = "Un rapport pour {object:2117} ; à l'intérieur",
		["Angerfang Encampment"] = "Campement de Hargnecroc",
		["Auberdine flight master"] = "Maître de vol d'Auberdine",
		["Back to the same murlocs; not every one drops a head."] = "Retournez voir les mêmes murlocs ; tous ne lâchent pas de tête.",
		["Below ground"] = "Sous terre",
		["Boat to Southshore"] = "Bateau pour Austrivage",
		["Cathedral of Light"] = "Cathédrale de la Lumière",
		["Daggerspine naga"] = "Nagas Daguéchine",
		["Deeprun Tram"] = "Tram des profondeurs",
		["Deepwater Tavern"] = "Taverne de l'Eau-profonde",
		["Dragonmaw Gates: kill these as you meet them"] = "Portes des Dragonmaw : tuez-les au fur et à mesure",
		["Druid training"] = "Entraînement de druide",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Farren"] = "Farren",
		["Fly to Astranaar"] = "Envolez-vous vers Astranaar",
		["Fly to {zone:1453}"] = "Volez jusqu'à {zone:1453}",
		["Fly to {zone:1455}"] = "Envolez-vous vers {zone:1455}",
		["Follow the road south over the bridge to {object:376} at the {zone:1437} end, where {npc:1075} waits."] = "Suivez la route vers le sud par le pont jusqu'à {object:376} à l'extrémité {zone:1437}, où {npc:1075} attend.",
		["For King Magni in {zone:1455}, at the end of this guide"] = "Pour le roi Magni à {zone:1455}, à la fin de ce guide",
		["For {npc:2916} in {zone:1455}, at the end of this guide"] = "Pour {npc:2916} à {zone:1455}, à la fin de ce guide",
		["Group 12 · {zone:1437} & {zone:1424}"] = "Groupe 12 · {zone:1437} et {zone:1424}",
		["Hillsbrad Fields town hall"] = "Hôtel de ville des champs de Hautebrande",
		["Hillsbrad town hall"] = "Hôtel de ville de Hautebrande",
		["If you skipped {quest:474}, grind here to level 31.23 to stay on the route's plan."] = "Si vous avez passé {quest:474}, tuez des monstres ici jusqu'au niveau 31.23 pour suivre le plan de l'itinéraire.",
		["Inside"] = "À l'intérieur",
		["Level 30 and 32 spells"] = "Sorts des niveaux 30 et 32",
		["Level 31.23"] = "Niveau 31.23",
		["Murloc heads"] = "Têtes de murloc",
		["North along the road to {object:376}. {npc:271460} stands in the ruins (use the {item:279996}); the {npc:271481} is held on the west side: lead it out to {npc:1072}."] = "Au nord le long de la route vers {object:376}. {npc:271460} se trouve dans les ruines (utiliser le {item:279996}) ; le {npc:271481} est retenu du côté ouest : ramenez-le à {npc:1072}.",
		["North-east to the Dragonmaw Gates: {npc:271338} stands at the gates (use the {item:279996})."] = "Au nord-est vers les Portes des Dragonmaw : {npc:271338} se trouve aux portes (utiliser le {item:279996}).",
		["Off the boat, {npc:251493} is the first you meet, north-west of the flight master."] = "En descendant du bateau, {npc:251493} est le premier que vous rencontrez, au nord-ouest du maître de vol.",
		["On the top floor"] = "Au dernier étage",
		["On the way"] = "En chemin",
		["Pick up everything in town before heading out. {npc:2381} and {npc:2438} stand between the flight master and the inn, Farren and {npc:2366} at the inn, Maleb in the town hall."] = "Prenez tout en ville avant de partir. {npc:2381} et {npc:2438} se tiennent entre le maître de vol et l'auberge, Farren et {npc:2366} à l'auberge, Maleb à l'hôtel de ville.",
		["Snapjaws"] = "Gueules d'acier",
		["South to the Dragonmaw's Angerfang Encampment: the first catapult stands on the way, and the {object:671518} lies in the camp."] = "Au sud vers le campement de Hargnecroc des Dragonmaw : la première catapulte se trouve sur le chemin, et le {object:671518} se trouve dans le camp.",
		["Southshore"] = "Austrivage",
		["Southshore flight master"] = "Maître de vol d'Austrivage",
		["Syndicate camp"] = "Camp du Syndicat",
		["Take the Deeprun Tram from the {object:28027} to {zone:1455}."] = "Prenez le Tram des profondeurs depuis le {object:28027} jusqu'à {zone:1455}.",
		["The Green Belt"] = "La Ceinture Verte",
		["The Snapjaw turtles bask along the river east of Southshore, south of {object:1772} (Horde)."] = "Les tortues Gueule d'acier se prélassent le long de la rivière à l'est d'Austrivage, au sud de {object:1772} (Horde).",
		["The Syndicate camp sits on the Alterac border in northern Hillsbrad, west of {object:1772} (Horde); the documents lie in the camp."] = "Le camp du Syndicat se trouve à la frontière d'Alterac dans le nord de Hautebrande, à l'ouest de {object:1772} (Horde) ; les documents se trouvent dans le camp.",
		["The Torn Fin murlocs crowd the Western Strand, south-west of Southshore.\nCareful: One camp holds a tight cluster of Oracles that all aggro together."] = "Les murlocs Aileron déchiré encombrent le Rivage occidental, au sud-ouest d'Austrivage.\nAttention : Un camp contient un groupe serré d'oracles qui attaquent tous ensemble.",
		["The Villards"] = "Les Villard",
		["The cheese shop in the {object:2096}."] = "La fromagerie dans {object:2096}.",
		["The naga hold the shore south-east of Southshore."] = "Les nagas occupent le rivage au sud-est d'Austrivage.",
		["The next step, {quest:474}, pits you against an elite chieftain: skip it."] = "L'étape suivante, {quest:474}, vous oppose à un chef élite : passez-la.",
		["The yetis live in the cave in the hills north of Southshore, on your way back south."] = "Les yetis vivent dans la grotte dans les collines au nord d'Austrivage, sur votre chemin du retour vers le sud.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2091} is a level 32 elite: most classes solo it at level 34, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Shadowcasters stand on either side of him, and at least one is linked to him, so it joins when he is pulled. Non-elite centurions and captains are spread around his ring of tents."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:2091} est un élite de niveau 32 : la plupart des classes le battent seules au niveau 34, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.\nAttention : des lanceurs de sorts se tiennent de chaque côté de lui, et au moins l'un d'eux lui est lié : il se joint au combat quand vous l'attirez. Des centurions et des capitaines non élites sont répartis autour de son cercle de tentes.",
		["Timed, 15 minutes to Southshore: only with your hearthstone set at Southshore's inn"] = "Chronométrée, 15 minutes jusqu'à Austrivage : seulement avec la pierre de foyer liée à l'auberge d'Austrivage",
		["To Deepwater Tavern"] = "Vers la taverne de l'Eau-profonde",
		["Torn Fin murlocs"] = "Murlocs Aileron déchiré",
		["Underwater"] = "Sous l'eau",
		["West along the road to Menethil."] = "À l'ouest par la route jusqu'au Port de Menethil.",
		["West of Southshore, in the town hall of Hillsbrad Fields: use the {item:279386} from the bags beside the lectern in front of the magistrate's place. Players report it must be the lectern, not the table."] = "À l'ouest d'Austrivage, dans l'hôtel de ville des champs de Hautebrande : utiliser {item:279386} depuis les sacs à côté du lutrin, devant la place du magistrat. Des joueurs signalent que c'est le lutrin qui compte, pas la table.",
		["Yeti cave"] = "Grotte des yétis",
		["grind on {npc:1418}"] = "tuez en boucle : {npc:1418}",
		["{item:280331}, from the Maddened Rotclaws: leave it in {quest:98283}'s cave (69.5,34.7) to call it"] = "{item:280331}, sur les griffes pourries affolées : la déposer dans la grotte de {quest:98283} (69,5 ; 34,7) pour l'attirer",
		["{item:3713}, from {npc:2381}"] = "{item:3713}, chez {npc:2381}",
		["{npc:1071} stands in the dwarves' camp."] = "{npc:1071} se tient dans le camp des nains.",
		["{npc:2104} stands on the top floor of Menethil Keep: go up inside, the arrow cannot tell the floors apart."] = "{npc:2104} se trouve au dernier étage du donjon de Menethil : montez à l'intérieur, la flèche ne distingue pas les étages.",
		["{npc:2104}: for {npc:270637}; on the top floor"] = "{npc:2104} : pour {npc:270637} ; au dernier étage",
		["{npc:211033}: only offered once you have handed in library books (the Library Books guide)"] = "{npc:211033} : proposée seulement une fois que vous avez rendu des livres de la bibliothèque (le guide Livres de la bibliothèque)",
		["{npc:2228}, inside"] = "{npc:2228}, à l'intérieur",
		["{npc:2276}, inside"] = "{npc:2276}, à l'intérieur",
		["{npc:2366}, in the inn: for {object:3204} (04-stranglethorn-vale)"] = "{npc:2366}, à l'auberge : pour {object:3204} (04-vallée-de-strangleronce)",
		["{npc:2382}: the lions come later"] = "{npc:2382} : les lions viendront plus tard",
		["{npc:2430}, upstairs"] = "{npc:2430}, à l'étage",
		["{npc:2438} also wants a {item:3719}, a {item:2997} and {item:2321}: crafted or bought; the cloak is turned in when you are back in Southshore later."] = "{npc:2438} veut aussi un {item:3719}, un {item:2997} et {item:2321} : fabriqués ou achetés ; la cape est à rendre quand vous revenez à Austrivage plus tard.",
		["{npc:251493}, north-west of the flight master"] = "{npc:251493}, au nord-ouest du maître de vol",
		["{npc:2708} is in the {object:2164}; {npc:211033} near the canal; {npc:5081} south of the {object:2101}."] = "{npc:2708} est dans {object:2164} ; {npc:211033} près du canal ; {npc:5081} au sud de {object:2101}.",
		["{npc:2711}: his trail leads to Arathi"] = "{npc:2711} : sa piste mène en Arathi",
		["{npc:271462} stands in the south-eastern hills: use the {item:279996} beside it."] = "{npc:271462} se dresse dans les collines du sud-est : utilisez la {item:279996} à côté.",
		["{npc:2784}, the {object:171709}"] = "{npc:2784}, {object:171709}",
		["{npc:4961} waits in the Pig and Whistle tavern in {object:2100}; he and his two thugs fight you, but stop once beaten."] = "{npc:4961} attend à la Taverne du Cochon siffleur, dans {object:2100} ; lui et ses deux voyous vous attaquent, mais s'arrêtent une fois vaincus.",
		["{npc:5479} trains warriors in {object:2100}, beside the Pig and Whistle. {npc:6236} waits on Fray Island in the {zone:1413}, on the way to Ratchet much later (40-50/01)."] = "{npc:5479} forme les guerriers dans {object:2100}, à côté de la taverne du Cochon siffleur. {npc:6236} attend sur l'île de la Dispute dans {zone:1413}, sur la route de Cabestan, bien plus tard (40-50/01).",
		["{npc:5683} (Groupe Alliance: optional, Forever players report he no longer offers it)"] = "{npc:5683} (Groupe Alliance : facultative, des joueurs de Forever signalent qu'il ne la propose plus)",
		["{npc:5683} waits north of {object:376} by the {object:2673}; {npc:271322} a short walk further north-east."] = "{npc:5683} attend au nord de {object:376} près du {object:2673} ; {npc:271322} un peu plus loin au nord-est.",
		["{object:671518}: for {npc:2104}"] = "{object:671518} : pour {npc:2104}",
		["{zone:1455} flight master"] = "Maître de vol de {zone:1455}",
		["{zone:1455} has no druid trainer: train with {npc:5504} in {zone:1453} before the tram."] = "{zone:1455} n'a pas de maître des druides : entraînez-vous auprès de {npc:5504} à {zone:1453} avant le tram.",
} end)()
t.guides["groupe-alliance/15-desolace"] = (function() return {
		["Escort {npc:5644}"] = "Escortez {npc:5644}",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Fly to Astranaar"] = "Envolez-vous vers Astranaar",
		["Follow the road west out of Astranaar; {object:19863} lies north of it."] = "Suivez la route vers l'ouest en sortant d'Astranaar ; {object:19863} se trouve au nord.",
		["Follow the road west past {object:19559} (Horde) and south-west through the {object:19556} into {zone:1443}; {object:176948} stands at the top of the pass."] = "Suivez la route vers l'ouest passé {object:19559} (Horde) et au sud-ouest à travers {object:19556} jusqu'à {zone:1443} ; {object:176948} se trouve au sommet du col.",
		["From Astranaar head north-west into the hills: the {quest:1738} is a glowing tree north of the road to {object:19863}. If you took {quest:65602}, the {item:190309} lies in a house among the trees north of {object:19863} (26.6,22.0). Then back past Astranaar to the Talondeep Path."] = "Depuis Astranaar, dirigez-vous au nord-ouest dans les collines : le {quest:1738} est un arbre lumineux au nord de la route vers {object:19863}. Si vous avez pris {quest:65602}, le {item:190309} se trouve dans une maison parmi les arbres au nord de {object:19863} (26.6,22.0). Puis retournez par Astranaar jusqu'au sentier de Talondeep.",
		["Group 13 · {zone:1443}"] = "Groupe 13 · {zone:1443}",
		["Her brother {npc:5643} (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The {npc:13019} keeps the sceptre in the fortress's main building."] = "Son frère {npc:5643} (36) arpente la forteresse avec les sectateurs de la Lame ardente (30-33) : attirez-le seul. {npc:13019} garde le sceptre dans le bâtiment principal de la forteresse.",
		["Inside"] = "À l'intérieur",
		["Kodo Graveyard"] = "Cimetière des kodos",
		["Kolkar Village"] = "Village des Kolkar",
		["Lead {npc:5644} out of the fortress; she walks off once you are clear of it. {npc:5642} takes the turn-in at {object:176948} at the end of the guide."] = "Sortez {npc:5644} de la forteresse ; elle s'en va une fois que vous en êtes sorti. {npc:5642} récupère la quête à {object:176948} à la fin du guide.",
		["Malem chest"] = "Coffre de Malem",
		["Out of Thunder Axe Fortress"] = "Sortie de la Forteresse de Hache-Tonnerre",
		["Sargeron"] = "Sargeron",
		["Scorpashi venom"] = "Venin scorpashi",
		["The Hatefury satyrs hold the ruins of Sargeron, east of {object:176948}.\nCareful: Hatefury Rogues spawn stealthed, and Hatefury Tricksters have a poison proc on their attacks."] = "Les satyres Fielfurie occupent les ruines de Sargeron, à l'est de {object:176948}.\nAttention : Les voleurs Fielfurie apparaissent camouflés, et les entourloupeurs Fielfurie ont un effet de poison sur leurs attaques.",
		["The Kolkar roam the plains around Kolkar Village; their ears are for {npc:5752}."] = "Les Kolkar errent dans les plaines autour du village des Kolkar ; leurs oreilles sont pour {npc:5752}.",
		["The Scorpashi scorpids hunt the hills around Kormek's Hut on the road south."] = "Les scorpides Scorpashi chassent dans les collines autour de la hutte de Kormek sur la route vers le sud.",
		["The chest lies in the ruins south-west of {object:176948}."] = "Le coffre se trouve dans les ruines au sud-ouest de {object:176948}.",
		["Use {npc:11596}'s {item:13892} on an {npc:4700} and walk the tamed kodo back to his camp, five times; Aged Kodos also drop the hides."] = "Utilisez le {item:13892} de {npc:11596} sur un {npc:4700} et ramenez le kodo apprivoisé à son camp, cinq fois ; les Vieux kodos lâchent aussi les peaux.",
		["{item:190309}, north of {object:19863}"] = "{item:190309}, au nord de {object:19863}",
		["{item:6767}; inside"] = "{item:6767} ; à l'intérieur",
		["{npc:11596}'s camp is on the road south of Kolkar Village, by the Kodo Graveyard."] = "Le camp de {npc:11596} se trouve sur la route au sud du village des Kolkar, près du cimetière des kodos.",
		["{npc:11863}'s tower stands on the hill west of Thunder Axe Fortress: take his quest first, the sceptre he wants is in the fortress."] = "La tour de {npc:11863} se trouve sur la colline à l'ouest de la forteresse Hache-Tonnerre : prenez sa quête d'abord, le sceptre qu'il veut est dans la forteresse.",
		["{npc:5643} and the Seer"] = "{npc:5643} et le Prophète",
		["{npc:5644} hides inside the Burning Blade's fortress south-west of {object:176948}."] = "{npc:5644} se cache à l'intérieur de la forteresse de la Lame ardente au sud-ouest de {object:176948}.",
		["{npc:5644}, inside"] = "{npc:5644}, à l'intérieur",
		["{object:176948} flight master"] = "Maître de vol de {object:176948}",
		["{quest:5741}; on the top floor"] = "{quest:5741} ; au dernier étage",
} end)()
t.guides["groupe-alliance/16-orneval-paluns"] = (function() return {
		["Astranaar"] = "Astranaar",
		["Astranaar flight master"] = "Maître de vol d'Astranaar",
		["Back to Auberdine"] = "Retour à Auberdine",
		["Boat to {object:1162}"] = "Bateau pour {object:1162}",
		["Contested zone: the camps in the east (Xavian, the Forsaken camp south of Forest Song) lie around Splintertree Post (Horde) and the road the Horde takes from the {zone:1413}. Stay grouped there."] = "Zone contestée : les camps de l'est (Xavian, le camp des Réprouvés au sud de Chant des forêts) entourent le poste de Bois-brisé (Horde) et la route que prend la Horde depuis {zone:1413}. Y rester groupés.",
		["Dartol's Rod"] = "Bâtonnet de transformation de Dartol",
		["Deepwater Tavern"] = "Taverne de l'Eau-profonde",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Fly to Auberdine"] = "Envolez-vous pour Auberdine",
		["Follow the road east to the satyr camps of Xavian; {npc:3920} hides at their edge."] = "Suivez la route vers l'est jusqu'aux camps de satyres de Xavian ; {npc:3920} se cache à leur lisière.",
		["Forest Song"] = "Chant des forêts",
		["Forest Song, the Night Elf outpost at the eastern end of the road: {npc:3848} stands there."] = "Chant des forêts, le poste avancé des elfes de la nuit à l'extrémité est de la route : {npc:3848} s'y trouve.",
		["From Auberdine to Rut'theran Village: the flight for Night Elves and whoever learned it in Group 8, else the boat from the Auberdine dock; then the portal up to {zone:1457}. {npc:4521} lives in the city (the map marks her)."] = "D'Auberdine au village de Rut'theran : le vol pour les Elfes de la nuit et ceux qui l'ont appris au Groupe 8, sinon le bateau du quai d'Auberdine ; puis le portail qui monte à {zone:1457}. {npc:4521} vit dans la ville (la carte la marque).",
		["Group 14 · {zone:1440} & {zone:1437}"] = "Groupe 14 · {zone:1440} et {zone:1437}",
		["Insane druids"] = "Druides fous",
		["Inside"] = "À l'intérieur",
		["Melyria and {npc:3901}"] = "Sentinelle Melyria Frostshadow et {npc:3901}",
		["Night Run"] = "Défilé de la nuit",
		["Satyrnaar"] = "Satyrnaar",
		["Take the tunnel into the Howling Vale; the tome lies in the ruins at its west end."] = "Prenez le tunnel vers la Vallée hurlante ; le tome se trouve dans les ruines à son extrémité ouest.",
		["The Bluegill murlocs on the beach south-west of Menethil carry the ingots."] = "Les murlocs Branchie-bleue sur la plage au sud-ouest du Port de Menethil portent les lingots.",
		["The Crazed and Withered Ancients north of the moonwell carry the {item:5475}; the worn chest it opens stands among them."] = "Les Anciens fous et les Anciens flétris au nord du puits de lune portent la {item:5475} ; le vieux coffre qu'elle ouvre se trouve parmi eux.",
		["The Dor'Danil Barrow Den: kill these as you meet them"] = "Le Refuge des saisons de Dor'danil : tuez-les au fur et à mesure",
		["The Forsaken's camp lies in the woods south of Forest Song.\nRusty chests lie around the Shadethicket furbolg camps west of the Forsaken; open them until one holds the pommel.\nCareful: Non-elite Forsaken of about level 28-30 guard the camp. Some of them are stealthed, and the ones around the table often aggro together."] = "Le camp des Réprouvés se trouve dans les bois au sud de Chant des forêts.\nDes coffres rouillés se trouvent autour des camps des furbolgs Ombrefeuille à l'ouest des Réprouvés ; ouvrez-les jusqu'à ce que l'un contienne le pommeau.\nAttention : des Réprouvés non-élites d'environ niveau 28-30 gardent le camp. Certains sont camouflés, et ceux autour de la table aggro souvent ensemble.",
		["The second {object:19901} lies in the valley of Night Run, on the way west."] = "Le second {object:19901} se trouve dans la vallée du Défilé de la nuit, sur la route vers l'ouest.",
		["The shrine sits on the hill just south-east of the moonwell; follow the winding path up."] = "L'Autel caché se trouve sur la colline juste au sud-est du puits de lune ; suivez le sentier sinueux.",
		["The three druids stand together at the Forsaken camp south of Forest Song.\nCareful: The den has many mobs that respawn quickly, including stealthed undead and patrols, so extra mobs often join a fight."] = "Les trois druides se tiennent ensemble au camp des Réprouvés au sud de Chant des forêts.\nAttention : le terrier contient beaucoup de monstres qui réapparaissent vite, y compris des morts-vivants camouflés et des patrouilles, donc des monstres supplémentaires rejoignent souvent le combat.",
		["The wreck of the Flying Osprey lies in the shallows south of the keep."] = "L'épave du Flying Osprey repose dans les hauts-fonds au sud du donjon.",
		["The {npc:3931} walks the shore of {quest:1035}, south-west of the chests; the {object:669176} lies north of the lake, on the way.\nCareful: Other mobs, some of them underwater, sit near the island. Clear them first so they don't join the fight when you pull the Oracle."] = "{npc:3931} arpente les rives de {quest:1035}, au sud-ouest des coffres ; {object:669176} se trouve au nord du lac, en chemin.\nAttention : d'autres monstres, dont certains sous l'eau, se tiennent près de l'île. Éliminez-les d'abord pour qu'ils ne se joignent pas au combat quand vous attirez l'Oracle.",
		["The {object:19901} stands in the satyr camp of Satyrnaar, further east along the road.\nCareful: The Felmusk Rogues in Night Run often go stealthed, and Satyrnaar has satyr casters."] = "Le {object:19901} se trouve dans le camp satyre de Satyrnaar, plus à l'est le long de la route.\nAttention : les voleurs Gangremusc du Défilé de la nuit sont souvent camouflés, et Satyrnaar compte des lanceurs de sorts satyres.",
		["{item:2702}; underwater"] = "{item:2702} ; sous l'eau",
		["{npc:1217} stands on the upper floor of Menethil's keep."] = "{npc:1217} se tient à l'étage supérieur du donjon de Menethil.",
		["{npc:3696} and his guards camp just east of {npc:3897}.\nCareful: Wolves and spiders roam near the camp and can join a fight. Some of the wolves come in pairs."] = "{npc:3696} et ses gardes campent juste à l'est de {npc:3897}.\nAttention : des loups et des araignées rôdent près du camp et peuvent se joindre au combat. Certains loups vont par deux.",
		["{npc:3894}, inside"] = "{npc:3894}, à l'intérieur",
		["{npc:3897}, a furbolg untouched by the corruption, sits south of the road below Mystral Lake."] = "{npc:3897}, un furbolg épargné par la corruption, se trouve au sud de la route sous le Lac Mystral.",
		["{npc:3940}, inside The Dor'Danil Barrow Den"] = "{npc:3940}, à l'intérieur du Refuge des saisons de Dor'danil",
		["{npc:3941}, inside The Dor'Danil Barrow Den"] = "{npc:3941}, à l'intérieur du Refuge des saisons de Dor'danil",
		["{npc:3942}, inside The Dor'Danil Barrow Den"] = "{npc:3942}, à l'intérieur du Refuge des saisons de Dor'danil",
		["{npc:4619} leads the Xavian satyrs; he carries the branch."] = "{npc:4619} dirige les satyres de Xavian ; il porte la branche.",
		["{object:669176}: for {npc:3961} in Astranaar"] = "{object:669176} : pour {npc:3961} à Astranaar",
		["{zone:1457}: {quest:1142} (detour)"] = "{zone:1457} : {quest:1142} (détour)",
} end)()
t.guides["groupe-alliance/17-strangleronce"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "« Loup de mer » MacKinley, au dernier étage",
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "Revenez vers le sud après Nesingwary : les Panthères et les Raptors de Strangleronce courent dans les clairières à l'ouest du camp vers la côte ; les anciens tigres tiennent les collines au sud-ouest.",
		["Both roam the grass around the camp and along the road north."] = "Les deux parcourent l'herbe autour du camp et le long de la route vers le nord.",
		["Careful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults."] = "Attention : des camps de trolls sont proches du territoire des tigres, et les trolls peuvent se joindre au combat si vous attirez sans précaution.\nAttention : le nid des raptors abrite de jeunes raptors qui se joignent au combat quand vous attaquez les adultes.",
		["Down to {object:3204}"] = "Descendez jusqu'à {object:3204}",
		["Druid training"] = "Entraînement de druide",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Fly to Darkshire"] = "Envolez-vous pour Sombre-Comté.",
		["Fly to {object:3204}"] = "Envolez-vous pour {object:3204}",
		["Fly to {object:81}"] = "Envolez-vous vers {object:81}",
		["Fly to {zone:1453}"] = "Volez jusqu'à {zone:1453}",
		["Follow the main road south the length of the jungle, past the {object:3202} turn-off, to {object:3204} on the southern cape."] = "Suivez la route principale vers le sud à travers la jungle, passez l'embranchement {object:3202}, jusqu'à {object:3204} sur le cap sud.",
		["Follow the west coast north; the haunted island lies off the shore west of Nesingwary's camp. Just reach it."] = "Suivez la côte ouest vers le nord ; l'île hantée se trouve au large, à l'ouest du camp de Nesingwary. Il suffit de l'atteindre.",
		["For Archmage Ansirem in {zone:1416}"] = "Pour l'archimage Ansirem dans {zone:1416}",
		["From {zone:1431} take the road south into Stranglethorn; the hunters' tents stand just west of the road past the Rebel Camp turn-off."] = "Depuis {zone:1431}, prenez la route vers le sud jusqu'à Strangleronce ; les tentes des chasseurs se trouvent juste à l'ouest de la route après l'embranchement du Camp rebelle.",
		["Gluggle, a rare murloc on the coast west of camp, drops the {item:4614}: take it if you meet him"] = "Gluggle, un murloc rare sur la côte à l'ouest du camp, laisse tomber le {item:4614} : prenez-le si vous le croisez",
		["Group 15 · {zone:1434}"] = "Groupe 15 · {zone:1434}",
		["Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave. Pick up Green Hills pages as they drop.\nCareful: Kurzen Commandos are level 34-35, not elite, and often spawn stealthed; near death they use Smoke Bomb."] = "Les Réducteurs de tête se tiennent plus loin dans le composé ; les Commandos rôdent camouflés autour et dans la grotte. Ramassez les pages des Collines verdoyantes au fur et à mesure.\nAttention : les Commandos de Kurzen sont de niveau 34-35, non élites, et apparaissent souvent camouflés ; près de la mort, ils utilisent Bombe fumigène.",
		["Herod's records lie in a hut on the compound's west side; his strongbox sits farther east, by the cave mouth."] = "Les registres de Herod se trouvent dans une hutte du côté ouest de la base ; son coffre est plus à l'est, près de l'entrée de la grotte.",
		["Into {zone:1434}"] = "Vers {zone:1434}",
		["Into {zone:1436}"] = "Vers {zone:1436}",
		["Kurzen's Compound"] = "Base de Kurzen",
		["Kurzen's Compound: kill these as you meet them"] = "Base de Kurzen : tuez-les au fur et à mesure",
		["Loop through the troll ruins of the north and centre: each holds one stone tablet of the troll legends. Shadowmaw Panthers prowl stealthed in the jungle around them; the Venture Co. camp on Lake Nazferiti carries the Tumbled Crystals."] = "Faites le tour des ruines trolls du nord et du centre : chacune contient une tablette de pierre des légendes trolls. Des panthères Ombregueule rôdent camouflées dans la jungle alentour ; le camp de la KapitalRisk au Lac Nazfériti contient les cristaux réduits.",
		["Nesingwary's Expedition"] = "Expédition de Nesingwary",
		["Panthers, raptors and elder tigers"] = "Panthères, raptors et anciens tigres",
		["Rebel Camp"] = "Camp rebelle",
		["River Crocolisks swim the river by the Rebel Camp."] = "Des Crocilisques des rivières nagent dans la rivière près du Camp rebelle.",
		["River crocolisks"] = "Crocilisques des rivières",
		["Skullsplitter trolls"] = "Trolls Skullsplitter",
		["Snapjaw Crocolisks"] = "Crocilisques Gueule d'acier",
		["Snapjaw Crocolisks bask on the shore and islands along the coast north of {object:3204}."] = "Des crocilisques Gueule d'acier se prélassent sur le rivage et les îles le long de la côte au nord de {object:3204}.",
		["Stranglethorn Tigers"] = "Tigres de Strangleronce",
		["Take the road north; {npc:738} patrols it, the camp sits in the hills to the west."] = "Prenez la route vers le nord ; {npc:738} y patrouille, le camp se trouve dans les collines à l'ouest.",
		["The Kurzen rebels hold the camp east of the Rebel Camp; work its outer edge, where Jungle Fighters and Medicine Men stand, and loot the supply crates by the tents."] = "Les rebelles de Kurzen occupent le camp à l'est du Camp rebelle ; travaillez sa lisière extérieure, où se tiennent des Combattants de la jungle et des Hommes-médecine, et pillez les caisses de ravitaillement près des tentes.",
		["The Savage Coast: kill these as you meet them"] = "La Côte sauvage : tuez-les au fur et à mesure.",
		["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "Les trolls Skullsplitter tiennent les ruines à l'est de la route entre Nesingwary et {object:3202}.",
		["The adult tigers prowl the hills just south and west of the camp."] = "Les tigres adultes rôdent dans les collines juste au sud et à l'ouest du camp.",
		["The elder tigers come later, on the way back from the Rebel Camp"] = "Les tigres âgés viennent plus tard, sur le chemin du retour depuis le Camp rebelle.",
		["The haunted island"] = "L'île hantée",
		["The jungle ruins"] = "Les ruines de la jungle",
		["The ore drops from Drywhisker kobolds in {zone:1417}"] = "Le minerai tombe des kobolds Sèche-moustache des {zone:1417}",
		["Thorsen patrols the road north of camp, toward the Rebel Camp."] = "Thorsen patrouille sur la route au nord du camp, en direction du Camp rebelle.",
		["Tram to {zone:1453}"] = "Tram pour {zone:1453}",
		["Walk back north; the Crystalvein Mine lies west of the road in the middle of the jungle. The Crystal Spine Basilisks there drop the shards.\nThe Bloodscalp trolls hold the ruins on the coast west of Nesingwary's camp."] = "Remontez vers le nord ; la Mine aux cristaux se trouve à l'ouest de la route au milieu de la jungle. Les basilics de cristal y laissent tomber les éclats.\nLes trolls Bloodscalp occupent les ruines sur la côte à l'ouest du camp de Nesingwary.",
		["Young tigers and panthers"] = "Jeunes tigres et panthères",
		["grind on {npc:1096}"] = "tuez en boucle : {npc:1096}",
		["{item:2006}: {object:58}; underwater"] = "{item:2006} : {object:58} ; sous l'eau",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}, dans une caisse de {object:263}",
		["{npc:2495}, by the bank; inside"] = "{npc:2495}, près de la banque ; à l'intérieur",
		["{npc:2495}, inside"] = "{npc:2495}, à l'intérieur",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, à l'étage de la taverne",
		["{npc:2498}, inside"] = "{npc:2498}, à l'intérieur",
		["{npc:2832}, in the {object:56910}; upstairs"] = "{npc:2832}, dans {object:56910} ; à l'étage",
		["{npc:469}, in the hut"] = "{npc:469}, dans la hutte",
		["{npc:6807}, {object:56910}; upstairs"] = "{npc:6807}, {object:56910} ; à l'étage",
		["{npc:687} on the way"] = "{npc:687} en chemin",
		["{npc:715}, from {zone:1441}"] = "{npc:715}, depuis {zone:1441}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716} collectionne {item:2755} : les pages tombent de presque tous les humanoïdes de la jungle. Assemblez les pages en chapitres au fur et à mesure.",
		["{npc:729} and the Lashtail raptors"] = "{npc:729} et les raptors flagellants",
		["{npc:729}, the great tiger, lairs on the hilltop south-west of the camp; Lashtail Raptors run south of it, along the way to {object:3204}."] = "{npc:729}, le grand tigre, a son repaire au sommet de la colline au sud-ouest du camp ; des raptors flagellants courent au sud de celle-ci, le long de la route vers {object:3204}.",
		["{npc:737}, in the tavern"] = "{npc:737}, dans la taverne",
		["{npc:737}, upstairs"] = "{npc:737}, à l'étage",
		["{npc:770}: for {npc:773} in {object:3204}"] = "{npc:770} : pour {npc:773} à {object:3204}",
		["{npc:773}, in the tavern; upstairs"] = "{npc:773}, dans la taverne ; à l'étage",
		["{npc:773}, upstairs"] = "{npc:773}, à l'étage",
		["{npc:941}, below ground"] = "{npc:941}, sous terre",
		["{object:1162} flight master"] = "Maître de vol de {object:1162}",
		["{object:287}, upstairs"] = "{object:287}, à l'étage",
		["{object:288}, below ground"] = "{object:288}, sous terre",
		["{object:3204} flight master"] = "Maître de vol de {object:3204}",
		["{object:56910} is the tall building over the harbour; most of the quest givers are on its floors or the docks below."] = "{object:56910} est le grand bâtiment qui domine le port ; la plupart des donneurs de quêtes se trouvent à ses étages ou sur les quais en contrebas.",
		["{object:81} flight master"] = "{object:81} maître de vol",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201} : faites simplement le tour du camp des chasseurs",
		["{quest:2904}, from Gnomeregan: Chief Engineer Scooty runs the goblin transporter in {object:3204} (the map marks him)."] = "{quest:2904}, de Gnomeregan : l'ingénieur en chef Scooty tient le transporteur gobelin de {object:3204} (la carte le marque).",
		["{zone:1434}: kill these as you meet them"] = "{zone:1434} : tuez-les au fur et à mesure.",
		["{zone:1455} has no druid trainer: take the Deeprun Tram from {object:171524} to {zone:1453} and train with {npc:5504}."] = "{zone:1455} n'a pas de maître des druides : prenez le Tram des profondeurs depuis {object:171524} jusqu'à {zone:1453} et entraînez-vous avec {npc:5504}.",
} end)()
t.guides["groupe-alliance/18-arathi"] = (function() return {
		["A {npc:2434} lurks unseen on the edge of {quest:538}; kill him and read the contract he carries."] = "Un {npc:2434} rôde invisible au bord de {quest:538} ; tuez-le et lisez le contrat qu'il porte.",
		["Back west through {zone:1430} to Darkshire."] = "Retour vers l'ouest par {zone:1430} jusqu'à Sombre-Comté.",
		["Below ground"] = "Sous terre",
		["Careful: Syndicate Spies and Assassins can be stealthed. Assassins also poison you.\nCareful: About three stealthed Syndicate mobs are inside {npc:2320}'s house. {npc:2320} does not join when they are pulled, and a ranged attack through the doorway brings him out by himself."] = "Attention : les espions et les assassins du Syndicat peuvent être camouflés. Les assassins vous empoisonnent aussi.\nAttention : environ trois membres du Syndicat camouflés se trouvent dans la maison de {npc:2320}. {npc:2320} ne se joint pas au combat quand vous les attirez, et une attaque à distance par la porte le fait sortir seul.",
		["Circle of Outer Binding"] = "Cercle de lien extérieur",
		["Circle of West Binding"] = "Cercle de lien occidental",
		["Crushridge ogres"] = "Ogres Cassecrête",
		["Dalaran"] = "Dalaran",
		["Drywhisker Gorge: kill these as you meet them"] = "Gorge des Sèches-moustaches : tuez-les au fur et à mesure",
		["Each key lies at one of the Highlands' standing-stone circles: east of the shards, near {object:2685} and in the west. The {object:2702} stands west of {object:2685}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "Chaque clé se trouve dans l'un des cercles de pierres dressées des Hautes-terres : à l'est des éclats, près de {object:2685} et à l'ouest. Le {object:2702} se trouve à l'ouest de {object:2685}.\nAttention : chaque pierre centrale est gardée par environ trois élémentaires de niveau 39 environ qui attaquent ensemble si vous cliquez sur la pierre sans les avoir éliminés : exilés ardents au cercle occidental, exilés foudroyants au cercle extérieur, exilés grimpeurs au cercle oriental.",
		["East along the road to the Fallow Sanctuary. {npc:256028} mobs drop the crystals; Noboru walks the ruins and drops his cudgel."] = "Vers l'est le long de la route jusqu'au Sanctuaire des friches. Les sbires de {npc:256028} laissent tomber les cristaux ; Noboru arpente les ruines et laisse tomber son gourdin.",
		["Ebenezer Rustlocke"] = "Ebenezer Rustlocke",
		["Escort the professor to the beach north of the cove and guard him while he works; naga attack in waves.\nCareful: The ambush is two level 40 water elementals, and they are immune to frost. If the fight happens inside the cave, the professor joins in instead of working and further elementals keep appearing; holding the elementals at the cave entrance, away from him, lets him finish with only the first two to deal with."] = "Escortez le professeur jusqu'à la plage au nord de la crique et protégez-le pendant qu'il travaille ; les nagas attaquent par vagues.\nAttention : l'embuscade se compose de deux élémentaires d'eau de niveau 40, insensibles au givre. Si le combat a lieu dans la grotte, le professeur s'y joint au lieu de travailler et d'autres élémentaires continuent d'apparaître ; retenir les élémentaires à l'entrée de la grotte, loin de lui, lui permet de terminer avec seulement les deux premiers à affronter.",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Faldir's Cove"] = "Crique de Faldir",
		["Fallow Sanctuary"] = "Sanctuaire des friches",
		["Fly to Darkshire"] = "Envolez-vous pour Sombre-Comté.",
		["Fly to {quest:538}"] = "Envolez-vous pour {quest:538}",
		["Fly to {zone:1453}"] = "Volez jusqu'à {zone:1453}",
		["Follow the road east out of Hillsbrad over Thoradin's Wall to {object:2685}."] = "Suivez la route vers l'est depuis Hautebrande par le Mur de Thoradin jusqu'à {object:2685}.",
		["Follow the road north out of {quest:538} into the mountains. Mountain lions roam the slopes; the Syndicate in Strahnbrad wear the signet rings, and {npc:2306} walks the manor grounds on the north side of town."] = "Suivez la route vers le nord depuis {quest:538} jusqu'aux montagnes. Des lions des montagnes rôdent sur les pentes ; les membres du Syndicat à Strahnbrande portent les chevalières, et {npc:2306} se promène dans le domaine du manoir au nord de la ville.",
		["Follow the road north to the draenei of the Harborage."] = "Suivez la route vers le nord jusqu'aux draeneï du Harborage.",
		["For {npc:1440} in {zone:1453}: keep it"] = "Pour {npc:1440} à {zone:1453} : gardez-la",
		["For {npc:2487} in {object:3204}: keep it"] = "Pour {npc:2487} à {object:3204} : gardez-le",
		["For {npc:2542} in {object:3204}: keep it"] = "Pour {npc:2542} à {object:3204} : gardez-le",
		["For {npc:2711} in {quest:538}"] = "Pour {npc:2711} dans {quest:538}",
		["From {zone:1455} take the tunnel east through {zone:1426} into {zone:1432} and follow the road to Thelsamar."] = "Depuis {zone:1455}, prenez le tunnel vers l'est à travers {zone:1426} jusqu'à {zone:1432} et suivez la route jusqu'à Thelsamar.",
		["Gavin's Naze"] = "Promontoire de Gavin",
		["Group 16 · {zone:1417}, {zone:1416} & {zone:1435}"] = "Groupe 16 · {zone:1417}, {zone:1416} et {zone:1435}",
		["Head back north-east past {object:2685}; {npc:2712} and {npc:2713} camp in the hills north of Go'Shek Farm."] = "Revenez au nord-est passé {object:2685} ; {npc:2712} et {npc:2713} campent dans les collines au nord de la ferme de Go'Shek.",
		["Head north past Go'Shek Farm; the shards glitter on the hill by the Circle of East Binding."] = "Allez au nord après la Ferme de Go'Shek ; les éclats brillent sur la colline près du Cercle de lien oriental.",
		["Inside"] = "À l'intérieur",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "Seulement si Gluggle vous a donné le pendentif à Strangleronce",
		["Phizzlethorpe"] = "Phizzlethorpe",
		["Ruins of Alterac: kill these as you meet them"] = "Ruines d'Alterac : tuez-les au fur et à mesure",
		["South-east along the loch to the dig site."] = "Longez le loch vers le sud-est jusqu'au site de fouilles.",
		["South-west to the Kirin Tor camp on the lake shore west of Dalaran, just over the border into {zone:1421}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "Au sud-ouest, au camp du Kirin Tor sur la rive du lac à l'ouest de Dalaran, juste au-delà de la frontière dans {zone:1421} : le {npc:269127} s'y trouve. L'archimage Ansirem se tient au sud-est, près du dôme.",
		["Stay with {npc:2713} while she sneaks into Go'Shek Farm and back; Horde orcs jump you on the way.\nCareful: Orcs that drop to low health run away. {npc:2713} follows them and can pull more mobs, so kill or slow runners fast."] = "Restez avec {npc:2713} pendant qu'elle s'infiltre dans la ferme de Go'Shek et en ressort ; des orcs de la Horde vous attaquent en chemin.\nAttention : les orcs qui tombent à basse vie s'enfuient. {npc:2713} les poursuit et peut attirer plus de monstres, donc tuez ou ralentissez les fuyards rapidement.",
		["Strahnbrad: kill these as you meet them"] = "Strahnbrande : tuez-les au fur et à mesure",
		["Subdue the succubus"] = "Soumettez la succube",
		["Summon Succubus"] = "Invoquer un succube",
		["The Crushridge ogres hold the hills north of Strahnbrad. Farther north, a worn wooden chest holds the {item:3706}; {npc:2320} of the {quest:537} stands right by it."] = "Les ogres Cassecrête occupent les collines au nord de Strahnbrande. Plus au nord, un coffre en bois usé contient le {item:3706} ; {npc:2320} du {quest:537} se tient juste à côté.",
		["The Drowned Reef: kill these as you meet them"] = "Le récif englouti : tuez-les au fur et à mesure",
		["The Drywhisker kobolds dig in the gorge east of Hammerfall (Horde); skirt the town to the north. They drop both the motes and Krazek's ore.\nCareful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "Les kobolds Sèche-moustache creusent dans la gorge à l'est de Trépas-d'Orgrim (Horde) ; contournez la ville par le nord. Ils laissent tomber à la fois les particules et le minerai de Krazek.\nAttention : chaque type de kobold s'enfuit chercher de l'aide quand sa vie est basse (kobolds à 30 %, géomètres et terrassiers à 15 %), ce qui peut en attirer d'autres.",
		["The Harborage"] = "Le Havre boueux",
		["The Syndicate hold the farm north-west of {object:2685}. A {npc:217589} crawls about the farm: catch one with {npc:217412}'s Entomology Starter Kit, then tick it off.\nCareful: Syndicate Highwaymen are level 30-31 and can cast Sneak while out of combat, so they are often stealthed and hard to spot."] = "Le Syndicat occupe la ferme au nord-ouest de {object:2685}. Un {npc:217589} rampe dans la ferme : attrapez-en un avec le kit de démarrage en entomologie de {npc:217412}, puis cochez-le.\nAttention : les malandrins du Syndicat sont de niveau 30-31 et peuvent lancer Camouflage hors combat, ils sont donc souvent camouflés et difficiles à repérer.",
		["The Witherbark trolls live in the hills south of Go'Shek Farm; Witch Doctors stand in the village, Shadow Hunters guard the far end of the valley."] = "Les trolls Flétrécorce vivent dans les collines au sud de la Ferme de Go'Shek ; des Sorciers-docteurs se tiennent dans le village, des Chasseurs de l'ombre gardent le fond de la vallée.",
		["The courier walks the road west of Go'Shek Farm with two guards; pull them off the road."] = "Le courrier emprunte la route à l'ouest de la ferme de Go'Shek avec deux gardes ; attirez-les hors de la route.",
		["The shards lie at the far end of Drywhisker Gorge."] = "Les éclats se trouvent au fond de la Gorge des Sèches-moustaches.",
		["The tomes lie in the ruined keep west of Strahnbrad; Argus Shadow Mages hold the ruins.\nCareful: Crushridge Warmongers call nearby allies within 15 yd once they fall below half health."] = "Les tomes se trouvent dans le donjon en ruine à l'ouest de Strahnbrande ; des mages de l'ombre d'Argus occupent les ruines.\nAttention : les combattants Cassecrête appellent les alliés proches dans un rayon de 15 m une fois leur vie descendue sous la moitié.",
		["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "Les deux épaves reposent dans la baie à l'ouest de la crique. Les cartes et les journaux sont à l'intérieur ; les gemmes gisent au fond de la mer autour. Des nagas Daguéchine nagent dans toute la baie.",
		["The western swamp"] = "Le marais occidental",
		["The wrecked caravan lies off the road near Biggs.\nCareful: The camp is full of Lost Ones around level 38. They stand in linked groups of 2-3, many are casters, and they respawn quickly."] = "La caravane détruite se trouve à l'écart de la route, près de Biggs.\nAttention : le camp est rempli de Lost Ones de niveau 38 environ. Ils se tiennent en groupes liés de 2 ou 3, beaucoup lancent des sorts, et ils réapparaissent vite.",
		["Thelsamar"] = "Thelsamar",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2417} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:2417} est un élite de niveau 40 : la plupart des classes le battent seules au niveau 42, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["Tram to {zone:1455}"] = "Tram pour {zone:1455}",
		["Walk back onto the span: Ebenezer lies under its Arathi end."] = "Revenez sur le pont : Ebenezer gît sous son extrémité côté Arathi.",
		["West along the coast to the goblins' cove; {npc:2766} keeps watch on the rocks above it."] = "Vers l'ouest le long de la côte jusqu'à la crique des gobelins ; {npc:2766} surveille les rochers au-dessus.",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "Jeunes crocilisques, Tisseuses des pleurs et Jaguars du marécage parcourent tous le marais autour de la route.",
		["{item:2321} for {npc:2438}'s cloak, from {npc:2381}, if you have none"] = "{item:2321} pour la cape de {npc:2438}, chez {npc:2381}, si vous n'en avez pas",
		["{item:3658}: Crushridge ogres"] = "{item:3658} : ogres Cassecrête",
		["{item:3659}: the {object:1760}; inside"] = "{item:3659} : {object:1760} ; à l'intérieur",
		["{item:4435} from {npc:2572}, {npc:2573} and {npc:2574}, by this stop"] = "{item:4435} depuis {npc:2572}, {npc:2573} et {npc:2574}, à cet arrêt",
		["{item:4492}; underwater"] = "{item:4492} ; sous l'eau",
