		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "La course suivante de {npc:2498} concernant Zanzil commence à {zone:1441} : passez-la.",
		["{npc:2535} and {npc:2536}"] = "{npc:2535} et {npc:2536}",
