t.guides["groupe-alliance/21-terres-ingrates-hinterlands"] = (function() return {
		["Aerie Peak"] = "Nid-de-l'Aigle",
		["Aerie Peak flight master"] = "Maître de vol de Nid-de-l'Aigle",
		["Agmond's End"] = "Fin d'Agmond",
		["Archaedas and the {object:131474}"] = "Archaédas et les {object:131474}",
		["Archaedas, the last boss, wakes the stone guardians around his room during the fight. Behind him, the {object:131474}: click them, talk to the spirit on the left, then click the Discs again for the miniature copy before you leave."] = "Archaédas, le dernier boss, réveille les gardiens de pierre autour de sa salle pendant le combat. Derrière lui, les {object:131474} : les cliquer, parler à l'esprit à gauche, puis cliquer à nouveau sur les Disques pour la copie miniature avant de partir.",
		["At the digsite by the road north to {zone:1432}, on the way to the Thelsamar flight."] = "Au site de fouilles, au bord de la route du nord vers {zone:1432}, sur le chemin du vol de Thelsamar.",
		["Back to {npc:264265}"] = "Retour vers {npc:264265}",
		["Blue Pearls from Stranglethorn"] = "Perles bleues de Strangleronce",
		["Both stand in the {object:32356}. Karnik's last task, An Ambassador of Evil, is in Angor Fortress in the {zone:1418}, which the route has left: do not take it."] = "Tous deux se tiennent dans {object:32356}. La dernière tâche de Karnik, An Ambassador of Evil, est dans la forteresse d'Angor, dans les {zone:1418}, que le parcours a quittées : ne pas la prendre.",
		["Clear the chapel's pews first: pulling Mograine brings the whole room. Mograine first; when he falls, Whitemane runs in, puts the group to sleep and raises him once: kill him again, then her."] = "Nettoyez d'abord les bancs de la chapelle : attirer Mograine fait venir toute la salle. Mograine en premier ; quand il tombe, Whitemane arrive, endort le groupe et le ressuscite une fois : tuez-le à nouveau, puis elle.",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Explore the hidden chamber"] = "Explorer la chambre cachée",
		["Fly from Thelsamar to {zone:1455}. {npc:1356}, {npc:6294} and {npc:5387} are all in the {object:32356}; {npc:6826} in the {object:32362}."] = "Griffon de Thelsamar à {zone:1455}. {npc:1356}, {npc:6294} et {npc:5387} sont tous dans l'{object:32356} ; {npc:6826} dans le {object:32362}.",
		["Fly to Southshore"] = "Envolez-vous pour Austrivage",
		["Fly to Thelsamar"] = "Volez vers Thelsamar",
		["Fly to {object:1162}"] = "Envolez-vous vers {object:1162}",
		["For {npc:2910}, on the way out of the {zone:1418}"] = "Pour {npc:2910}, en sortant des {zone:1418}",
		["For {npc:2916} in {zone:1455}"] = "Pour {npc:2916} à {zone:1455}",
		["From Theramore, ride north into the {zone:1413} to Ratchet, or fly if you know its flight path. {npc:6251} teaches in the house by the bank."] = "Depuis Theramore, allez au nord dans les {zone:1413} jusqu'à Cabestan, ou envolez-vous si vous connaissez son point de vol. {npc:6251} enseigne dans la maison près de la banque.",
		["Group 19 · {zone:1418} & {zone:1425}"] = "Groupe 19 · {zone:1418} & {zone:1425}",
		["Group of 5. {quest:1053} only comes after {quest:1052}, from {npc:1182} in {zone:1443}: without it, the Library still pays for the two books."] = "Groupe de 5. {quest:1053} ne vient qu'après {quest:1052}, de {npc:1182} en {zone:1443} : sans elle, la Bibliothèque paie quand même pour les deux livres.",
		["Inside Bloodfen Burrow"] = "À l'intérieur du Terrier des Rougefanges",
		["Keep 5 free quest log slots. Everyone takes the quests at their own pace; meet at the entrance for the run."] = "Garder 5 emplacements libres dans le journal de quêtes. Chacun prend les quêtes à son rythme ; se retrouver à l'entrée pour le donjon.",
		["Leave by the front, south to the Valley of Fangs."] = "Sortir par l'entrée, au sud vers la Vallée des Crocs.",
		["Lethlor Ravine"] = "Ravin de Lethlor",
		["Loksey and his dogs wait in a small alcove near the start. {quest:1050} lies on a bench or the floor of the narrow corridors, to the left as you enter the room. Doan is the last boss: at half health he shields himself and blows up everything near him, run out and come back. The red book for {npc:264265} is on a table on the right of Doan's room; the Scarlet Key, for the Armory and Cathedral doors, in the chest behind him."] = "Loksey et ses chiens attendent dans une petite alcôve près de l'entrée. {quest:1050} se trouve sur un banc ou au sol des couloirs étroits, à gauche en entrant dans la pièce. Doan est le dernier boss : à moitié vie, il se protège par un bouclier et fait exploser tout ce qui est près de lui, sortez et revenez. Le livre rouge pour {npc:264265} est sur une table à droite de la salle de Doan ; la Clé Écarlate, pour les portes de l'Armurerie et de la Cathédrale, dans le coffre derrière lui.",
		["On the way north: he stands on the western edge of the Dalaran crater, by the road from Hillsbrad to Silverpine."] = "En route vers le nord : il se tient sur le bord ouest du cratère de Dalaran, près de la route de Hautebrande à Pins-Argentés.",
		["Raleigh's next errand is in the Scarlet Monastery: alone, skip it; in a group, the next steps."] = "La prochaine commission de Raleigh est au Monastère écarlate : seul, passez ; en groupe, les étapes suivantes.",
		["Ratchet"] = "Cabestan",
		["Ride back east to Dustwind Gulch."] = "Retournez vers l'est au Goulet de la Bourrasque.",
		["Ride north to Thelsamar and fly to Southshore. {npc:3980} preaches by the inn."] = "Allez au nord jusqu'à Thelsamar et envolez-vous pour Austrivage. {npc:3980} prêche près de l'auberge.",
		["Ride north-east out of Southshore on the road into the {zone:1425}; Aerie Peak sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "Sortez d'Austrivage vers le nord-est sur la route menant aux {zone:1425} ; Nid-de-l'Aigle se trouve juste après la frontière. {npc:5635} tient sa cour au sommet, {quest:1450} s'occupe de la volière et {npc:7884} se tient près de l'auberge.",
		["Ride through {zone:1421}, then east across {zone:1420}: Horde land, keep clear of Brill and the guards on the roads. The monastery stands in the far north-east; the four wings are four doors in the courtyard."] = "Traversez {zone:1421}, puis allez vers l'est à travers {zone:1420} : territoire de la Horde, évitez Brill et les gardes sur les routes. Le monastère se trouve à l'extrême nord-est ; les quatre ailes sont quatre portes dans la cour.",
		["Ride west across the {zone:1418} to the Dustbelcher camp at Camp Boff. {npc:2944} stands in its middle with Wyrmhunters and Maulers around him."] = "Traversez les {zone:1418} vers l'ouest jusqu'au camp des Dustbelcher au camp Boff. {npc:2944} se tient au milieu avec des chasseurs de wyrms et des maulers autour de lui.",
		["Scarlet Monastery"] = "Monastère Écarlate",
		["Scarlet Monastery (dungeon, optional): Raleigh's errand"] = "Monastère écarlate (donjon, optionnel) : commission de Raleigh",
		["Share each quest with your group: click it in the quest log, then Share."] = "Partagez chaque quête au groupe : clic sur la quête dans le journal, puis Partager.",
		["Share each quest with your group: click it in the quest log, then Share. A {item:7666} may drop on the way: its chain goes on with {npc:6826} in {zone:1455}."] = "Partager chaque quête avec votre groupe : cliquer dessus dans le journal, puis Partager. Un {item:7666} peut tomber en route : sa suite continue avec {npc:6826} à {zone:1455}.",
		["Southshore"] = "Austrivage",
		["Southshore: {npc:3980}"] = "Austrivage : {npc:3980}",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "La prochaine tâche de Talonaxe attend un guide des {zone:1425} ultérieur.",
		["The Armory: {npc:3975}"] = "L'Armurerie : {npc:3975}",
		["The Cathedral: Mograine and Whitemane"] = "La Cathédrale : Mograine et Whitemane",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "Les Dragonnets flamboyants nichent dans le ravin à l'est de {npc:2888} ; laissez tranquilles les Gardiens des terres brûlées (élites). Le {item:4612} tombe rarement : prenez-le s'il tombe pendant que vous tuez des monstres.",
		["The Shadowforge dwarves of the digsite in front of the cave and of the outer cave drop both power stones, not often: no need to enter the instance for them. {npc:6294}'s chest is in the outer cave, at the back of the left-hand hall, behind a pillar, with two guards."] = "Les nains Ombreforge du site de fouilles devant la grotte et de la grotte extérieure lâchent les deux pierres de pouvoir, rarement : pas besoin d'entrer dans l'instance pour elles. Le coffre de {npc:6294} est dans la grotte extérieure, au fond du couloir de gauche, derrière un pilier, avec deux gardes.",
		["The digsite and the outer cave"] = "Le site de fouilles et la grotte extérieure",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "Les deux premières cages se trouvent ensemble dans le village de Fanécorce au sud de {npc:5634} ; la troisième est dans le village suivant, à l'est. Chaque troll Witherbark peut lâcher un collier.",
		["The {object:32377}: the Platinum Discs reward"] = "{object:32377} : la récompense des disques de platine",
		["Thelsamar flight master"] = "Maître de vol de Thelsamar",
		["Theramore"] = "Theramore",
		["Theramore flight master"] = "Maître de vol de Theramore",
		["To the Scarlet Monastery"] = "Au Monastère Écarlate",
		["Uldaman"] = "Uldaman",
		["Uldaman (dungeon, optional): {npc:2817}"] = "Uldaman (donjon, facultatif) : {npc:2817}",
		["Uldaman: a 5-player dungeon at the north end of the {zone:1418}, levels 42 to 52 on Forever: best at 43 or more. The {zone:1418} quests come first, then the dungeon, then the rewards in {zone:1455} on the way to Southshore. Alone? Skip it: the guide goes on in the {zone:1418}."] = "Uldaman : un donjon 5 joueurs au nord des {zone:1418}, niveaux 42 à 52 sur Forever : optimal à 43 ou plus. D'abord les quêtes des {zone:1418}, puis le donjon, puis les récompenses à {zone:1455} sur la route d'Austrivage. Seul ? Passez : le guide continue dans les {zone:1418}.",
		["Uldaman: {npc:2909}"] = "Uldaman : {npc:2909}",
		["Valley of Fangs"] = "Vallée des Crocs",
		["Warlock: {quest:3631}"] = "Démoniste : {quest:3631}",
		["Witherbark villages"] = "Villages de Fanécorce",
		["for {npc:4454} in the {object:151976}: the {zone:1446} guide crosses them at 45, keep it"] = "pour {npc:4454} dans les {object:151976} : le guide de {zone:1446} les traverse au niveau 45, conservez-le",
		["{item:273169}, red book on a table in Doan's room"] = "{item:273169}, livre rouge sur une table dans la salle de Doan",
		["{item:4635}: {npc:2932}, elite 38"] = "{item:4635} : {npc:2932}, élite 38",
		["{item:7666}, a drop: for {npc:6826} in {zone:1455}"] = "{item:7666}, un butin : pour {npc:6826} à {zone:1455}",
		["{item:8009}: Shadowforge dwarves"] = "{item:8009} : nains Ombreforge",
		["{item:8027}, from his chest"] = "{item:8027}, dans son coffre",
		["{item:8052}: Shadowforge dwarves"] = "{item:8052} : nains Ombreforge",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616} se tient sur les quais où accoste le bateau.",
		["{npc:264265}: {quest:96800}, {npc:6487}'s book"] = "{npc:264265} : {quest:96800}, livre de {npc:6487}",
		["{npc:2817}'s next quest pays no experience: skip it."] = "La quête suivante de {npc:2817} ne rapporte pas d'expérience : passez-la.",
		["{npc:2817}, Valley of Fangs"] = "{npc:2817}, Vallée des Crocs",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "La tâche suivante de {npc:2888} est une chasse élite : passez-la.",
		["{npc:2909} waits just outside Uldaman, west of the cave. His amulet is on {npc:2932}, a Shadowforge dwarf (elite 38) outside the dungeon portal, south of {npc:2909}."] = "{npc:2909} attend juste devant Uldaman, à l'ouest de la grotte. Son amulette est sur {npc:2932}, un nain Ombreforge (élite 38) devant le portail du donjon, au sud de {npc:2909}.",
		["{npc:3974}, elite 34"] = "{npc:3974}, élite 34",
		["{npc:3975} spins with Whirlwind: everyone but the tank steps away until it ends. When he dies, a wave of trainees runs in: fight them at the door."] = "{npc:3975} tourbillonne avec Tourbillon : tout le monde sauf le tank s'éloigne jusqu'à la fin. À sa mort, une vague de recrues arrive : combattez-les à la porte.",
		["{npc:3975}, elite 40"] = "{npc:3975}, élite 40",
		["{npc:3976}, elite 42"] = "{npc:3976}, élite 42",
		["{npc:3977}, elite 42"] = "{npc:3977}, élite 42",
		["{npc:3980}, upstairs"] = "{npc:3980}, à l'étage",
		["{npc:3980}, upstairs in the inn"] = "{npc:3980}, à l'étage dans l'auberge",
		["{npc:3980}, upstairs in the inn: four Scarlet bosses"] = "{npc:3980}, à l'étage à l'auberge : quatre boss écarlates",
		["{npc:4944}, on the top floor"] = "{npc:4944}, au dernier étage",
		["{npc:4968}, on the top floor"] = "{npc:4968}, au dernier étage",
		["{npc:5387} hands a voucher for the {object:131474}: {npc:7292} pays it in the {object:32377}."] = "{npc:5387} remet un bon pour {object:131474} : {npc:7292} le paie dans {object:32377}.",
		["{npc:5634} camps on the road east of Aerie Peak."] = "{npc:5634} campe sur la route à l'est de Nid-de-l'Aigle.",
		["{npc:5636}, beside the flight master at the top; inside"] = "{npc:5636}, à côté du maître de vol au sommet ; à l'intérieur",
		["{npc:6487}, elite 37"] = "{npc:6487}, élite 37",
		["{npc:6826}: his follow-ups need another Uldaman run, not in this guide"] = "{npc:6826} : ses suites nécessitent un autre passage à Uldaman, pas dans ce guide",
		["{npc:6906} and the hidden chamber"] = "{npc:6906} et la chambre cachée",
		["{npc:6906}, Eric and Olaf wait in the first halls, at the top of a ramp. The chest beside {npc:6906} holds the {item:7740}, Revelosh drops the Shaft of Tsol: together they make the {item:7733}. Plant it in the Map Room, kill Ironaya (elite), then walk all the way into the chamber."] = "{npc:6906}, Eric et Olaf attendent dans les premiers couloirs, en haut d'une rampe. Le coffre près de {npc:6906} contient le {item:7740}, Revelosh lâche la hampe : ensemble ils forment le {item:7733}. Le planter dans la Salle des Cartes, tuer Ironaya (élite), puis avancer jusqu'au fond de la chambre.",
		["{npc:7292}, in the Vault"] = "{npc:7292}, dans la Chambre forte",
		["{npc:7744}, below ground: bind your hearthstone here"] = "{npc:7744}, sous terre : liez votre pierre de foyer ici",
		["{npc:7884} keeps paying for necklaces: hand in any extras"] = "{npc:7884} paie toujours les colliers : rendez ceux en trop",
		["{npc:7884}, inside"] = "{npc:7884}, à l'intérieur",
		["{object:171531}: {npc:3974} and {npc:6487}"] = "{object:171531} : {npc:3974} et {npc:6487}",
		["{object:32356}: {npc:2916} and {npc:2918}"] = "{object:32356} : {npc:2916} et {npc:2918}",
		["{quest:1050} goes back to Mae Paledust in {zone:1455}: the {zone:1425} guide (Group 22) passes there."] = "{quest:1050} retourne à Mae Paledust à {zone:1455} : le guide {zone:1425} (Groupe 22) y passe.",
		["{quest:1050}, on the floor of the Library"] = "{quest:1050}, au sol de la Bibliothèque",
		["{quest:1450}, inside"] = "{quest:1450}, à l'intérieur",
		["{zone:1455} flight master"] = "Maître de vol de {zone:1455}",
		["{zone:1455} rewards"] = "Récompenses à {zone:1455}",
} end)()
t.guides["groupe-alliance/22-feralas"] = (function() return {
		["Back to the Ruins of Solarsal. Every Hatecrest naga there can drop scales."] = "Retour aux ruines de Solarsal. Chaque naga Hatecrest sur place peut laisser des écailles.",
		["Boat to The Forgotten Coast"] = "Bateau pour la Côte oubliée",
		["Boat to the Forgotten Coast and ride east across {zone:1444} to the Grimtotem camp north of the road. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "Prenez le bateau pour la Côte oubliée et traversez les {zone:1444} vers l'est jusqu'au camp du Totem sinistre au nord de la route. {npc:7956} attend à l'extérieur ; libérez les fées fléchetteuses de l'enclos au centre et gardez {npc:7956} et au moins six d'entre elles en vie.",
		["Boat to the Forgotten Coast and ride east into Feral Scar Vale. {npc:14637}'s quests on the coast need level 45."] = "Prenez le bateau pour la Côte oubliée et allez vers l'est dans le Val des Griffes farouches. Les quêtes de {npc:14637} sur la côte nécessitent le niveau 45.",
		["Boat to {object:152576}"] = "Bateau pour {object:152576}",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Feathermoon flight master"] = "Maître de vol de Plumelune",
		["Feral Scar Vale"] = "Val des Griffes farouches",
		["Fly to Thalanaar"] = "Envolez-vous pour Thalanaar",
		["Gordunni ogres"] = "Les ogres Gordunni",
		["Grimtotem camp"] = "Le camp Totem sinistre",
		["Grimtotem tauren"] = "Taurens Totem sinistre",
		["Grind to 45"] = "Farmer jusqu'au niveau 45",
		["Group 20 · {zone:1444}"] = "Groupe 20 · {zone:1444}",
		["Hatecrest naga"] = "Nagas Hainecrête",
		["In the quest log before going in: {quest:3636} ({npc:1284}, {zone:1453}, Group 18). {npc:12866}'s quest is taken here; {npc:8516}'s two inside. Keep 3 free quest log slots."] = "Dans le journal avant d'entrer : {quest:3636} ({npc:1284}, {zone:1453}, Groupe 18). La quête de {npc:12866} se prend ici ; les deux de {npc:8516} à l'intérieur. Garder 3 places libres dans le journal.",
		["Into {zone:1413}"] = "Dans les {zone:1413}",
		["Isle of Dread"] = "Île de l'effroi",
		["Protect him at the idol"] = "Le protéger à l'idole",
		["Rage Scar Hold"] = "Repaire des Griffes féroces",
		["Razorfen Downs (dungeon, optional)"] = "Souilles de Tranchebauge (donjon, facultatif)",
		["Razorfen Downs: a 5-player dungeon at the southern edge of the {zone:1413}, levels 35 to 41, east of the road down to the {object:19844}. At 43 or so it goes fast. {npc:12866} waits on a hill outside it. Alone? Skip it: the guide goes on to {zone:1444}."] = "Souilles de Tranchebauge : un donjon pour 5 joueurs au sud de {zone:1413}, niveaux 35 à 41, à l'est de la route qui descend vers {object:19844}. Vers 43, il va vite. {npc:12866} attend sur une colline devant. Seul ? Le passer : le guide continue vers {zone:1444}.",
		["Razorfen Downs: outside the portal"] = "Souilles de Tranchebauge : devant le portail",
		["Razorfen Downs: {npc:7358}"] = "Souilles de Tranchebauge : {npc:7358}",
		["Razorfen Downs: {npc:8516}"] = "Souilles de Tranchebauge : {npc:8516}",
		["Ride back to the Forgotten Coast; the goblin stands by the dock."] = "Retournez à la Côte oubliée ; le gobelin se tient près du quai.",
		["Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide; one may drop a {quest:7735}, which {npc:7852} pays for too."] = "Revenez vers l'ouest par la route, puis montez au nord dans les collines du Repaire des Griffes féroces. Tout yéti ici peut laisser tomber une peau ; l'un d'eux peut donner une {quest:7735}, que {npc:7852} McGrubben paie aussi.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "Chevauchez vers l'est jusqu'au camp Gordunni dans les collines au sud-est de la vallée des yétis : des Démonistes Gordunni et des Chamans Gordunni tiennent le camp, des Brutes Gordunni errent sur les pentes alentour et plus au nord.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "Chevauchez vers le nord dans la vallée des yétis. Tout Yéti Griffe farouche peut laisser tomber une peau épaisse ; {npc:5346} (niveau 48) rôde au milieu.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "Chevauchez au nord-est jusqu'à l'avant-poste elfe de la nuit à la frontière de {zone:1441}.",
		["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to Thalanaar. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "Allez au sud-est vers les gnolls Woodpaw ; les sacs du courrier se trouvent dans leur camp sud, et un colis à l'intérieur lance une livraison vers Thalanaar. La ruche Zukk'ash est juste au sud : frayez un chemin jusqu'à la cosse qui retient Raschal, libérez-le et gardez-le en vie sur le chemin du retour.",
		["Ruins of Solarsal"] = "Ruines de Solarsal",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "Des Marcheurs des rivages, des Marcheurs des profondeurs et des Marcheurs des vagues (géants élites) arpentent la côte au nord du quai : frappez-en un avec l'{item:18904} et tuez le géant rétréci. Des Elémentaires marins et des Embruns dérivent dans les mêmes vagues.",
		["Take the boat to the Forgotten Coast and follow the shore south to the wrecked row boat on the beach."] = "Prenez le bateau pour la Côte oubliée et suivez le rivage vers le sud jusqu'au canot détruit sur la plage.",
		["Thalanaar"] = "Thalanaar",
		["Thalanaar flight master"] = "Maître de vol de Thalanaar",
		["The Forgotten Coast: kill these as you meet them"] = "La Côte oubliée : tuez-les au fur et à mesure",
		["The Isle of Dread is the island just south of Sardor Isle: swim over. Hatecrest Serpent Guards and Sorceresses hold it; {npc:8136} (level 47) waits in the cave at its south end. Pull his guards first."] = "L'Île de l'effroi est l'île juste au sud de l'île de Sardor : rejoignez-la à la nage. Des gardes-serpents et des ensorceleuses Hainecrête l'occupent ; {npc:8136} (niveau 47) attend dans la grotte à son extrémité sud. Attirez d'abord ses gardes.",
		["The courier's boat"] = "Le bateau du messager",
		["The last boss (elite 41), at the far end."] = "Le dernier boss (élite 41), tout au fond.",
		["The three targets of {quest:6626} live outside the portal, among the barrows and thorns (elites, 33)."] = "Les trois cibles de {quest:6626} sont devant le portail, parmi les tertres et les ronces (élites, 33).",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "Marchez vers le sud sur l'île jusqu'aux ruines nagas ; le belvédère se trouve parmi elles.",
		["You end at the Forgotten Coast dock: the {zone:1446} guide starts with the trip east from here."] = "Vous terminez au quai de la Côte oubliée : le guide de {zone:1446} commence par le trajet vers l'est depuis ici.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "pour Tyrande Whisperwind à {zone:1457} : l'itinéraire vous y mène au niveau 47",
		["grind on {npc:5292} at Feral Scar Vale, {zone:1444}"] = "Farmez {npc:5292} au Val des Griffes farouches, {zone:1444}",
		["{item:11463}, from the backpacks"] = "{item:11463}, dans les sacs à dos",
		["{item:9248}; below ground"] = "{item:9248} ; sous terre",
		["{npc:12866}, on a hill outside"] = "{npc:12866}, sur une colline devant le donjon",
		["{npc:14637}'s refills are level 55: skip them."] = "Les recharges de {npc:14637} Fandazzle sont de niveau 55 : passez-les.",
		["{npc:3936} then asks you to carry news to {zone:1457}: skip it, Gadgetzan sends you there instead."] = "{npc:3936} vous demande ensuite d'apporter des nouvelles à {zone:1457} : ignorez, Gadgetzan vous y enverra à la place.",
		["{npc:3936}, beside him"] = "{npc:3936}, à côté de lui",
		["{npc:4048} walks around Thalanaar: look inside the circle on the map"] = "{npc:4048} se promène autour de Thalanaar : regardez à l'intérieur du cercle sur la carte",
		["{npc:7764}: his answer waits in Rut'theran Village, later"] = "{npc:7764} : sa réponse attend à Rut'theran Village, plus tard",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, au sommet du bastion",
		["{npc:7879}, upstairs"] = "{npc:7879}, à l'étage",
		["{npc:7880} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:7880} se tient à l'étage dans son bâtiment : montez à l'intérieur, la flèche ne distingue pas les étages.",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136} attend la fin de la boucle sur le continent.",
		["{npc:8516} waits in a prison cell inside. His quests cannot be shared: every player takes {quest:3523} and hands it in to him (he wants his Oathstone back) BEFORE anyone starts {quest:3525}. Then he walks to the idol and casts while waves of enemies come: stay close and keep them off him; it ends at his brazier."] = "{npc:8516} attend dans une cellule à l'intérieur. Ses quêtes ne se partagent pas : chaque joueur prend {quest:3523} et la lui rend (il veut récupérer sa pierre de serment) AVANT que quiconque lance {quest:3525}. Il marche alors jusqu'à l'idole et incante pendant que des vagues d'ennemis arrivent : rester près de lui et les tenir loin ; cela finit à son brasero.",
		["{object:152576} stands on Sardor Isle, off the Forgotten Coast: the boat from the coast's dock crosses to it. {npc:7880} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{object:152576} se trouve sur l'île de Sardor, au large de la Côte oubliée : le bateau depuis le quai de la côte y mène. {npc:7880} se tient à l'étage dans son bâtiment : montez à l'intérieur, la flèche ne distingue pas les étages.",
		["{object:152577}: kill these as you meet them"] = "{object:152577} : tuez-les au fur et à mesure",
		["{object:164954}, inside"] = "{object:164954}, à l'intérieur",
} end)()
t.guides["groupe-alliance/23-tanaris"] = (function() return {
		["Boat to {object:1162}"] = "Bateau pour {object:1162}",
		["Careful: Thieves cast Disarm. Rogues stay hidden with Sneak. Assassins use Execute when your health is at 20% or lower."] = "Attention : les Larrons lancent Désarmement. Les Voleurs restent cachés grâce à Camouflage. Les Assassins utilisent Exécution quand votre vie est à 20 % ou moins.",
		["Dunemaul Compound"] = "Base des Cognedunes",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Fly to Aerie Peak"] = "Envolez-vous vers Nid-de-l'Aigle",
		["Fly to Theramore"] = "Volez jusqu'à Theramore",
		["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp.\nCareful: Two or three pirates stand with {npc:7883}, and many more pirates from the town join the fight once it starts."] = "Suivez la côte vers le sud jusqu'à la crique des pirates. Les pirates des Mers du Sud envahissent la plage et les bateaux : progressez par le bord et attirez-les un par un. {npc:7883} se tient de l'autre côté ; la cargaison volée de {npc:7881} se trouve dans le camp.\nAttention : deux ou trois pirates se tiennent avec {npc:7883}, et beaucoup d'autres pirates de la ville se joignent au combat dès qu'il commence.",
		["Gadgetzan"] = "Gadgetzan",
		["Gadgetzan flight master"] = "Maître de vol de Gadgetzan",
		["Gadgetzan: Zul'Farrak rewards"] = "Gadgetzan : récompenses de Zul'Farrak",
		["Gives the {item:8585}"] = "Donne le {item:8585}",
		["Group 21 · {zone:1446}"] = "Groupe 21 · {zone:1446}",
		["Group of 5: share each quest (quest log, Share) before going in. {npc:7267}, the last boss, waits behind the door Weegli blows open after the pyramid event."] = "Groupe de 5 : partagez chaque quête (journal de quêtes, Partager) avant d'entrer. {npc:7267}, le dernier boss, attend derrière la porte que Weegli fait sauter après l'événement de la pyramide.",
		["He runs off to keep Rizzle busy"] = "Il s'éloigne pour occuper Rizzle Brassbolts",
		["Keep 3 free quest log slots. {npc:7876}, {npc:7804} and {npc:7407} are all in Gadgetzan."] = "Gardez 3 emplacements libres dans le journal de quêtes. {npc:7876}, {npc:7804} et {npc:7407} sont tous à Gadgetzan.",
		["Lost Rigger Cove: kill these as you meet them"] = "Crique des Gréements : tuez-les au fur et à mesure",
		["Mirage Raceway"] = "Piste des mirages",
		["Noonshade Ruins"] = "Ruines d'Ombre-du-Zénith",
		["Noonshade Ruins: kill these as you meet them"] = "Ruines d'Ombre-du-Zénith : tuez-les au fur et à mesure",
		["Pool by Sandsorrow Watch"] = "Bassin près du Guet de Tristesable",
		["Ride back west to Gadgetzan."] = "Retournez à l'ouest jusqu'à Gadgetzan.",
		["Ride back west toward Gadgetzan. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch.\nCareful: Wastewander Rogues (level 43-44) move stealthed, so they can approach unseen."] = "Revenez vers l'ouest en direction de Gadgetzan. Les bandits et larrons Bat-le-désert tiennent les dunes sur le chemin ; chacun peut porter une outre.\nAttention : les voleurs Bat-le-désert (niveau 43-44) se déplacent camouflés, ils peuvent donc approcher sans être vus.",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "Chevauchez vers l'est à travers les dunes jusqu'au Port Gentepression sur la côte nord-est.",
		["Ride north-west from Gadgetzan to the walled city, at the edge of the dunes. Inside, every troll can drop {quest:3042}; the scarabs by the graveyard of {npc:7272} drop the shells.\nThe pyramid event: free {npc:7604} and his crew from the cage at the top of the stairs, then hold the stairs against the troll waves. Once the trolls are dead, Bly turns on you: he drops the {quest:2768}."] = "Partez vers le nord-ouest depuis Gadgetzan jusqu'à la cité fortifiée, au bord des dunes. À l'intérieur, chaque troll peut laisser tomber {quest:3042} ; les scarabées près du cimetière de {npc:7272} laissent tomber les carapaces.\nL'événement de la pyramide : libérez {npc:7604} et son équipe de la cage en haut des marches, puis tenez les marches contre les vagues de trolls. Une fois les trolls morts, Bly se retourne contre vous : il laisse tomber {quest:2768}.",
		["Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you."] = "Chevauchez vers le nord-ouest jusqu'à la ruche Centipaar dans les dunes. N'importe quel Centipaar peut lâcher des morceaux d'insecte.\nAttention : les Traînards Centipaar lancent {npc:4196} en combat comme hors combat, ce qui fait venir de petits renforts qui vous interrompent.",
		["Ride north-west to the Sandfury troll camp at Sandsorrow Watch. Use the {item:8584} at the edge of its pool; the trolls stand close, so pull the nearest first."] = "Allez au nord-ouest jusqu'au camp de trolls Sandfury au Guet de Tristesable. Utilisez {item:8584} au bord de son bassin ; les trolls sont proches, attirez d'abord le plus proche.",
		["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time.\nCareful: The other thistleshrub mobs in the area are level 49-50 and wander a lot, so you can easily pull extra mobs."] = "Chevauchez vers le sud jusqu'à {quest:3362}. Les Chardonniers collecteurs de rosée lâchent les glandes ; seules certaines sont remplies, gardez donc celles-là. Les Chardonniers noueux et les Chardonniers taille-racines partagent la vallée. Les Chardonniers noueux sont de niveau 48-50, au-dessus du vôtre : attirez-les un par un.\nAttention : les autres chardonniers du secteur sont de niveau 49-50 et errent beaucoup : vous pouvez facilement en attirer d'autres.",
		["Ride south past the Broken Pillar to the Gaping Chasm, the Hazzali tunnels; Scrimshank's gear lies deep inside.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "Allez au sud en passant le Pilier brisé jusqu'au Gouffre béant, les tunnels Hazzali ; l'équipement de Scrimshank se trouve au fond.\nAttention : un insecte garde l'équipement. De nombreux insectes patrouillent dans les tunnels, certains de niveau 50, donc les combats attirent souvent des monstres supplémentaires.",
		["Ride south to the dig camp at the Broken Pillar. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "Allez au sud jusqu'au camp de fouilles du Pilier brisé. {npc:7771} vous remet un casque détecteur : équipez-le pour voir les monticules {quest:3161}, qui parsèment le sable autour du camp et au sud-ouest en direction des ogres.",
		["Ride south-east off the {object:151976} into {zone:1446}. Gadgetzan is just inside the border."] = "Prenez la route au sud-est depuis {object:151976} vers {zone:1446}. Gadgetzan se trouve juste à la frontière.",
		["Ride south-east to Waterspring Field. {npc:7847} stands in the middle of the southern Wastewander camp: clear around him first.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them."] = "Allez au sud-est jusqu'au Champ des puisatiers. {npc:7847} se tient au milieu du camp Bat-le-désert du sud : nettoyez les alentours d'abord.\nAttention : deux voleurs Bat-le-désert camouflés l'accompagnent où qu'il aille. À son camp de réapparition, deux mages de l'ombre et leurs serviteurs sont assez proches pour rejoindre le combat contre lui. Près des tours, vous pouvez le combattre sans eux.",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "Chevauchez au sud-ouest jusqu'à la Base des Cognedunes. Des Brutes Cognedune et des Massacreurs Cognedune (46-48) la remplissent ; {npc:12046} (49) se tient au centre entouré de gardes : éliminez-les d'abord.",
		["The Broken Pillar"] = "Le Pilier Brisé",
		["The Gaping Chasm"] = "Le Gouffre béant",
		["The Mirage Raceway lies on the {object:151976} in south-east {zone:1441}. {npc:4454} and {npc:4630} are in the camps beside the track.\n{npc:4709} stands by the goblin camp.\nWhile {npc:4709} keeps Rizzle talking, his plans lie unguarded in the gnome camp across the track."] = "La Piste des mirages se trouve sur les {object:151976} au sud-est des {zone:1441}. {npc:4454} et {npc:4630} sont dans les camps près de la piste.\n{npc:4709} se tient près du camp gobelin.\nPendant que {npc:4709} occupe Rizzle, ses plans sont sans surveillance dans le camp gnome de l'autre côté de la piste.",
		["The Noxious Lair"] = "Le Repaire nuisible",
		["The Wanted poster beside him"] = "L'affiche Avis de recherche à côté de lui",
		["The little turtle {npc:5955} hides at the north end of the valley. Lead him home to his wife {npc:6015}, by the water just east of {object:151975}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "La petite tortue {npc:5955} se cache à l'extrémité nord de la vallée. Ramenez-le chez sa femme {npc:6015}, au bord de l'eau juste à l'est de {object:151975} : il marche lentement et les bêtes du désert l'attaquent, alors gardez-le en vie.",
		["The pool by Sandsorrow Watch"] = "Le bassin près du Guet de Tristesable",
		["The same poster: {npc:7847} comes much later, after Gadgetzan"] = "La même affiche : {npc:7847} arrive bien plus tard, après Gadgetzan",
		["The tougher Wastewander rogues, shadow mages and assassins camp south-east of Gadgetzan, south of the bandits. Leave {npc:7847} in the middle of the southern camp for later.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp."] = "Les voleurs, mages de l'ombre et assassins Bat-le-désert plus coriaces campent au sud-est de Gadgetzan, au sud des bandits. Laissez {npc:7847} au milieu du camp sud pour plus tard.\nAttention : les voleurs Bat-le-désert gardent Camouflage actif hors combat, donc des voleurs cachés peuvent se joindre à un combat que vous lancez dans un camp.",
		["Underwater"] = "Sous l'eau",
		["Waterspring Field"] = "Champ des puisatiers",
		["Zul'Farrak"] = "Zul'Farrak",
		["Zul'Farrak (dungeon, optional): Gadgetzan"] = "Zul'Farrak (donjon, facultatif) : Gadgetzan",
		["Zul'Farrak: a troll city in the north-west of {zone:1446}, levels 44 to 54, best at 45 or more with a full group. Three quests from Gadgetzan, all done inside. Alone? Skip it: the guide flies on to Theramore."] = "Zul'Farrak : une cité troll au nord-ouest de {zone:1446}, niveaux 44 à 54, idéale à partir du niveau 45 en groupe complet. Trois quêtes à prendre à Gadgetzan, toutes faites à l'intérieur. Seul ? Passez-la : le guide s'envole ensuite vers Theramore.",
		["for {zone:1457}: the route takes you there at 47"] = "pour {zone:1457} : l'itinéraire vous y mène au niveau 47",
		["grind on {npc:5474}"] = "tuez en boucle : {npc:5474}",
		["{item:8593}; below ground"] = "{item:8593} ; sous terre",
		["{npc:11758}, on the east side of town"] = "{npc:11758}, à l'est de la ville",
		["{npc:12046}, below ground"] = "{npc:12046}, sous terre",
		["{npc:4630}: only after {quest:1137}"] = "{npc:4630} : seulement après {quest:1137}",
		["{npc:5594}, inside"] = "{npc:5594}, à l'intérieur",
		["{npc:5955}'s escort"] = "L'escorte de {npc:5955}",
		["{npc:7407}, by the water tower"] = "{npc:7407}, près du château d'eau",
		["{npc:7408}, next to him"] = "{npc:7408}, à côté de lui",
		["{npc:7583}'s next ingredient grows in the {zone:1425}, and the route never brings it back: skip it."] = "L'ingrédient suivant de {npc:7583} pousse dans les {zone:1425}, et la route ne le ramène jamais : ignorez-le.",
		["{npc:7763}: his crate goes to Rut'theran Village, later"] = "{npc:7763} : sa caisse va à Rut'theran Village, plus tard",
		["{npc:7881}'s next delivery goes back to {object:3204}: skip it."] = "La prochaine livraison de {npc:7881} retourne à {object:3204} : ignorez-la.",
		["{npc:7881}, in the port's tavern; inside"] = "{npc:7881}, dans la taverne du port ; à l'intérieur",
		["{npc:7881}, inside"] = "{npc:7881}, à l'intérieur",
		["{npc:7882}, inside"] = "{npc:7882}, à l'intérieur",
		["{object:1162} flight master"] = "Maître de vol de {object:1162}",
		["{object:20805}, inside"] = "{object:20805}, à l'intérieur",
		["{quest:2864}, north side of town"] = "{quest:2864}, au nord de la ville",
		["{quest:2873}; upstairs"] = "{quest:2873} ; à l'étage",
		["{quest:3362}: kill these as you meet them"] = "{quest:3362} : tuez-les au passage",
} end)()
t.guides["groupe-alliance/24-hinterlands"] = (function() return {
		["Aerie Peak"] = "Nid-de-l'Aigle",
		["Aerie Peak flight master"] = "Maître de vol de Nid-de-l'Aigle",
		["Boat to Stormwind Harbor"] = "Bateau pour le port de Hurlevent",
		["Cathedral of Light: {npc:1284}"] = "Cathédrale de la Lumière : {npc:1284}",
		["Cenarion Enclave"] = "Enclave cénarienne",
		["Class trainer"] = "Maître de classe",
		["Craftsmen's Terrace"] = "Terrasse des Artisans",
		["Darkshire"] = "Sombre-Comté",
		["Darkshire flight master"] = "Maître de vol de Sombre-Comté",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Fly to Auberdine"] = "Envolez-vous pour Auberdine",
		["Fly to Lakeshire"] = "Envolez-vous vers Comté-du-Lac",
		["Fly to Thelsamar"] = "Volez vers Thelsamar",
		["Fly to {object:1162}"] = "Envolez-vous vers {object:1162}",
		["Fly to {object:3204}"] = "Envolez-vous pour {object:3204}",
		["Fly to {zone:1455}"] = "Envolez-vous vers {zone:1455}",
		["Group 22 · {zone:1425}, {zone:1419} & {zone:1432}"] = "Groupe 22 · {zone:1425}, {zone:1419} et {zone:1432}",
		["In the {object:32356}, by the bookshelves."] = "Dans le {object:32356}, près des étagères.",
		["Inside"] = "À l'intérieur",
		["Into {zone:1418}"] = "Dans {zone:1418}",
		["Into {zone:1432}"] = "Dans les {zone:1432}",
		["Ironband's Excavation Site"] = "Excavations de Baguefer",
		["Morgan's Vigil flight master"] = "Maître de vol de la Veille de Morgan",
		["Nethergarde Keep"] = "Rempart-du-Néant",
		["Nethergarde Keep flight master"] = "Maître de vol de Rempart-du-Néant",
		["Portal to {zone:1438}"] = "Portail vers {zone:1438}",
		["Ride back north to Ironband's camp."] = "Revenez vers le nord jusqu'aux Excavations de Baguefer.",
		["Ride east along the south shore of the loch to Ironband's camp."] = "Chevauchez vers l'est le long de la rive sud du Loch jusqu'aux Excavations de Baguefer.",
		["Ride north to Skulk Rock in the middle of the {zone:1425}. Green Sludges and Jade Oozes crawl all around it.\nCareful: Panthers move around the area in stealth."] = "Allez au nord jusqu'au Rocher de l'Affût au milieu des {zone:1425}. Des limaces vertes et des limons de jade rampent tout autour.\nAttention : des panthères se déplacent camouflées dans la zone.",
		["Ride on east along the road to the keep first: the {item:6091} expires an hour after Darkshire, and the bloodmages' beasts take longer than that."] = "Continuez vers l'est le long de la route jusqu'au donjon d'abord : le {item:6091} expire une heure après Sombre-Comté, et les bêtes des mages de sang mettent plus de temps que cela.",
		["Ride south through the pass into the {zone:1418}' northern edge: the Stonevault troggs dig outside Uldaman there. The carved urns and the magenta mushroom clusters sit in their caves and tunnels, outside the dungeon itself."] = "Allez au sud à travers le col jusqu'au bord nord des {zone:1418} : les troggs de Coffrepierre fouillent à l'extérieur d'Uldaman. Les urnes sculptées et les grappes de champignons magenta se trouvent dans leurs grottes et tunnels, à l'extérieur du donjon lui-même.",
		["Ride south-east to the Altar of Zul, the stepped Vilebranch temple in the south of the {zone:1425}, and climb to the top. Qiaga and {npc:8636} (elite, 50) stand up there: touch the top and come straight back down.\nCareful: Elite trolls guard the top platform, including {npc:7996} and {npc:8636}, along with several Vilebranch Soothsayers. The soothsayers cast spells and are linked to the rest of the group."] = "Allez au sud-est jusqu'à l'Autel de Zul, le temple à degrés des Vilebranche au sud des {zone:1425}, et grimpez au sommet. Qiaga et {npc:8636} (élite, 50) s'y tiennent : touchez le sommet et redescendez directement.\nAttention : Des trolls élites gardent la plateforme supérieure, dont {npc:7996} et {npc:8636}, ainsi que plusieurs Devin Vilebranche. Les devins lancent des sorts et sont liés au reste du groupe.",
		["Ride west: Starving Snickerfangs roam the dry hills just south of the bloodmages' camp; Scorpok Stingers (level 50) scuttle across the middle of the north. {npc:5982} vultures circle over all of it. Pull one at a time.\nAshmane Boars and Redstone Basilisks share the slopes south-west of the keep. Keep clear of the Helboars further south: they are level 52.\nCareful: Scorpok Stingers use Venom Sting; {npc:8301} adds Knockdown."] = "Allez à l'ouest : des raillecrocs affamées rôdent sur les collines sèches juste au sud du camp des mages de sang ; des aiguillonneurs scorpok (niveau 50) traversent le milieu du nord. Des vautours {npc:5982} tournent au-dessus de tout cela. Attirez-en un à la fois.\nDes sangliers cendrés et des basilics Rougepierre partagent les pentes au sud-ouest du donjon. Éloignez-vous des sangliers infernaux plus au sud : ils sont de niveau 52.\nAttention : les aiguillonneurs scorpok utilisent Piqûre venimeuse ; {npc:8301} ajoute Renversement.",
		["Rut'theran Village"] = "Village de Rut'theran",
		["Rut'theran Village flight master"] = "Maître de vol du village de Rut'theran",
		["Skulk Rock"] = "Rocher de l'Affût",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "Franchissez le portail vers {zone:1457}. Le Temple de la Lune se trouve au sud de la cité.",
		["Sunken Temple (dungeon, optional): {npc:5384}"] = "Temple englouti (donjon, facultatif) : {npc:5384}",
		["Temple of the Moon"] = "Temple de la Lune",
		["The Sunken Temple: a troll and dragon dungeon under the Pool of Tears in the {zone:1435}, best at 50 to 55 with a group of 5. This guide runs it later, from the {zone:1419} (Group 25). Alone? Skip it."] = "Le Temple englouti : un donjon de trolls et de dragons sous le Bassin des larmes, dans le {zone:1435}, idéal de 50 à 55 à 5 joueurs. Le guide le fait plus tard, depuis les {zone:1419} (Groupe 25). Seul ? La passer.",
		["The Uldaman dig"] = "La fouille d'Uldaman",
		["The bloodmages"] = "Les mages de sang",
		["The bloodmages' camp is the first stop beside the road into the {zone:1419}, north-west of Nethergarde Keep."] = "Le camp des mages de sang est le premier arrêt au bord de la route menant aux {zone:1419}, au nord-ouest de Rempart-du-Néant.",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "Le second palier des mages de sang paie les mêmes morceaux avec un objet d'amélioration et sans expérience : passez-le.",
		["Thelsamar"] = "Thelsamar",
		["Thelsamar flight master"] = "Maître de vol de Thelsamar",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:1494} (level 52 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:1494} (élite de niveau 52) demande un groupe de 2. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:8552} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {quest:8552} demande un groupe de 2. Passez-la si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["Tram to {zone:1453}"] = "Tram pour {zone:1453}",
		["for {quest:2990} at Nethergarde Keep, later"] = "pour {quest:2990} à Rempart-du-Néant, plus tard",
		["the book on her table"] = "le livre sur sa table",
		["the soil comes from {zone:1449}, later"] = "la terre vient du {zone:1449}, plus tard",
		["{item:8047}; below ground"] = "{item:8047} ; sous terre",
		["{npc:1470}, below ground"] = "{npc:1470}, sous terre",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}, au sommet de l'arbre",
		["{npc:5385}, upstairs"] = "{npc:5385}, à l'étage",
		["{npc:5636}, inside"] = "{npc:5636}, à l'intérieur",
		["{npc:7740}, beside her"] = "{npc:7740}, à côté d'elle",
		["{npc:7907} stands upstairs, above {npc:7916}: go up inside, the arrow cannot tell the floors apart."] = "{npc:7907} se tient à l'étage, au-dessus de {npc:7916} : montez à l'intérieur, la flèche ne distingue pas les étages.",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "La course suivante de {npc:7907} Lightwind mène en {zone:1446} : passez-la.",
		["{npc:7916}: keep it, the feathers come at the end of the {zone:1428} guide"] = "{npc:7916} : gardez-la, les plumes viennent à la fin du guide des {zone:1428}",
		["{npc:8022}' next task, {item:9471}, is a Zul'Farrak quest: skip it."] = "La prochaine tâche de {npc:8022}, {item:9471}, est une quête de Zul'Farrak : ignorez-la.",
		["{object:2743}; below ground"] = "{object:2743} ; sous terre",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}, au sommet du donjon",
		["{quest:3636}, from Razorfen Downs: {npc:1284} is in the Cathedral of Light."] = "{quest:3636}, des Souilles de Tranchebauge : {npc:1284} est dans la cathédrale de la Lumière.",
		["{zone:1419}: kill these as you meet them"] = "{zone:1419} : tuez-les au fur et à mesure que vous les rencontrez",
} end)()
t.guides["groupe-alliance/25-gorge-des-vents-brulants"] = (function() return {
		["Below ground"] = "Sous terre",
		["Camp Cagg"] = "Camp Cagg",
		["Class trainer"] = "Maître de classe",
		["Dustfire Valley"] = "Vallée des Escarbilles",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Firewatch Ridge: kill these as you meet them"] = "Crête de Guet-du-feu : tuez-les au fur et à mesure",
		["Fly to {zone:1455}"] = "Envolez-vous vers {zone:1455}",
		["For {npc:8256} in {zone:1455}, later"] = "Pour {npc:8256} à {zone:1455}, plus tard",
		["From Thelsamar ride south into the {zone:1418}, then west past the Horde town of Kargath (give it room) and up the trail into {zone:1427}. Thorium Point is the scaffolded camp on the north-west rim."] = "Depuis Thelsamar, chevauchez vers le sud dans {zone:1418}, puis vers l'ouest en passant par la ville horde de Kargath (gardez vos distances) et empruntez le sentier menant à {zone:1427}. La Halte du Thorium est le camp échafaudé sur le bord nord-ouest.",
		["Group 23 · {zone:1427}"] = "Groupe 23 · {zone:1427}",
		["If you skipped The {item:3985} or Facing Negolash, grind here to level 48.27 to stay on the route's plan."] = "Si vous avez passé {item:3985} ou Face à Negolash, tuez des monstres ici jusqu'au niveau 48.27 pour suivre le plan de l'itinéraire.",
		["If you skipped {quest:3452}, grind here to level 48.98 to stay on the route's plan."] = "Si vous avez passé {quest:3452}, tuez des monstres ici jusqu'au niveau 48.98 pour suivre le plan de l'itinéraire.",
		["If you skipped {quest:7701}, grind here to level 48.66 to stay on the route's plan."] = "Si vous avez passé {quest:7701}, tuez des monstres ici jusqu'au niveau 48.66 pour suivre le plan de l'itinéraire.",
		["Into {zone:1427}"] = "Dans les {zone:1427}",
		["Kalaran stands on the rim of the Cauldron, south of Thorium Point. Listen to his story."] = "Velarok se tient sur le bord du Chaudron, au sud de la Halte du Thorium. Écoutez son histoire.",
		["Level 48.27"] = "Niveau 48.27",
		["Level 48.66"] = "Niveau 48.66",
		["Level 48.98"] = "Niveau 48.98",
		["On the way"] = "En chemin",
		["Ride east across the Cauldron to the Grimesilt Dig Site in the south-east. The prisoner in the wooden outhouse wants 15 {item:4306} and eight dead Dark Iron Geologists from the dig site around it. The outhouse also opens with the key, if you found one.\nThe dwarf stands by the road at the dig site. When it is over, read the {object:175704} he leaves on the road in Dustfire Valley."] = "Traversez le Chaudron vers l'est jusqu'au Site de fouilles de Crasseboue au sud-est. Le prisonnier dans les latrines en bois veut 15 {item:4306} et huit géologues Sombrefer morts du site de fouilles alentour. Les latrines s'ouvrent aussi avec la clé, si vous en avez trouvé une.\nLe nain se tient près de la route au site de fouilles. Une fois terminé, lisez le {object:175704} qu'il laisse sur la route dans la Vallée des Escarbilles.",
		["Stoutlager Inn"] = "Auberge de la Fortebière",
		["The Grimesilt outhouse"] = "Les toilettes de Crasseboue",
		["The Slag Pit opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of {npc:14621} and his elite guards deep inside."] = "La Fosse aux scories s'ouvre au nord du Chaudron. Les plans secrets gisent sur sa corniche supérieure ; des incendosaures nagent dans les mares de lave plus loin, attirez-les vers le bord. Évitez {npc:14621} et ses gardes d'élite au fond.",
		["The night elf stands alone west of Thorium Point. Hear his story."] = "L'elfe de la nuit se tient seul à l'ouest de la Halte du Thorium. Écoutez son histoire.",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "La tâche suivante du prisonnier, Grand livre de {zone:1446}, vous envoie au {zone:1435} et au {zone:1445} : passez-la.",
		["The spiders roam the plateaus and lava pools in the south-west of the gorge.\nHeavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts.\nTaskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee."] = "Les araignées parcourent les plateaux et les mares de lave au sud-ouest de la gorge.\nDes Golems de guerre lourds patrouillent au fond du Chaudron, sous Kalaran ; des Élémentaires de magma dérivent parmi eux. Golems et élémentaires lâchent l'huile, les élémentaires les cœurs.\nLes Sous-chefs et les Esclavagistes mènent les esclaves dans tout le Chaudron, et n'importe lequel peut porter une {item:10551}. Les Forge-vapeur travaillent aux fourneaux du centre (la {item:18959}), les Guetteurs se tiennent sur les crêtes du sud (la longue-vue). N'importe quel {object:147516} peut lâcher la {item:11818} : gardez-la.\nAttention : les Esclavagistes Sombrefer (niveau 45-46) appellent à l'aide les alliés dans un rayon de 15 m quand vous les attirez, lancent Filet jusqu'à 15 m et utilisent Pourfendre au corps à corps.",
		["The {object:179827} board"] = "Le panneau {object:179827}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:14621} is a level 50 elite: most classes solo it at level 52, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:14621} est un élite de niveau 50 : la plupart des classes le battent seules au niveau 52, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:5860} (level 50 elite) needs a group of 3. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:5860} (élite de niveau 50) demande un groupe de 3. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:3181} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {quest:3181} demande un groupe de 2. Passez-la si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["Thorium Point"] = "Halte du Thorium",
		["Thorium Point flight master"] = "Maître de vol de la Halte du Thorium",
		["To Stoutlager Inn"] = "Vers l'Auberge de la Fortebière",
		["Use your hearthstone: it is bound at the Stoutlager Inn, Thelsamar ({zone:1425} guide). On cooldown? Fly from {object:3204} to Thelsamar."] = "Utilisez votre pierre de foyer : elle est liée à l'auberge de la Fortebière, à Thelsamar (guide des {zone:1425}). En recharge ? Prenez le griffon de {object:3204} à Thelsamar.",
		["grind on {npc:5839}"] = "tuez en boucle : {npc:5839}",
		["grind on {npc:5844}"] = "tuez en boucle : {npc:5844}",
		["grind on {npc:9318}"] = "tuez en boucle : {npc:9318}",
		["{item:10551} on the way"] = "{item:10551} en chemin",
		["{item:18922}; below ground"] = "{item:18922} ; sous terre",
		["{npc:5844} along the way to Thorium Point"] = "{npc:5844} sur le chemin vers la Halte du Thorium",
		["{npc:5846} along the way to Thorium Point"] = "{npc:5846} sur le chemin vers la Halte du Thorium",
		["{npc:5858} on the way"] = "{npc:5858} en chemin",
		["{npc:9318} along the way to Thorium Point"] = "{npc:9318} sur le chemin vers la Halte du Thorium",
		["{npc:9318} on the way"] = "{npc:9318} en chemin",
		["{object:147516} dwarves"] = "Nains {object:147516}",
		["{zone:1427}: kill these as you meet them"] = "{zone:1427} : tuez-les au fur et à mesure",
} end)()
t.guides["groupe-alliance/26-un-goro"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "Archesonus se tient à côté du roi Magni dans {object:171709}.",
		["Auberdine flight master"] = "Maître de vol d'Auberdine",
		["Below ground"] = "Sous terre",
		["Bind and train"] = "Lier la pierre de foyer et s'entraîner",
		["Bones and equipment"] = "Os et équipement",
		["Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from Diemetradons. The expedition's {item:11112} lies in the south-west jungle."] = "Les Os de dinosaure jonchent le sol au sud-ouest, parmi les stégodons : ceux-ci sont élites, ramassez les os autour d'eux et prenez le reste sur les Dimeurtrodons. L'{item:11112} de l'expédition se trouve dans la jungle sud-ouest.",
		["Eastern Pylon"] = "Le Pylône est",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Se termine auprès de {npc:9298} au {zone:1452} : gardez-la",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Fire Plume Ridge and the eastern jungle"] = "Crête de la Fournaise et la jungle est",
		["Fly to Astranaar"] = "Envolez-vous vers Astranaar",
		["Fly to Gadgetzan"] = "Envolez-vous pour Gadgetzan",
		["Fly to {object:1162}"] = "Envolez-vous vers {object:1162}",
		["Fly to {zone:1455}"] = "Envolez-vous vers {zone:1455}",
		["For {npc:7775} in {zone:1444}: keep it"] = "Pour {npc:7775} en {zone:1444} : gardez-la",
		["Four rune rubbings in {zone:1447}: keep it"] = "Quatre estampes de runes en {zone:1447} : gardez-la",
		["Gadgetzan"] = "Gadgetzan",
		["Group 24 · {zone:1449}"] = "Groupe 24 · {zone:1449}",
		["Lakkari Tar Pits"] = "Fosses de goudron de Lakkari",
		["Lar'korwi Mates and the raft"] = "Compagnes de Lar'korwi et le radeau",
		["Level 49.51"] = "Niveau 49.51",
		["Level 50.4"] = "Niveau 50.4",
		["Marshal's Refuge"] = "Refuge des Marshal",
		["Northern Pylon"] = "Le Pylône nord",
		["Pterrordax"] = "Pterreurdactyles",
		["Ride north along the western jungle back to the refuge."] = "Remontez vers le nord par la jungle ouest jusqu'au refuge.",
		["Ride north to Ironstone Plateau, where the robot stands among the gorillas. Stay out of the deep cave there."] = "Allez au nord jusqu'au Plateau de Rochefer, où le robot se tient parmi les gorilles. N'entrez pas dans la grotte profonde là-bas.",
		["Ride south down the east side. Young Diemetradons graze the eastern jungle and {npc:9165} fly near the eastern cliffs; both drop {npc:9998}'s scales."] = "Descendez vers le sud par le côté est. Les Jeunes dimeurtrodons paissent dans la jungle est et les {npc:9165} volent près des falaises est ; les deux laissent tomber les écailles de {npc:9998}.",
		["Ride south to Fire Plume Ridge in the middle of the crater, then east into the eastern jungle. Crystal clusters stand all over the crater, many of them around Fire Plume Ridge: take a few extra of each colour. Bloodpetal Lashers and Threshers drop the petals; the expedition's {item:11113} sits at an abandoned camp in the eastern jungle."] = "Allez au sud jusqu'à la Crête de la Fournaise au centre du cratère, puis à l'est dans la jungle est. Des grappes de cristal parsèment le cratère, beaucoup autour de la Crête de la Fournaise : prenez-en quelques-unes de plus de chaque couleur. Les flagellants et batteurs Pétale-de-sang laissent tomber les pétales ; le {item:11113} de l'expédition se trouve dans un camp abandonné dans la jungle est.",
		["Ride west back to the refuge.\nGive the elite devilsaurs and stegodons a wide berth. Pick up every Power Crystal and {object:157936} you pass from here on."] = "Retournez vers l'ouest jusqu'au refuge.\nGardez vos distances avec les diablosaures et les stégodons élites. Ramassez désormais chaque Cristal de puissance et chaque {object:157936} que vous croisez.",
		["Ride west from {npc:9619}: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop {quest:3764}; Pterrordax nest on the southern cliffs if you still need kills.\nCareful: Gorishi silithids are level 51-54 and cast Silithid Pox or Tunneler Acid in melee; Gorishi Workers have a 50% chance to call for help within 25 yd once they fall below 45% health."] = "Allez à l'ouest depuis {npc:9619} : la ruche silithide remplit le sud du cratère. Utilisez la fiole de grattage sur une nurserie, une chambre avec des larves suspendues. Les guêpes et ouvriers Gorishi donnent {quest:3764} ; des pterreurdactyles nichent sur les falaises sud si vous avez encore des monstres à tuer.\nAttention : les silithides Gorishi sont de niveau 51-54 et lancent Variole silithide ou Acide de foreuse au corps à corps ; les ouvriers Gorishi ont 50 % de chances d'appeler à l'aide dans un rayon de 25 m une fois sous 45 % de vie.",
		["Ride west out of Gadgetzan to the long ramp down into {zone:1449}. {npc:9619} camps at the foot of the ramp, in the south-east corner of the crater."] = "Sortez de Gadgetzan vers l'ouest jusqu'à la longue rampe descendant dans {zone:1449}. {npc:9619} campe au pied de la rampe, dans le coin sud-est du cratère.",
		["Stoutlager Inn"] = "Auberge de la Fortebière",
		["The Gorishi hive"] = "La ruche Gorishi",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "Les compagnes de Lar'korwi rôdent dans la jungle à l'ouest de {npc:9619}. L'épave du radeau gît sur la rive du lac là-bas ; le petit paquet repose dans l'eau à côté. Gardez la boussole, la carte et la clé pour {npc:8737}. Toute bête du cratère peut laisser tomber {item:11116} : faites un clic droit dessus.",
		["The Marshlands"] = "La Fondrière",
		["The Slithering Scar"] = "La Balafre sinueuse",
		["The dead Threshadon lies by the water north of {npc:9619}."] = "Le battrodon mort se trouve au bord de l'eau au nord de {npc:9619}.",
		["The flight from Theramore lands in Gadgetzan."] = "Le vol depuis Theramore atterrit à Gadgetzan.",
		["The pylon stands on the eastern cliffs."] = "Le pylône se dresse sur les falaises est.",
		["The pylon stands on the slope east of the refuge. Pterrordax circle the slopes around it: they count for Spraggle and drop {npc:9998}'s scales."] = "Le pylône se dresse sur la pente à l'est du refuge. Des Pterreurdactyles tournoient sur les pentes alentour : ils comptent pour Spraggle et lâchent les écailles de {npc:9998}.",
		["The pylon stands on the western cliffs. {npc:9167} fly over the whole west side."] = "Le pylône se dresse sur les falaises ouest. Les {npc:9167} volent au-dessus de tout le côté ouest.",
		["The relics are in the {zone:1428}: keep it"] = "Les reliques sont dans {zone:1428} : gardez-la",
		["Thelsamar flight master"] = "Maître de vol de Thelsamar",
		["Theramore flight master"] = "Maître de vol de Theramore",
		["To Stoutlager Inn"] = "Vers l'Auberge de la Fortebière",
		["Top up here to level 49.51 before the hand-ins at Marshal's Refuge: they take you to level 50."] = "Montez ici jusqu'au niveau 49,51 avant de rendre les quêtes au Refuge des Marshal : elles vous feront atteindre le niveau 50.",
		["Top up here to level 50.4 before the hand-ins at Talrendis Point: they take you to level 51."] = "Montez ici jusqu'au niveau 50,4 avant de rendre les quêtes à la Halte de Talrendis : elles vous feront atteindre le niveau 51.",
		["Use your hearthstone: it is bound at the Stoutlager Inn, Thelsamar. On cooldown? Fly to Theramore, take the boat to {object:1162}, then fly to Thelsamar."] = "Utilisez votre pierre de foyer : elle est liée à l'auberge de la Fortebière, à Thelsamar. En recharge ? Griffon jusqu'à Theramore, bateau pour {object:1162}, puis griffon pour Thelsamar.",
		["Western Pylon"] = "Le Pylône ouest",
		["Xiggs waits in the {object:32359}."] = "Xiggs attend dans {object:32359}.",
		["grind on Pterrordax"] = "tuez des Pterreurdactyles en boucle",
		["grind on {npc:6116}"] = "tuez en boucle : {npc:6116}",
		["grind on {npc:9164}"] = "tuez en boucle : {npc:9164}",
		["grind on {npc:9167}"] = "tuez en boucle : {npc:9167}",
		["{item:11834} from {npc:6518} and {npc:6519}, 60 yd south"] = "{item:11834} auprès de {npc:6518} et {npc:6519}, 60 yd au sud",
		["{npc:11406}: for Ogtinc in {zone:1447}, keep it"] = "{npc:11406} : pour Ogtinc en {zone:1447}, gardez-la",
		["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117}, au fond de la grotte ; sous terre",
		["{npc:9117}, below ground"] = "{npc:9117}, sous terre",
		["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616} : les limons sont en {zone:1448}, gardez-la",
		["{npc:9618} stands just outside the refuge."] = "{npc:9618} se tient juste devant le refuge.",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, à l'entrée du refuge",
		["{npc:9998}, at the refuge's entrance"] = "{npc:9998}, à l'entrée du refuge",
		["{object:161504}, underwater"] = "{object:161504}, sous l'eau",
		["{zone:1449}: kill these as you meet them"] = "{zone:1449} : tuez-les au fur et à mesure",
		["{zone:1455} flight master"] = "Maître de vol de {zone:1455}",
} end)()
t.guides["groupe-alliance/27-steppes-ardentes"] = (function() return {
		["Aerie Peak flight master"] = "Maître de vol de Nid-de-l'Aigle",
		["Auberdine flight master"] = "Maître de vol d'Auberdine",
		["Back to {zone:1438}"] = "Retour vers {zone:1438}",
		["Below ground"] = "Sous terre",
		["Blackrock Stronghold"] = "Bastion Rochenoire",
		["Climb to the top of Dreadmaul Rock and plant the head in the soft dirt mound."] = "Grimpez au sommet du Rocher des Cognepeurs et plantez la tête dans le monticule de terre meuble.",
		["Dreadmaul Rock"] = "Rocher des Cognepeurs",
		["Druid training"] = "Entraînement de druide",
		["Ends with {quest:4808} in Everlook, {zone:1452}: keep it"] = "Se termine par {quest:4808} à Long-Guet, {zone:1452} : gardez-la",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Flame Crest"] = "Corniche des flammes",
		["Fly to Aerie Peak"] = "Envolez-vous vers Nid-de-l'Aigle",
		["Fly to Morgan's Vigil"] = "Voler jusqu'à la Veille de Morgan",
		["Fly to Nethergarde Keep"] = "Voler jusqu'au Rempart-du-Néant",
		["Fly to Rut'theran Village"] = "Envolez-vous vers le village de Rut'theran",
		["Fly to Southshore"] = "Envolez-vous pour Austrivage",
		["Fly to {zone:1455}"] = "Envolez-vous vers {zone:1455}",
		["Follow the road west, then climb north to the goblin camp on Flame Crest."] = "Suivez la route vers l'ouest, puis montez vers le nord jusqu'au camp gobelin de la Corniche des flammes.",
		["Group 25 · {zone:1428} & {zone:1447}"] = "Groupe 25 · {zone:1428} & {zone:1447}",
		["Group of 5, levels 50 to 55. Keep 3 free quest log slots. Share each quest with your group: click it in the quest log, then Share."] = "Groupe de 5, niveaux 50 à 55. Garder 3 places libres dans le journal de quêtes. Partagez chaque quête au groupe : clic sur la quête dans le journal, puis Partager.",
		["If you skipped {quest:4022}, grind here to level 52.08 to stay on the route's plan."] = "Si vous avez passé {quest:4022}, tuez des monstres ici jusqu'au niveau 52.08 pour suivre le plan de l'itinéraire.",
		["Level 50.89"] = "Niveau 50.89",
		["Level 51.39"] = "Niveau 51.39",
		["Level 52"] = "Niveau 52",
		["Level 52.08"] = "Niveau 52.08",
		["Morgan's Vigil"] = "Veille de Morgan",
		["Morgan's Vigil flight master"] = "Maître de vol de la Veille de Morgan",
		["Morgan's Vigil sits in the south-east of the Steppes, at the top of the pass up from Redridge."] = "La Veille de Morgan se trouve au sud-est des Steppes ardentes, en haut du col qui monte depuis les Carmines.",
		["Mosshoof Coursers"] = "Coursiers Sabots-de-mousse",
		["Optional: {npc:8395} wants two Undamaged Hippogryph Feathers from the hippogryphs around his camp. The data lists no experience for it."] = "Facultatif : {npc:8395} veut deux Plumes d'hippogryphe sans défaut des hippogryphes autour de son camp. Les données n'indiquent aucune expérience pour cette quête.",
		["Ravencrest Monument"] = "Colosse de Ravencrest",
		["Ride back east along the road to the Vigil."] = "Revenez vers l'est par la route jusqu'à la Veille.",
		["Ride north out of the {zone:1419} into the {zone:1435}, then east past Stonard (Horde) to the Pool of Tears. The temple lies under the water: swim down into it and find the dungeon's entrance inside."] = "Sortir des {zone:1419} par le nord vers le {zone:1435}, puis aller à l'est après Pierrêche (Horde) jusqu'au Bassin des larmes. Le temple est sous l'eau : plonger, entrer et trouver l'entrée du donjon à l'intérieur.",
		["Ride north-east from the shrine: {npc:8405} camps at the Bear's Head, in the hills above the road."] = "Partez vers le nord-est depuis le sanctuaire : {npc:8405} campe à Tête d'ours, dans les collines au-dessus de la route.",
		["Ruins of Thaurissan: kill these as you meet them"] = "Ruines de Thaurissan : tuez-les au fur et à mesure",
		["Rut'theran Village"] = "Village de Rut'theran",
		["Shadowsong Shrine"] = "Sanctuaire de Shadowsong",
		["Stoutlager Inn"] = "Auberge de la Fortebière",
		["Sunken Temple"] = "Temple englouti",
		["Sunken Temple (dungeon, optional): the Pool of Tears"] = "Temple englouti (donjon, facultatif) : le Bassin des larmes",
		["Sunken Temple: the tablets and Jammal'an"] = "Temple englouti : les tablettes et Jammal'an",
		["Sunken Temple: the {npc:5709}"] = "Temple englouti : {npc:5709}",
		["Swim to the small island off the southern tip of {zone:1447}: {npc:8392} waits by the monument."] = "Nagez jusqu'au petit îlot au large de la pointe sud de {zone:1447} : {npc:8392} attend près du monument.",
		["Take the Deeprun Tram from {zone:1455} to {zone:1453} and back: {npc:5384} waits in the {object:28027}."] = "Prendre le Tram des profondeurs de {zone:1455} à {zone:1453}, aller et retour : {npc:5384} attend dans le {object:28027}.",
		["The Atal'ai Tablets lie in the temple's halls: pick them up as you clear. {npc:5710} drops his head for the {npc:5598}'s quest ({zone:1425}, west of the Altar of Zul): not on this route, take it there on your own if you pass by."] = "Les tablettes atal'ai sont posées dans les salles du temple : les ramasser en avançant. {npc:5710} donne sa tête pour la quête de l'{npc:5598} ({zone:1425}, à l'ouest de l'autel de Zul) : pas sur ce trajet, la prendre de votre côté si vous passez par là.",
		["The Firegut ogres hold the great rock north of the Vigil, with the Brutes on its east side."] = "Les ogres Brûlentrailles tiennent le grand rocher au nord de la Veille, avec les Brutes sur son flanc est.",
		["The Highborne ghosts haunt the ruins around the shrine; the Haldarr satyrs hold the camp just north of it."] = "Les fantômes bien-nés hantent les ruines autour du sanctuaire ; les satyres Haldarr tiennent le Campement des Haldarr juste au nord.",
		["The Ruins of Eldarath"] = "Ruines d'Eldarath",
		["The Shattered Strand"] = "La Grève fracassée",
		["The Spitelash naga of the Ruins of Eldarath carry {item:13815}. {npc:8507}'s four runes stand among the ruins: use his {item:10445} on each."] = "Les nagas Fouette-bile des Ruines d'Eldarath portent {item:13815}. Les quatre runes de {npc:8507} se dressent parmi les ruines : utilisez son {item:10445} sur chacune.",
		["The Wildkin Feathers lie on the ground across the {zone:1425}, south and east of Aerie Peak, where the owlbeasts roam; the mobs here are well below you now."] = "Les plumes d'Indomptable jonchent le sol dans {zone:1425}, au sud et à l'est du Nid-de-l'Aigle, là où rôdent les chouettards ; les monstres du coin sont désormais bien en dessous de votre niveau.",
		["The nearest Mosshoof Coursers graze the hills north-east of the Bear's Head, toward the Legashi Encampment; a larger herd roams the open ground to the south."] = "Les coursiers Sabots-de-mousse les plus proches paissent dans les collines au nord-est de Tête d'ours, vers le Campement Legashi ; un troupeau plus grand parcourt la plaine au sud.",
		["The relics are the carved stones scattered through the Ruins of Thaurissan around Flame Crest: click them until the information is recovered.\nRead the tablet in the {object:147516} camp among the ruins, south-west of Flame Crest, to copy the transcript.\nUse the {item:12284} on a {npc:7047} on the slopes east of Flame Crest just before it dies, then loot the essence it leaves."] = "Les reliques sont les pierres gravées éparpillées dans les Ruines de Thaurissan autour de la Corniche des flammes : cliquez dessus jusqu'à récupérer les informations.\nLisez la tablette dans le camp {object:147516} parmi les ruines, au sud-ouest de la Corniche des flammes, pour en copier la transcription.\nUtilisez {item:12284} sur un {npc:7047} sur les pentes à l'est de la Corniche des flammes juste avant qu'il meure, puis ramassez l'essence qu'il laisse.",
		["The shrine lies in the south-west corner of {zone:1447}, south of Talrendis Point."] = "Le sanctuaire se trouve dans le coin sud-ouest de {zone:1447}, au sud de la Halte de Talrendis.",
		["The wildkin are in {zone:1452}: keep it"] = "Les Indomptables sont au {zone:1452} : gardez-la",
		["The {npc:5709} waits at the very end, past the green dragons. He drops the {item:10454}: right-click it, then hand it in at the {object:148512} in his room before you leave."] = "{npc:5709} attend tout au fond, après les dragons verts, et laisse l'{item:10454} : clic droit dessus, puis la rendre au {object:148512}, dans la même salle, avant de partir.",
		["Thelsamar flight master"] = "Maître de vol de Thelsamar",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} (level 48 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:7977} (élite de niveau 48) demande un groupe de 2. Passez-la si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:9461} is a level 54 elite: most classes solo it at level 56, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:9461} est un élite de niveau 54 : la plupart des classes le battent seules au niveau 56, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["To Stoutlager Inn"] = "Vers l'Auberge de la Fortebière",
		["Top up here to level 50.89 before the hand-ins at {zone:1426}: they take you to level 51."] = "Complétez ici jusqu'au niveau 50.89 avant les rendus de quêtes à {zone:1426} : ils vous font passer au niveau 51.",
		["Top up here to level 51.39 before the hand-ins at Flame Crest: they take you to level 52."] = "Montez ici jusqu'au niveau 51.39 avant les rendus de la Corniche des flammes : ils vous amènent au niveau 52.",
		["Top up here to level 52 before the hand-ins at Flame Crest: they take you to level 53."] = "Montez ici jusqu'au niveau 52 avant les rendus de la Corniche des flammes : ils vous amènent au niveau 53.",
		["Use your hearthstone (Stoutlager Inn, Thelsamar) if it is ready again. On cooldown? Fly from Nethergarde Keep to Thelsamar."] = "Utilisez votre pierre de foyer (auberge de la Fortebière, Thelsamar) si elle est de nouveau prête. En recharge ? Prenez le griffon du Rempart-du-Néant à Thelsamar.",
		["Use your hearthstone: it is bound at the Stoutlager Inn, Thelsamar. On cooldown? Fly from Talrendis Point to Auberdine, take the boat to {object:1162}, then fly to Thelsamar."] = "Utilisez votre pierre de foyer : elle est liée à l'auberge de la Fortebière, à Thelsamar. En recharge ? Griffon de la Halte de Talrendis à Auberdine, bateau pour {object:1162}, puis griffon pour Thelsamar.",
		["Wildkin feathers"] = "Plumes d'Indomptable",
		["grind on {npc:6196}"] = "tuez en boucle : {npc:6196}",
		["grind on {npc:6375}"] = "tuez en boucle : {npc:6375}",
		["grind on {npc:7034}"] = "tuez en boucle : {npc:7034}",
		["grind on {npc:9690}"] = "tuez en boucle : {npc:9690}",
		["{item:10454}, a drop"] = "{item:10454}, un butin",
		["{item:11467} on the way"] = "{item:11467} en chemin",
		["{item:11467}; inside"] = "{item:11467} ; à l'intérieur",
		["{item:7972}: the {npc:7864}, about 10%"] = "{item:7972} : les {npc:7864}, environ 10 %",
		["{npc:7034}, below ground"] = "{npc:7034}, sous terre",
		["{npc:7363} waits at the Rise of the Defiler, the hill south-west of the keep. The {zone:1419} mobs on the way drop the Imperfect Draenethyst Fragments; bring her what you have.\nCareful: Felcular, {npc:7664} and Ilifar are all level 60 elites. Razelikh casts Mana Burn, Strong Cleave and Decimate, and as its health drops it adds {object:141891}, Flames of Chaos and then Enrage at 15%."] = "{npc:7363} attend à la Cime du Souilleur, la colline au sud-ouest du rempart. Les monstres de {zone:1419} en chemin laissent tomber les fragments de draenéthyste imparfaits ; apportez-lui ce que vous avez.\nAttention : Gangrénaire, {npc:7664} et Ilifar sont tous des élites de niveau 60. Razelikh lance Brûlure de mana, Strong Cleave et Decimate, et à mesure que sa vie baisse il ajoute {object:141891}, Flames of Chaos, puis s'enrage à 15 %.",
		["{npc:7363} walks around here: look inside the circle on the map"] = "{npc:7363} se promène par ici : cherchez dans le cercle sur la carte",
		["{npc:7907} stands upstairs, above {npc:7916}: go up inside, the arrow cannot tell the floors apart."] = "{npc:7907} se tient à l'étage, au-dessus de {npc:7916} : montez à l'intérieur, la flèche ne distingue pas les étages.",
		["{npc:8420} camps at the Legashi Encampment in the north; his equipment lies all over the Thalassian Base Camp just south-east of him."] = "{npc:8420} campe au Campement Legashi, au nord ; son équipement est éparpillé dans tout le Camp de base thalassien, juste au sud-est.",
		["{npc:9176} and the Blackrock orcs hold the camps and the stronghold at the foot of Blackrock Mountain, west of Flame Crest. Pull them one at a time; every orc and worg may drop a medallion, so kill them until you have fifty.\nCareful: {npc:9176} has a guard linked to him that joins the fight, and a second soldier patrols close by; clear the patrol before pulling."] = "{npc:9176} et les orcs Rochenoire tiennent les camps et le bastion au pied du Mont Rochenoire, à l'ouest de la Corniche des flammes. Attirez-les un par un ; chaque orc et chaque worg peut laisser tomber un médaillon, tuez-les jusqu'à en avoir cinquante.\nAttention : {npc:9176} a un garde lié qui rejoint le combat, et un second soldat patrouille tout près ; éliminez la patrouille avant d'attirer.",
		["{npc:9177}: the Blackrock orcs drop the medallions, keep it open all through the Steppes"] = "{npc:9177} : les orcs Blackrock laissent tomber les médaillons, gardez-la ouverte dans toutes les Steppes",
		["{object:153556} on the way"] = "{object:153556} en chemin",
		["{zone:1447}: kill these as you meet them"] = "{zone:1447} : tuez-les au fur et à mesure",
		["{zone:1455} flight master"] = "Maître de vol de {zone:1455}",
		["{zone:1455} has no druid trainer: take the portal up to {zone:1457} and train in the Cenarion Enclave, then come back down to Rut'theran Village."] = "{zone:1455} n'a pas de maître des druides : prenez le portail vers {zone:1457}, entraînez-vous dans l'Enclave cénarienne, puis redescendez à Rut'theran.",
} end)()
t.guides["groupe-alliance/28-gangrebois"] = (function() return {
		["Below ground"] = "Sous terre",
		["Deadwood Village"] = "Village des Mort-bois",
		["Ends in the {zone:1413}: keep it"] = "Se termine dans {zone:1413} : gardez-la",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Felpaw Village"] = "Village de Gangrepatte",
		["First crater"] = "Premier cratère",
		["Five feathers buy a little Timbermaw reputation"] = "Cinq plumes rapportent un peu de réputation Grumegueule",
		["Fly to Astranaar"] = "Envolez-vous vers Astranaar",
		["Follow the road north to the cave mouth of Timbermaw Hold; {npc:15395} guards it."] = "Suivez la route vers le nord jusqu'à l'entrée de la grotte du Repaire des Grumegueules ; {npc:15395} la garde.",
		["Follow the road north to the cratered vale and walk to each crater, killing the Entropic Beasts and Horrors between them."] = "Suivez la route vers le nord jusqu'au val criblé de cratères et rendez-vous à chaque cratère, en tuant les Bêtes d'entropie et les Horreurs entre eux.",
		["Group 26 · {zone:1448}"] = "Groupe 26 · {zone:1448}",
		["If you skipped The Horn of the Beast or The {item:9328}, grind here to level 52.58 to stay on the route's plan."] = "Si vous avez passé La corne de la bête ou {item:9328}, tuez des monstres ici jusqu'au niveau 52.58 pour suivre le plan de l'itinéraire.",
		["Irontree Woods"] = "Bois d'Arbrefer",
		["Jadefire Glen"] = "Vallon des Jadefeu",
		["Jadefire Run is the satyr valley in the north-west, with {npc:10648} at its far end. He drops the {quest:939}; every Jadefire satyr can drop {item:11674}."] = "Le Défilé des Jadefeu est la vallée des satyres au nord-ouest, avec {npc:10648} tout au fond. Il laisse tomber {quest:939} ; chaque satyre Jadefeu peut laisser tomber {item:11674}.",
		["Jadefire Run: kill these as you meet them"] = "Défilé des Jadefeu : tuez-les au fur et à mesure",
		["Jaedenar"] = "Jaedenar",
		["Jaedenar again"] = "Retour à Jaedenar",
		["Jaedenar is the ruined temple north of the glen. Some of its cultists drop a {item:13140}, about one kill in thirty: it opens {npc:11018}'s cell in Shadow Hold, the cave at the back. If it drops, clear the way out before you free her; if not, skip her quests."] = "Jaedenar est le temple en ruine au nord du vallon. Certains de ses cultistes laissent tomber {item:13140}, environ une fois sur trente : il ouvre la cellule de {npc:11018} dans le Fort des ombres, la grotte du fond. S'il tombe, dégagez la sortie avant de la libérer ; sinon, passez ses quêtes.",
		["Keep her alive until she is out of the cave"] = "Gardez-la en vie jusqu'à sa sortie de la grotte",
		["Level 52.58"] = "Niveau 52.58",
		["Level 52.69"] = "Niveau 52.69",
		["Level 52.9"] = "Niveau 52.9",
		["Oozes"] = "Limons",
		["Ride north out of Astranaar into {zone:1448}. {npc:11554} the furbolg stands by the road just south of the Emerald Sanctuary."] = "Partez vers le nord depuis Astranaar pour entrer dans {zone:1448}. {npc:11554} le furbolg se tient au bord de la route, juste au sud du Sanctuaire d'émeraude.",
		["Ride south-east from Jaedenar to the Emerald Sanctuary, the druids' camp by the road in southern {zone:1448}."] = "Partez vers le sud-est depuis Jaedenar jusqu'au Sanctuaire d'émeraude, le camp des druides au bord de la route, dans le sud de {zone:1448}.",
		["Ruins of Constellas"] = "Ruines de Constellas",
		["Rut'theran Village flight master"] = "Maître de vol du village de Rut'theran",
		["Salfa stands at the {zone:1452} end of the tunnel: keep it"] = "Salfa se tient à l'extrémité du tunnel côté {zone:1452} : gardez-la",
		["Second crater"] = "Deuxième cratère",
		["Shatter Scar Vale"] = "Val Grêlé",
		["Step into the cave: {npc:11558} and {npc:11557} stand just inside."] = "Entrez dans la grotte : {npc:11558} et {npc:11557} se tiennent juste à l'intérieur.",
		["The Cursed and Tainted Oozes slide about the streams and fel pools around Jaedenar and Bloodvenom Falls: kill them and use Laris's Empty Ooze Jars on their remains."] = "Les limons maudits et les limons corrompus glissent le long des ruisseaux et des bassins gangrenés autour de Jaedenar et des Chutes de la Vénéneuse : tuez-les et utilisez les pots vides de Laris sur leurs restes.",
		["The Deadwood furbolgs live in the village just south-west of {npc:11554}; keep the Deadwood Headdress Feathers they drop."] = "Les furbolgs Mort-bois vivent dans le village juste au sud-ouest de {npc:11554} ; gardez les Coiffures de plumes mort-bois qu'ils laissent tomber.",
		["The Deadwood furbolgs of Felpaw Village fill the hills west of the cave. The Avengers can drop a {quest:8470}.\nCareful: Den Watchers are level 53-54; they call nearby allies within 25 yd once below 50% health and run off for help below 15%."] = "Les furbolgs Mort-bois du Village de Gangrepatte occupent les collines à l'ouest de la grotte. Les vengeurs peuvent laisser tomber {quest:8470}.\nAttention : les protecteurs sont de niveau 53-54 ; sous 50 % de vie, ils appellent les alliés à moins de 25 mètres, et sous 15 % ils s'enfuient chercher de l'aide.",
		["The Emerald Sanctuary"] = "Sanctuaire d'émeraude",
		["The Jadefire satyrs hold the glen west of the road, with {npc:9454} at its back.\nCareful: Jadefire Shadowstalkers (level 51-52) use Sneak and Slowing Poison and are stealthed, so they often join fights uninvited."] = "Les satyres Jadefeu tiennent le vallon à l'ouest de la route, avec {npc:9454} au fond.\nAttention : les traqueurs des ombres Jadefeu (niveau 51-52) utilisent Sneak et Slowing Poison et sont camouflés, si bien qu'ils se joignent souvent aux combats sans y être invités.",
		["The Warpwood treants of Irontree Woods, east of Jadefire Run, carry the {item:11503}."] = "Les tréants Crochebois du Bois d'Arbrefer, à l'est du Défilé des Jadefeu, portent {item:11503}.",
		["The vial is filled in {zone:1457}: keep it; inside"] = "La fiole se remplit à {zone:1457} : gardez-la ; à l'intérieur",
		["Third crater"] = "Troisième cratère",
		["Timbermaw Hold"] = "Repaire des Grumegueules",
		["Top up here to level 52.69 before the hand-ins at Jaedenar: they take you to level 53."] = "Montez ici jusqu'au niveau 52.69 avant les rendus de Jaedenar : ils vous amènent au niveau 53.",
		["Top up here to level 52.9 before the hand-ins at Emerald Sanctuary: they take you to level 53."] = "Montez ici jusqu'au niveau 52.9 avant les rendus au Sanctuaire d'émeraude : ils vous amènent au niveau 53.",
		["Trey Lightforge's remains lie beside her."] = "Les restes de Trey Lightforge gisent à côté d'elle.",
		["Use the {item:12922} at the corrupted moonwell in the middle of Jaedenar. If you freed {npc:11018}, go back into Shadow Hold for the succubus {npc:9518}."] = "Utilisez {item:12922} au puits de lune corrompu au centre de Jaedenar. Si vous avez libéré {npc:11018}, retournez dans le Fort des ombres pour la succube {npc:9518}.",
		["grind on {npc:7109}"] = "tuez en boucle : {npc:7109}",
		["grind on {npc:7125}"] = "tuez en boucle : {npc:7125}",
		["grind on {npc:7153}"] = "tuez en boucle : {npc:7153}",
		["grind on {npc:7155}"] = "tuez en boucle : {npc:7155}",
		["{item:13140}, a rare drop"] = "{item:13140}, butin rare",
		["{npc:11016}, in Shadow Hold; below ground"] = "{npc:11016}, dans le Fort des ombres ; sous terre",
		["{npc:11020}, below ground"] = "{npc:11020}, sous terre",
		["{npc:11557}: thirty {quest:6031}, handed in when you pass through again at 57; below ground"] = "{npc:11557} : trente {quest:6031}, à rendre quand vous repasserez au niveau 57 ; sous terre",
		["{npc:11558}: the Timbermaw speak to you only from Neutral; walks around here: look inside the circle on the map"] = "{npc:11558} : les Grumegueules ne vous parlent qu'à partir de Neutre ; patrouille par ici : regardez dans le cercle sur la carte",
		["{npc:15395} waits at the north end of {zone:1448}"] = "{npc:15395} attend à l'extrémité nord de {zone:1448}",
		["{npc:9116}, inside"] = "{npc:9116}, à l'intérieur",
		["{npc:9518}, below ground"] = "{npc:9518}, sous terre",
		["{npc:9528}, in the ruins just east of {npc:11554}"] = "{npc:9528}, dans les ruines juste à l'est de {npc:11554}",
		["{quest:8470}, a rare drop"] = "{quest:8470}, butin rare",
} end)()
t.guides["groupe-alliance/29-berceau-de-l-hiver"] = (function() return {
		["Back to the hills: only the Ice Thistle Matriarchs and Patriarchs carry the horns. Keep killing yetis until level 54: Harlo's wildkin quests are red before that."] = "Retour aux collines : seuls les matriarches et patriarches Chardon de glace portent les cornes. Continuez à tuer des yétis jusqu'au niveau 54 : les quêtes d'Indomptables de Harlo sont rouges avant cela.",
		["Boat to {object:1162}"] = "Bateau pour {object:1162}",
		["Browman Mill: kill these as you meet them"] = "Scierie de Browman : tuez-les au fur et à mesure",
		["Careful: {npc:10411} goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min."] = "Attention : {npc:10411} devient invisible hors combat et appelle des Gargouilles Aile-de-roc dès qu'un combat commence. Il n'en existe que 3 et ils réapparaissent toutes les 15 min.",
		["Chillwind Camp"] = "Camp du Noroît",
		["Everlook"] = "Long-Guet",
		["Everlook flight master"] = "Maître de vol de Long-Guet",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Fly to Southshore"] = "Envolez-vous pour Austrivage",
		["Fly to Theramore"] = "Volez jusqu'à Theramore",
		["Follow the road east across the zone to the chapel."] = "Suivez la route vers l'est à travers la zone jusqu'à la Chapelle de l'Espoir de Lumière.",
		["Follow the road west to {npc:9298}'s camp beside the hot springs."] = "Suivez la route vers l'ouest jusqu'au camp de {npc:9298} Snowden, près des sources chaudes.",
		["Follow the southern road east into the {zone:1423}; the ruins of Darrowshire lie south of it. {npc:10926}'s ghost plays by the ruined house at the south end."] = "Suivez la route du sud vers l'est pour entrer dans {zone:1423} ; les ruines de Comté-de-Darrow se trouvent au sud. Le fantôme de {npc:10926} joue près de la maison en ruine, à l'extrémité sud.",
		["For Kernda in Timbermaw Hold: keep it"] = "Pour Kernda, au Repaire des Grumegueules : gardez-la",
		["Free Darrowshire Spirits: talk to them"] = "Libérer les esprits de Darrowshire : parlez-leur",
		["From Southshore, ride north up the road through Alterac to Chillwind Camp."] = "Depuis Austrivage, remontez la route vers le nord à travers les montagnes d'Alterac jusqu'au Camp du Noroît.",
		["Frostfire Hot Springs: kill these as you meet them"] = "Sources de Givrefeu : tuez-les au fur et à mesure",
		["Group 27 · {zone:1452} & {zone:1423}"] = "Groupe 27 · {zone:1452} & {zone:1423}",
		["Ice Thistle Hills: kill these as you meet them"] = "Collines des Chardons de glace : tuez-les au fur et à mesure",
		["Ice Thistle yetis live in the hills south of Winterfall Village, Chillwind Chimaeras in the valley toward Everlook."] = "Les yétis Chardon de glace vivent dans les collines au sud du Village Tombe-hiver, les chimères Noroît dans la vallée vers Long-Guet.",
		["Into {zone:1423}"] = "Entrer dans {zone:1423}",
		["Into {zone:1452}"] = "Entrer dans {zone:1452}",
		["Keep it: Gregan in {zone:1444} brews the elixir later"] = "Gardez-le : Gregan Brewspewer, en {zone:1444}, prépare l'élixir plus tard",
		["Level 55.05"] = "Niveau 55.05",
		["Light's Hope Chapel"] = "Chapelle de l'Espoir de Lumière",
		["On the way"] = "En chemin",
		["On {npc:10978}, by the inn"] = "Sur {npc:10978}, près de l'auberge",
		["Optional: Sunken Temple"] = "Facultatif : Temple englouti",
		["Pick up the supplies around the wagon and take {npc:10301}'s amulet back from the owlbeasts nearby."] = "Ramassez les fournitures autour du chariot et reprenez l'amulette de {npc:10301} aux chouettards voisins.",
		["Pristine Yeti Horns"] = "Cornes de yéti en parfait état",
		["Ride north-west back to the village."] = "Retournez au village au nord-ouest.",
		["Ride south-east down the valley to {npc:10301}'s damaged crate in the snow at Mazthoril, with his wrecked wagon just east of it."] = "Descendez la vallée vers le sud-est jusqu'à la caisse endommagée de {npc:10301}, dans la neige à Mazthoril, avec son chariot détruit juste à l'est.",
		["Short of level 54 after the yetis? Running the Sunken Temple (50-54) instead of grinding gets you there faster in a group. Come back to Everlook afterwards."] = "Pas encore niveau 54 après les yétis ? En groupe, faire le Temple englouti (50-54) vous y amène plus vite que de tuer des monstres en boucle. Revenez ensuite à Long-Guet.",
		["The Deadwood cauldron in {zone:1448}: keep it"] = "Le Chaudron des Mort-bois en {zone:1448} : gardez-la",
		["The Scourge around {object:176970}, west of the chapel, drop both kinds of Scourgestone; Darrowshire Spirits rise from them: talk to each one to free it."] = "Le Fléau autour de {object:176970}, à l'ouest de la chapelle, laisse tomber les deux sortes de pierres du Fléau ; des esprits de Darrowshire s'en élèvent : parlez à chacun pour le libérer.",
		["The Undercroft"] = "Le caveau de Zaeldarr",
		["The Winterfall furbolg village lies east of Everlook: Shaman (56-57), Den Watchers (55-56) and Ursa (57-58), all above you. Kill the Shaman first, they heal, and pull from the edge. {npc:10738} in the cave at the back is elite: stay out."] = "Le village des furbolgs Tombe-hiver se trouve à l'est de Long-Guet : chamans (56-57), protecteurs (55-56) et ursas (57-58), tous au-dessus de votre niveau. Tuez d'abord les chamans, ils soignent, et attirez depuis la bordure. {npc:10738}, dans la grotte du fond, est un élite : n'y allez pas.",
		["The next guide starts here and flies to Chillwind Camp."] = "Le guide suivant commence ici et s'envole vers le Camp du Noroît.",
		["The ruins lie around the frozen lake south of {object:177132}. Pick up the four relic fragments lying in the ruins and the Moontouched Feathers on the ground where the wildkin roam."] = "Les ruines entourent le lac gelé au sud de {object:177132}. Ramassez les quatre fragments de relique qui traînent dans les ruines et les plumes de Chouettard lunaire au sol, là où rôdent les Indomptables.",
		["The three pieces of the doll lie in the ruined houses of Darrowshire; picking one up can call out ghosts. Combine them into the doll."] = "Les trois morceaux de la poupée sont dans les maisons en ruine de Comté-de-Darrow ; en ramasser un peut faire surgir des fantômes. Combinez-les pour former la poupée.",
		["The western Winterfall camp sits in the hills between {npc:11556} and {npc:9298}. Any furbolg here can drop an {item:12771} (about one in ten) and, rarely, a {quest:8471}: right-click whichever drops. Keep the {quest:6031} the furbolgs drop for Meilosh."] = "Le camp Tombe-hiver de l'ouest est dans les collines entre {npc:11556} et {npc:9298} Snowden. Chaque furbolg ici peut laisser {item:12771} (environ une fois sur dix) et, rarement, {quest:8471} : faites un clic droit sur ce qui tombe. Gardez {quest:6031} laissé par les furbolgs pour Meilosh.",
		["Top up here to level 55.05 before the hand-ins at Everlook: they take you to level 56."] = "Montez ici jusqu'au niveau 55.05 avant les rendus à Long-Guet : ils vous amènent au niveau 56.",
		["Winterfall Village"] = "Village Tombe-hiver",
		["grind on {npc:11552}"] = "tuez en boucle : {npc:11552}",
		["{item:12383}, 110 yd north"] = "{item:12383}, à 110 mètres au nord",
		["{item:12771}, a rare drop"] = "{item:12771}, butin rare",
		["{item:12886}; inside"] = "{item:12886} ; à l'intérieur",
		["{item:12888}; inside"] = "{item:12888} ; à l'intérieur",
		["{item:15785}; below ground"] = "{item:15785} ; sous terre",
		["{npc:10301}'s camp"] = "Camp de {npc:10301}",
		["{npc:10301}'s supplies"] = "Fournitures de {npc:10301}",
		["{npc:10431}: keep both for the Plaguelands; inside"] = "{npc:10431} : gardez les deux pour les Maleterres ; à l'intérieur",
		["{npc:10926}'s doll"] = "Poupée de {npc:10926}",
		["{npc:10978}: {npc:7583} and {npc:10977} come later"] = "{npc:10978} : {npc:7583} et {npc:10977} viennent plus tard",
		["{npc:11038}, by the graves south of the chapel"] = "{npc:11038}, près des tombes au sud de la chapelle",
		["{npc:11038}: {npc:12250} is a level 54 elite"] = "{npc:11038} : {npc:12250} est un élite de niveau 54",
		["{npc:11118}: bind your hearthstone here"] = "{npc:11118} : liez votre pierre de foyer ici",
		["{npc:11556} guards the mouth of Timbermaw Hold, north-west of {npc:9298}."] = "{npc:11556} garde l'entrée du Repaire des Grumegueules, au nord-ouest de {npc:9298}.",
		["{npc:11616}: the termites come later, in Terrordale"] = "{npc:11616} : les termites viendront plus tard, à Val-Terreur",
		["{npc:11629}: keep it for Darrowshire; inside"] = "{npc:11629} : gardez-la pour Comté-de-Darrow ; à l'intérieur",
		["{npc:11754} walks around Everlook: look inside the circle on the map"] = "{npc:11754} se promène dans Long-Guet : cherchez dans le cercle sur la carte",
		["{npc:12250} is elite: grouping up is advised. He waits at the bottom of the Undercroft, the crypt in the south-west of the zone."] = "{npc:12250} est un élite : il est conseillé de se grouper. Il attend au fond du caveau de Zaeldarr, la crypte au sud-ouest de la zone.",
		["{npc:7440} along the way to {npc:9298}"] = "{npc:7440} sur le chemin de {npc:9298}",
		["{npc:7441} along the way to {npc:9298}"] = "{npc:7441} sur le chemin de {npc:9298}",
		["{npc:7442} along the way to {npc:9298}"] = "{npc:7442} sur le chemin de {npc:9298}",
		["{object:1162} flight master"] = "Maître de vol de {object:1162}",
		["{quest:5152}, in the {zone:1422}: keep it"] = "{quest:5152}, dans {zone:1422} : gardez-la",
		["{quest:6031}, for Meilosh later"] = "{quest:6031}, pour Meilosh plus tard",
		["{quest:8471}, a rare drop"] = "{quest:8471}, butin rare",
} end)()
t.guides["groupe-alliance/30-maleterres"] = (function() return {
		["Aerie Peak flight master"] = "Maître de vol de Nid-de-l'Aigle",
		["Andorhal"] = "Ruines d'Andorhal",
		["Auberdine flight master"] = "Maître de vol d'Auberdine",
		["Below ground"] = "Sous terre",
		["Boat to The Forgotten Coast"] = "Bateau pour la Côte oubliée",
		["Broken Pillar"] = "Pilier brisé",
		["Cenarion Hold"] = "Fort cénarien",
		["Chillwind Camp"] = "Camp du Noroît",
		["Chillwind Camp flight master"] = "Maître de vol du Camp du Noroît",
		["Climb the hill west of Hearthglen to look down on the town.\nCareful: Sentinels posted at the gate can detect stealthed players. Additional sentinels are found within the town, and an elite walks a patrol route nearby."] = "Grimpez sur la colline à l'ouest d'Âtreval pour observer la ville d'en haut.\nAttention : les sentinelles postées à la porte peuvent détecter les joueurs camouflés. D'autres sentinelles se trouvent dans la ville, et un élite suit une patrouille à proximité.",
		["Collie is up the hill behind it."] = "Collie est en haut de la colline derrière.",
		["Cross the river east to the Undercroft, the crypt in the south-west of the zone. The {object:177667} lies inside: its key is on {npc:12248} in the far north-east, done in the next guide."] = "Traversez la rivière vers l'est jusqu'au caveau de Zaeldarr, la crypte au sud-ouest de la zone. Le {object:177667} se trouve à l'intérieur : sa clé est sur {npc:12248}, tout au nord-est, ce qui se fait dans le guide suivant.",
		["Cross the river west to {npc:1855}'s hut."] = "Traversez la rivière vers l'ouest jusqu'à la cabane de {npc:1855}.",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "Traversez le sud du cratère jusqu'à {npc:9619}, près de la rampe.",
		["Dalson's Tears"] = "Larmes de Dalson",
		["Dalson's Tears cauldron"] = "Chaudron des Larmes de Dalson",
		["Diseased Grizzlies"] = "Grizzlys malades",
		["Dredge Crushers dig further west; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "Les Écraseurs térébrants creusent plus à l'ouest ; les Pinceurs Cinglepierre, Écorcheurs Cinglepierre et Traqueuses des rochers chassent sur les mêmes sables.",
		["Dredge Strikers dig in the dunes north-west of the hold; Stonelash Scorpids and Sand Skitterers roam all around."] = "Les Frappeurs térébrants creusent les dunes au nord-ouest du fort ; les Scorpides Cinglepierre et les Glisseuses du sable rôdent tout autour.",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Se termine auprès de {npc:9298} au {zone:1452} : gardez-la",
		["Escort {npc:9999}"] = "Escorter {npc:9999}",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Felstone Field cauldron"] = "Chaudron du Champ de Felstone",
		["Fly from Gadgetzan to Marshal's Refuge. {npc:8737}'s hut stands at the Lakkari Tar Pits, west of the refuge; J.D.\n{npc:9997}'s friend {npc:9999} has gone missing."] = "Envolez-vous de Gadgetzan au Refuge des Marshal. La cabane de {npc:8737} se dresse aux Fosses de goudron de Lakkari, à l'ouest du refuge ; J.D.\n{npc:9999}, l'ami de {npc:9997}, a disparu.",
		["Fly to Everlook"] = "Envolez-vous vers Long-Guet",
		["Fly to Gadgetzan"] = "Envolez-vous pour Gadgetzan",
		["Fly to Light's Hope Chapel"] = "Envolez-vous vers la chapelle de l'Espoir de Lumière",
		["Fly to Marshal's Refuge"] = "Envolez-vous vers le Refuge des Marshal",
		["Fly to Rut'theran Village"] = "Envolez-vous vers le village de Rut'theran",
		["Fly to Southshore"] = "Envolez-vous pour Austrivage",
		["Fly to Theramore"] = "Volez jusqu'à Theramore",
		["Follow the road south-west out of the pass to Cenarion Hold. {npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Suivez la route vers le sud-ouest à la sortie du col jusqu'au Fort cénarien. {npc:15189} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
		["For Chillwind Camp: keep it"] = "Pour le Camp du Noroît : gardez-la",
		["For the druids of {zone:1457}: keep it"] = "Pour les druides de {zone:1457} : gardez-la",
		["For {zone:1448}: keep it"] = "Pour {zone:1448} : gardez-la",
		["For {zone:1451}: keep it"] = "Pour {zone:1451} : gardez-la",
		["For {zone:1453}: keep it"] = "Pour {zone:1453} : gardez-la",
		["From Rut'theran Village, fly to {object:152576}."] = "Depuis Rut'theran, envolez-vous vers {object:152576}.",
		["From Theramore, ride west into the {zone:1413} and north up the coast to Ratchet."] = "Depuis Theramore, partez à l'ouest dans {zone:1413} puis au nord le long de la côte jusqu'à Cabestan.",
		["Gadgetzan"] = "Gadgetzan",
		["Gadgetzan flight master"] = "Maître de vol de Gadgetzan",
		["Gahrron's Withering cauldron"] = "Chaudron de la Flétrissure de Gahrron",
		["Group 28 · {zone:1422}, {zone:1423} & {zone:1444}"] = "Groupe 28 · {zone:1422}, {zone:1423} & {zone:1444}",
		["Hearthglen overlook"] = "Point de vue sur Âtreval",
		["Horgus' skull lies at Blackwood Lake and Marduk's sword in the Infectis Scar, each where ghosts fight; grown Plaguehounds hunt the plains between."] = "Le crâne d'Horgus se trouve au Lac de Noirbois et l'épée de Marduk dans la Balafre infecte, chacun là où des fantômes se battent ; des chiens pestiférés adultes chassent dans les plaines entre les deux.",
		["If you skipped The {item:9328}, grind here to level 56.89 to stay on the route's plan."] = "Si vous avez sauté la quête du {item:9328}, tuez des monstres ici jusqu'au niveau 56.89 pour rester dans le plan de la route.",
		["Inside"] = "À l'intérieur",
		["Lakkari Tar Pits: kill these as you meet them"] = "Fosses de goudron de Lakkari : tuez-les au fur et à mesure",
		["Lead {npc:9999} north to Marshal's Refuge. When he faints, use {item:11804} on him to wake him."] = "Escortez {npc:9999} au nord jusqu'au Refuge des Marshal. Quand il s'évanouit, utilisez {item:11804} sur lui pour le réveiller.",
		["Level 56.89"] = "Niveau 56.89",
		["Light's Hope Chapel"] = "Chapelle de l'Espoir de Lumière",
		["Listen to his story"] = "Écouter son histoire",
		["Mark {npc:10902} with the {item:12815}"] = "Marquer {npc:10902} avec la {item:12815}",
		["Mark {npc:10903} with the {item:12815}"] = "Marquer {npc:10903} avec la {item:12815}",
		["Mark {npc:10904} with the {item:12815}"] = "Marquer {npc:10904} avec la {item:12815}",
		["Mark {npc:10905} with the {item:12815}"] = "Marquer {npc:10905} avec la {item:12815}",
		["Marshal's Refuge"] = "Refuge des Marshal",
		["More watches"] = "Encore des montres",
		["Northern Pylon"] = "Le Pylône nord",
		["On {npc:7583}"] = "Sur {npc:7583}",
		["Plaguewood: kill these as you meet them"] = "Pestebois : tuez-les au fur et à mesure",
		["Portal to {zone:1438}"] = "Portail vers {zone:1438}",
		["Radley and Durgen"] = "Radley et Durgen",
		["Ranshalla in {zone:1452}: keep it"] = "Ranshalla au {zone:1452} : gardez-la",
		["Ratchet"] = "Cabestan",
		["Ratchet flight master"] = "Maître de vol de Cabestan",
		["Ride back south to the camp."] = "Retournez au camp, au sud.",
		["Ride down the ramp into the crater: {npc:9619} camps at its foot."] = "Descendez la rampe dans le cratère : {npc:9619} campe à son pied.",
		["Ride east to Fire Plume Ridge, climb it and use {npc:10541} at the lava vents near the top."] = "Partez à l'est jusqu'à la Crête de la Fournaise, grimpez-y et utilisez {npc:10541} aux bouches de lave près du sommet.",
		["Ride east to the Hive'Ashi tower in Southwind Village; climb it and kill the ambushers that rise for the encrusted object."] = "Partez à l'est jusqu'à la tour de la Ruche'Ashi au Village de Sudevent ; grimpez-y et tuez les embusqués qui surgissent pour l'objet incrusté.",
		["Ride east to the border river: {npc:1855} lives in a small hut on the bank."] = "Allez à l'est jusqu'à la rivière frontalière : {npc:1855} vit dans une petite cabane sur la rive.",
		["Ride east to {npc:13220}."] = "Chevauchez vers l'est jusqu'à {npc:13220}.",
		["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "Chevauchez vers le nord par le côté est jusqu'au plateau des gorilles. {npc:9622}, un gorille de niveau 55, se tient dans sa grotte la plus profonde : éliminez d'abord les gorilles de l'entrée.",
		["Ride north to Terrordale. {npc:12384} lives in the ruined hut, and his receipt book lies in the ruined inn nearby.\n{npc:11140} stands by {npc:12384}' hut in Terrordale."] = "Partez au nord jusqu'à Val-Terreur. {npc:12384} vit dans la cabane en ruine, et son carnet de reçus se trouve dans l'auberge en ruine voisine.\n{npc:11140} se tient près de la cabane de {npc:12384} à Val-Terreur.",
		["Ride north up the road to the Northridge lumber mill; {npc:11610} hides at the camp's edge."] = "Remontez la route vers le nord jusqu'au Camp de bûcherons de la Crête du nord ; {npc:11610} se cache en bordure du camp.",
		["Ride north-west to Quel'Lithien Lodge, at the edge of the Plaguewood."] = "Partez au nord-ouest jusqu'au Gîte de Quel'Lithien, à la lisière du Pestebois.",
		["Ride north-west to the Dalson farm. The diary lies in the barn; a wandering skeleton carries the outhouse key, and {npc:10836} waits in the outhouse with the cabinet key."] = "Allez au nord-ouest jusqu'à la ferme des Dalson. Le journal est dans la grange ; un squelette errant porte la clé des latrines, et {npc:10836} attend dans les latrines avec la clé de l'armoire.",
		["Ride out of the crater's north-western pass into {zone:1451} and on to Cenarion Hold. {npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Sortez du cratère par le col nord-ouest pour entrer en {zone:1451} et continuez jusqu'au Fort cénarien. {npc:15189} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
		["Ride south to Gahrron's Withering, where {npc:11078} guards the cauldron."] = "Partez au sud jusqu'à la Flétrissure de Gahrron, où {npc:11078} garde le chaudron.",
		["Ride south-west to the camp."] = "Retournez au camp, au sud-ouest.",
		["Ride south-west to {npc:7771}'s camp at the Broken Pillar."] = "Partez au sud-ouest jusqu'au camp de {npc:7771}, au Pilier brisé.",
		["Ride west along the road to the hot springs."] = "Suivez la route vers l'ouest jusqu'aux sources chaudes.",
		["Ride west past Marshal's Refuge and south down the western side to Golakka Hot Springs: {npc:10302} the goblin sits by the water."] = "Partez à l'ouest au-delà du Refuge des Marshal puis au sud par le côté ouest jusqu'aux Sources de Golakka : {npc:10302} le gobelin est assis au bord de l'eau.",
		["Ride west to Terrordale. Plaguehound Runts, Plaguebats and Carrion Grubs roam its woods; fill the {item:15042} at the big termite mounds and kill the Frenzied Plaguehounds further north."] = "Partez à l'ouest jusqu'à Val-Terreur. Des chiens pestiférés chétifs, des chauves-souris pestiférées et des larves putrides parcourent ses bois ; remplissez le {item:15042} aux grandes termitières et tuez les chiens pestiférés frénétiques plus au nord.",
		["Rut'theran Village"] = "Village de Rut'theran",
		["Skeletal Flayers and Slavering Ghouls roam the fields north of the camp; all the Scourge here drop Scourgestones.\nCareful: These undead notice you from far away, and other undead nearby join the fight when one is pulled.\nCareful: The {npc:10411} (3 spawns, 15 min respawn) turns invisible when out of combat and calls in Rockwing Gargoyles once a fight starts."] = "Des Écorcheurs squelettes et des Goules écumantes parcourent les champs au nord du camp ; tout le Fléau ici laisse tomber des Pierres du Fléau.\nAttention : ces morts-vivants vous repèrent de loin, et les autres morts-vivants proches se joignent au combat quand vous en attirez un.\nAttention : l'{npc:10411} (3 apparitions, réapparition en 15 min) devient invisible hors combat et appelle des Gargouilles Aile-de-roc dès qu'un combat commence.",
		["Sorrow Hill: kill these as you meet them"] = "Colline des chagrins : tuez-les au fur et à mesure",
		["Southwind Village"] = "Village de Sudevent",
		["Take the boat to the mainland and ride north-east to {npc:14637}'s camp by the {object:152574}."] = "Prenez le bateau pour le continent et partez au nord-est jusqu'au camp de {npc:14637}, près de {object:152574}.",
		["Tar Beasts wallow in the Lakkari Tar Pits; the fire elementals of Fire Plume Ridge in the middle carry the ash; the Gorishi wasps of the Slithering Scar in the south carry the gland. Every creature in the crater can drop {item:11018}.\nCareful: Gorishi Workers that drop below 45% health have a 50% chance to call for help from allies within 25 yd."] = "Les bêtes du goudron se vautrent dans les Fosses de goudron de Lakkari ; les élémentaires de feu de la Crête de la Fournaise, au centre, portent les cendres ; les guêpes Gorishi de la Balafre sinueuse, au sud, portent les glandes. Toutes les créatures du cratère peuvent laisser tomber {item:11018}.\nAttention : les ouvriers Gorishi qui passent sous 45 % de vie ont 50 % de chances d'appeler à l'aide leurs alliés à moins de 25 m.",
		["Ten {item:11040} from the {item:11020}"] = "Dix {item:11040} tirées de la {item:11020}",
		["Thalanaar flight master"] = "Maître de vol de Thalanaar",
		["The Andorhal watchtowers"] = "Les tours de guet d'Andorhal",
		["The Forgotten Coast: kill these as you meet them"] = "La Côte oubliée : tuez-les au fur et à mesure",
		["The Hive'Ashi tower"] = "La tour de la Ruche'Ashi",
		["The Marshlands: kill these as you meet them"] = "La Fondrière : tuez-les au fur et à mesure",
		["The Scarlet Crusade"] = "La Croisade écarlate",
		["The Scarlet Medics, Hunters, Knights and Mages patrol the lumber camp and the road toward Hearthglen."] = "Les médecins, chasseurs, chevaliers et mages écarlates patrouillent dans le camp de bûcherons et sur la route d'Âtreval.",
		["The Temple Gardens"] = "Les Jardins du temple",
		["The Undercroft"] = "Le caveau de Zaeldarr",
		["The Writhing Haunt: kill these as you meet them"] = "Le Repaire putride : tuez-les au fur et à mesure",
		["The cauldron sits at Dalson's Tears, north-east of Felstone; its Cauldron Lord stands beside it."] = "Le chaudron se trouve aux Larmes de Dalson, au nord-est du Champ de Felstone ; son Seigneur du Chaudron se tient à côté.",
		["The cauldron sits at the Writhing Haunt, by {npc:10739}' farm."] = "Le chaudron se trouve au Repaire putride, près de la ferme de {npc:10739}.",
		["The crater"] = "Le cratère",
		["The gorillas live on Ironstone Plateau, east of Marshal's Refuge. Keep their pelts for {npc:9619}. Stay out of the deepest cave: {npc:9622} is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds."] = "Les gorilles vivent sur le Plateau de Rochefer, à l'est du Refuge des Marshal. Gardez leurs peaux pour {npc:9619}. N'entrez pas dans la grotte la plus profonde : {npc:9622} est de niveau 55.\nAttention : les gorilles d'Un'Goro (niveau 50-51) appellent à l'aide leurs alliés à moins de 20 m dès qu'ils tombent à 25 % de vie. Une grotte pleine de singes se trouve dans la zone, et y combattre attire de nombreux renforts.",
		["The pelts come after loop 2, on the gorilla plateau"] = "Les peaux viennent après la boucle 2, sur le plateau des gorilles",
		["The portal in Rut'theran Village leads up to {zone:1457}."] = "Le portail de Rut'theran monte vers {zone:1457}.",
		["The shrunken giants roam the {object:152574}; the sea elementals wade along the coast to the west."] = "Les géants rapetissés errent autour de {object:152574} ; les élémentaires marins pataugent le long de la côte à l'ouest.",
		["The tortured druids and sentinels haunt the ruined village south-west of {npc:13220}."] = "Les Druides torturés et les Sentinelles torturées hantent le village en ruine au sud-ouest de {npc:13220}.",
		["The wooden sign beside {npc:9997}"] = "Le panneau en bois à côté de {npc:9997}",
		["Umber in {zone:1450}: keep it"] = "Umber à {zone:1450} : gardez-la",
		["Upstairs"] = "À l'étage",
		["Use the {item:12627} by the grain silos to draw out Temporal Parasites. {quest:5154} is one of the musty tomes in the town hall. Every skeleton in town drops {quest:5537}."] = "Utilisez le {item:12627} près des silos à grain pour faire sortir les Parasites temporels. {quest:5154} est l'un des vieux tomes de l'hôtel de ville. Tous les squelettes de la ville lâchent des {quest:5537}.",
		["Use the {item:12815} at the foot of each of the four watchtowers around the edge of Andorhal, north of the camp."] = "Utilisez la {item:12815} au pied de chacune des quatre tours de guet en bordure d'Andorhal, au nord du camp.",
		["Walk into Timbermaw Hold and take the {zone:1450} branch of the tunnel to Nighthaven."] = "Entrez dans le Repaire des Grumegueules et prenez la branche du tunnel vers {zone:1450} jusqu'à Havrenuit.",
		["Writhing Haunt cauldron"] = "Chaudron du Repaire putride",
		["grind on {npc:11740}"] = "tuez en boucle : {npc:11740}",
		["{item:11478}; below ground"] = "{item:11478} ; sous terre",
		["{item:11479}; below ground"] = "{item:11479} ; sous terre",
		["{item:11480}; below ground"] = "{item:11480} ; sous terre",
		["{item:11834} on the way"] = "{item:11834} en chemin",
		["{item:12894}, at the monument"] = "{item:12894}, au monument",
		["{item:12954} lies in the town hall of Hearthglen, west of {npc:1855}: the Scarlet guards stand close together."] = "{item:12954} se trouve dans l'hôtel de ville d'Âtreval, à l'ouest de {npc:1855} : les gardes écarlates s'y tiennent serrés.",
		["{item:12954}; inside"] = "{item:12954} ; à l'intérieur",
		["{item:12955} lies east of the barn at Gahrron's Withering."] = "{item:12955} se trouve à l'est de la grange de la Flétrissure de Gahrron.",
		["{item:12956}; underwater"] = "{item:12956} ; sous l'eau",
		["{item:13853} on the way"] = "{item:13853} en chemin",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal."] = "{npc:10667} attend dans l'auberge en ruine, à l'ouest d'Andorhal.",
		["{npc:10739} stands by the farm at the Writhing Haunt, north-east of the fields."] = "{npc:10739} se tient près de la ferme du Repaire putride, au nord-est des champs.",
		["{npc:10778}'s ghost wanders by the farmhouse of Felstone Field, west of Dalson's Tears; her parcel lies inside."] = "Le fantôme de {npc:10778} erre près de la ferme du Champ de Felstone, à l'ouest des Larmes de Dalson ; son colis se trouve à l'intérieur.",
		["{npc:10878} and {npc:7740} stand by the Temple of the Moon; fill {item:11682} at the moonwell inside."] = "{npc:10878} et {npc:7740} se tiennent près du temple de la Lune ; remplissez {item:11682} au puits de lune à l'intérieur.",
		["{npc:10927}'s farmhouse stands on the hill east of the camp; {npc:10936}'s monument is just north of it."] = "La ferme de {npc:10927} se dresse sur la colline à l'est du camp ; le monument de {npc:10936} est juste au nord.",
		["{npc:11075} guards the cauldron in Felstone Field, west of Andorhal."] = "{npc:11075} garde le chaudron du Champ de Felstone, à l'ouest d'Andorhal.",
		["{npc:11613} walks the Northridge camp east of {npc:11610}; {npc:11611} guards the tower at Hearthglen's southern approach.\nCareful: Guards stand at the tower's base and one more circles it on patrol. Clear them before you engage Durgen so they don't join the fight."] = "{npc:11613} arpente le camp de la Crête du nord, à l'est de {npc:11610} ; {npc:11611} garde la tour à l'approche sud d'Âtreval.\nAttention : des gardes se tiennent au pied de la tour et un autre en fait le tour en patrouille. Éliminez-les avant d'engager Durgen pour qu'ils ne se joignent pas au combat.",
		["{npc:11741} walks around here: look inside the circle on the map"] = "{npc:11741} se promène par ici : cherchez dans le cercle sur la carte",
		["{npc:11886} is elite: grouping up is advised"] = "{npc:11886} est un élite : mieux vaut être en groupe",
		["{npc:17082}, at the Alliance tents"] = "{npc:17082}, aux tentes de l'Alliance",
		["{npc:1833} along the way to {npc:11610}"] = "{npc:1833} sur le chemin de {npc:11610}",
		["{npc:1833} on the way"] = "{npc:1833} en chemin",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} est un élite de niveau 61",
		["{npc:1852} is elite: grouping up is advised. He guards his phylactery in the middle of Andorhal.\nSmall lockboxes lie in the rubble all over Andorhal; each holds a watch.\nCareful: Ghouls and skeletons usually stand next to the boxes and attack when you come close. Searing ghouls also hurt anyone nearby and will break stealth."] = "{npc:1852} est élite : mieux vaut être en groupe. Il garde son phylactère au milieu d'Andorhal.\nDe petits coffrets reposent dans les décombres partout dans Andorhal ; chacun contient une montre.\nAttention : des goules et des squelettes se tiennent souvent près des coffrets et attaquent quand vous approchez. Les goules brûlantes blessent aussi tout ce qui est à proximité et rompent le camouflage.",
		["{npc:5411} in Gadgetzan: keep it"] = "{npc:5411} à Gadgetzan : gardez-la",
		["{npc:5594}, inside"] = "{npc:5594}, à l'intérieur",
		["{npc:5901}, on the coast north of town"] = "{npc:5901}, sur la côte au nord de la ville",
		["{npc:7740}: keep it for Gadgetzan"] = "{npc:7740} : gardez-la pour Gadgetzan",
		["{npc:7775}'s camp lies north of the {object:152574}. He sells the {item:11243} once he has his bait."] = "Le camp de {npc:7775} se trouve au nord de {object:152574}. Il vend le {item:11243} une fois qu'il a son appât.",
		["{npc:7900}: keep it for {zone:1446}"] = "{npc:7900} : gardez-la pour {zone:1446}",
		["{npc:8496}: keep it for Un'Goro; inside"] = "{npc:8496} : gardez-la pour Un'Goro ; à l'intérieur",
		["{npc:8598}, 170 yd north-east"] = "{npc:8598}, à 170 m au nord-est",
		["{npc:9047}, in the Cenarion Enclave"] = "{npc:9047}, dans l'Enclave cénarienne",
		["{npc:9117}, below ground"] = "{npc:9117}, sous terre",
		["{npc:9299} in Gadgetzan: keep it"] = "{npc:9299} à Gadgetzan : gardez-la",
		["{npc:9299} waits at the graveyard just east of town; the gravestone stands nearby."] = "{npc:9299} attend au cimetière juste à l'est de la ville ; la pierre tombale se trouve à proximité.",
		["{npc:9684}'s lair lies in the jungle north of {npc:9619}, below the eastern cliffs: use {item:11568} there. {npc:9684} is level 56: start at full health."] = "Le repaire de {npc:9684} se trouve dans la jungle au nord de {npc:9619}, sous les falaises est : utilisez-y la {item:11568}. {npc:9684} est de niveau 56 : commencez avec toute votre vie.",
		["{npc:9999} sits on the south-east slope of Fire Plume Ridge, in the middle of the crater."] = "{npc:9999} est assis sur le versant sud-est de la Crête de la Fournaise, au centre du cratère.",
		["{object:175894}, inside"] = "{object:175894}, à l'intérieur",
		["{object:175924}, in the farmhouse; inside"] = "{object:175924}, dans la ferme ; à l'intérieur",
		["{object:177667}, below ground"] = "{object:177667}, sous terre",
		["{quest:3444} is in Ratchet"] = "{quest:3444} se trouve à Cabestan",
		["{quest:5058}, inside"] = "{quest:5058}, à l'intérieur",
		["{quest:5210}, at Light's Hope Chapel: keep it"] = "{quest:5210}, à la chapelle de l'Espoir de Lumière : gardez-la",
		["{quest:6762} in {zone:1450}: keep it"] = "{quest:6762} à {zone:1450} : gardez-la",
		["{zone:1423}: kill these as you meet them"] = "{zone:1423} : tuez-les au fur et à mesure",
