} end)()
t.guides["groupe-alliance/31-silithus"] = (function() return {
		["Boat to {object:3204}"] = "Bateau pour {object:3204}",
		["Chromie in Andorhal: keep it"] = "Chromie à Andorhal : gardez-la",
		["Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels."] = "Chacun à son rythme : ce qui est déjà fait se coche tout seul, le guide reprend où vous en êtes. En groupe ? L'XP de groupe est meilleure à 4 niveaux d'écart ou moins.",
		["Fly from Marshal's Refuge to Ratchet."] = "Envolez-vous du Refuge des Marshal à Cabestan.",
		["Fly to Light's Hope Chapel"] = "Envolez-vous vers la chapelle de l'Espoir de Lumière",
		["Fly to {zone:1453}"] = "Volez jusqu'à {zone:1453}",
		["For {npc:10778}: keep it"] = "Pour {npc:10778} : gardez-la",
		["Group 29 · {zone:1423}"] = "Groupe 29 · {zone:1423}",
		["Its jars are filled on the next Un'Goro visit"] = "Ses pots se remplissent lors de la prochaine visite à Un'Goro",
		["Light's Hope Chapel"] = "Chapelle de l'Espoir de Lumière",
		["Ratchet"] = "Cabestan",
		["Ride north to the Plaguewood's north-eastern edge.\nCareful: The trolls along the path to Zul'Mashar are level 57-59. They run away at low health and call for help, so they often bring adds with them."] = "Partez au nord jusqu'à la lisière nord-est du Pestebois.\nAttention : les trolls sur le chemin de Zul'Mashar sont de niveau 57-59. Ils fuient quand leur vie est basse et appellent à l'aide, si bien qu'ils ramènent souvent des renforts.",
		["Ride on north to Chillwind Camp and fly to Light's Hope Chapel."] = "Continuez au nord jusqu'au Camp du Noroît et envolez-vous vers la chapelle de l'Espoir de Lumière.",
		["Ride south-west to the Undercroft. The mound of dirt lies inside. {npc:11886} is elite: grouping up is advised.\nCareful: About four non-elite adds come with Mercutio. They walk to the grave instead of appearing on the spot."] = "Partez au sud-ouest jusqu'au caveau de Zaeldarr. Le tas de terre se trouve à l'intérieur. {npc:11886} est un élite : il est conseillé de vous grouper.\nAttention : environ quatre renforts non élites accompagnent Mercutio. Ils marchent jusqu'à la tombe au lieu d'apparaître sur place.",
		["Scourge Champions"] = "Champions du Fléau",
		["Scourge Champions (59) roam the Noxious Glade, north of Light's Hope Chapel. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants. Pull them one at a time.\nThe Champions drop Fetid Skulls, which the game does not count: their tooltip shows nothing. Right-click the {item:13156} in the bags with a skull there: the skull becomes a {item:13155} or crumbles to {item:13159}. The skull line of this step counts the Resonating Skulls."] = "Des champions du Fléau (59) errent dans la Clairière nocive, au nord de la chapelle de l'Espoir de Lumière. Passez le {item:13156} de {npc:11063} au-dessus de chacun de ceux que vous tuez : les crânes qui résonnent sont ceux qu'il veut. Attirez-les un par un.\nLes champions laissent des Crânes fétides, que le jeu ne compte pas : leur infobulle n'affiche rien. Clic droit sur {item:13156} dans les sacs, avec un crâne fétide dedans : le crâne devient {item:13155} ou tombe en {item:13159}. La ligne des crânes de cette étape compte les crânes résonants.",
		["Take the Deeprun Tram to {zone:1455}."] = "Prenez le Tram des profondeurs jusqu'à {zone:1455}.",
		["Take the boat from Ratchet to {object:3204} and fly to {zone:1453}."] = "Prenez le bateau de Cabestan à {object:3204} et envolez-vous vers {zone:1453}.",
		["The Undercroft"] = "Le caveau de Zaeldarr",
		["Tram to {zone:1455}"] = "Tram pour {zone:1455}",
		["{item:13155}, from the Scourge Champions"] = "{item:13155}, sur les Champions du Fléau",
		["{item:14613}, from {npc:11886}"] = "{item:14613}, sur {npc:11886}",
		["{npc:332}, in SI:7"] = "{npc:332}, au SI:7",
		["{npc:3520}, who walks the canals"] = "{npc:3520}, qui se promène le long des canaux",
		["{npc:8496}, inside"] = "{npc:8496}, à l'intérieur",
		["{object:3204} flight master"] = "Maître de vol de {object:3204}",
		["{quest:6184} at Chillwind Camp: keep it"] = "{quest:6184} au Camp du Noroît : gardez-la",
		["{zone:1455} flight master"] = "Maître de vol de {zone:1455}",
} end)()
t.guides["groupe-alliance/32-silithus-fin"] = (function() return {
